INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_a#17','math',5,2,'u5','','g5_2_math_u5_review_a','unit_review','M5-2-u5-C2',3,'sa','auto','가로 5 cm, 세로 3 cm, 높이 3 cm인 직육면체 모양 캠핑 상자의 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":17,"concept":"M5-2-u5-C2","difficulty":3,"kind":"sa","stem":"가로 5 cm, 세로 3 cm, 높이 3 cm인 직육면체 모양 캠핑 상자의 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["44"],"explanation":["직육면체에는 길이가 같은 모서리가 4개씩 3묶음 있어요.","5 × 4 + 3 × 4 + 3 × 4 = 44예요.","그래서 44 cm예요."],"mis":"M5-2-u5-X07","asset":{"type":"geo","items":[{"w":143.0,"h":99.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[143.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[110,33.0,"sw"],"ㅁ":[33.0,66,"ne"],"ㅇ":[143.0,66,"e"],"ㅂ":[0,99.0,"sw"],"ㅅ":[110,99.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[55.0,107.0],"5 cm"],[[142.5,86.5],"3 cm"],[[92,66.0],"3 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 4 cm, 세로 2 cm, 높이 3 cm인 직육면체 모양 선물 상자의 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["직육면체에는 길이가 같은 모서리가 4개씩 3묶음 있어요.","4 × 4 + 2 × 4 + 3 × 4 = 36이에요.","그래서 36 cm예요."],"asset":{"type":"geo","items":[{"w":110.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[110.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[88,88.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[44.0,96.0],"4 cm"],[[115.0,81.0],"2 cm"],[[70,55.0],"3 cm"]]}],"tag":false}},{"stem":"가로 3 cm, 세로 2 cm, 높이 2 cm인 직육면체 모양 도시락통의 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["직육면체에는 길이가 같은 모서리가 4개씩 3묶음 있어요.","3 × 4 + 2 × 4 + 2 × 4 = 28이에요.","그래서 28 cm예요."],"asset":{"type":"geo","