INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_d#7','sci',5,2,'u3','','g5_2_sci_u3_review_d','unit_review','SC5-2-u3-C18',1,'mc','auto','단열을 이용하는 물건이 아닌 것은 어느 것인가요?',ARRAY['SC5-2-u3-X30']::text[],false,'{"seq":7,"concept":"SC5-2-u3-C18","difficulty":1,"kind":"mc","stem":"단열을 이용하는 물건이 아닌 것은 어느 것인가요?","options":[{"t":"금속 프라이팬","correct":true},{"t":"보온 도시락","mis":"SC5-2-u3-X30"},{"t":"아이스박스","mis":"SC5-2-u3-X30"},{"t":"겹쳐 입은 옷","mis":"SC5-2-u3-X30"}],"explanation":["프라이팬은 열을 전해요.","나머지는 막아요.","프라이팬이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_d#8','sci',5,2,'u3','','g5_2_sci_u3_review_d','unit_review','SC5-2-u3-C19',1,'mc','auto','캠프 장치 대회에서 단열재로 쓰기에 알맞은 재료는 어느 것인가요?',ARRAY['SC5-2-u3-X30']::text[],false,'{"seq":8,"concept":"SC5-2-u3-C19","difficulty":1,"kind":"mc","stem":"캠프 장치 대회에서 단열재로 쓰기에 알맞은 재료는 어느 것인가요?","options":[{"t":"솜","correct":true},{"t":"구리판","mis":"SC5-2-u3-X30"},{"t":"알루미늄 캔","mis":"SC5-2-u3-X30"},{"t":"금속 국자","mis":"SC5-2-u3-X30"}],"explanation":["솜은 열을 막아요.","금속은 열이 잘 가요.","솜이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_d#9','sci',5,2,'u3','','g5_2_sci_u3_review_d','unit_review','SC5-2-u3-C2',2,'ox','auto','햇빛반 캠프 일지 ①에서 물통 속 물이 텐트 안 공기보다 온도가 높아요.',ARRAY['SC5-2-u3-X04']::text[],false,'{"seq":9,"concept":"SC5-2-u3-C2","difficulty":2,"kind":"ox","stem":"햇빛반 캠프 일지 ①에서 물통 속 물이 텐트 안 공기보다 온도가 높아요.","answer":"O","reason_options":[{"t":"12.0 °C가 6.5 °C보다 크기 때문에","correct":true},{"t":"공기는 언제나 물보다 따뜻하기 때문에","mis":"SC5-2-u3-X04"}],"mis":"SC5-2-u3-X04","explanation":["숫자를 견줘요.","12.0이 더 커요.","물이 더 높아요."],"asset":{"type":"passage","lines":["캠프 첫날, 이름표에 열 변색 붙임딱지를 붙였다. 손을 대면 색이 바뀌었다.","텐트 안 공기 — 알코올 온도계: 6.5 °C","물통 속 물 — 탐침 온도계: 12.0 °C","나무 의자 표면 — 적외선 온도계: 3.8 °C","모둠장 은찬: 「느낌 말고 숫자로 적자.」"],"title":"① 첫날 — 이름표와 온도 재기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_d#10','sci',5,2,'u3','','g5_2_sci_u3_review_d','unit_review','SC5-2-u3-C5',2,'mc','auto','햇빛반 캠프 일지 ②의 결과를 바르게 정리한 것은 어느 것인가요?',ARRAY['SC5-2-u3-X09','SC5-2-u3-X10','SC5-2-u3-X13']::text[],false,'{"seq":10,"concept":"SC5-2-u3-C5","difficulty":2,"kind":"mc","stem":"햇빛반 캠프 일지 ②의 결과를 바르게 정리한 것은 어느 것인가요?","options":[{"t":"코코아는 낮아지고 우유 팩은 높아져 결국 같아졌다","correct":true},{"t":"코코아만 낮아지고 우유 팩은 그대로였다","mis":"SC5-2-u3-X09"},{"t":"두 온도는 끝까지 같아지지 않았다","mis":"SC5-2-u3-X10"},{"t":"변화는 처음과 끝이 같은 빠르기였다","mis":"SC5-2-u3-X13"}],"explanation":["둘 다 변했어요.","처음엔 크게요.","같아졌어요."],"asset":{"type":"passage","lines":["따뜻한 코코아 컵 속에 차가운 우유 팩을 넣고 온도를 쟀다.","0분 — 코코아 50 °C · 우유 팩 10 °C","4분 — 코코아 40 °C · 우유 팩 22 °C","8분 — 코코아 34 °C · 우유 팩 28 °C","12분 — 코코아 31 °C · 우유 팩 31 °C"],"title":"② 첫날 저녁 — 코코아와 우유 팩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_d#11','sci',5,2,'u3','','g5_2_sci_u3_review_d','unit_review','SC5-2-u3-C6',2,'match','auto','캠프 장면과 열이 이동하는 쪽을 이으세요.','{}'::text[],false,'{"seq":11,"concept":"SC5-2-u3-C6","difficulty":2,"kind":"match","stem":"캠프 장면과 열이 이동하는 쪽을 이으세요.","pairs":[{"l":"코코아 속 우유 팩","r":"코코아 → 우유 팩"},{"l":"맨손으로 뭉친 눈","r":"손 → 눈"},{"l":"햇빛반 찬 물통을 쥔 손","r":"손 → 물통"}],"mis":"SC5-2-u3-X11","explanation":["더 따뜻한 쪽을 찾아요.","그쪽에서 나가요.","낮은 쪽으로 가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_d#12','sci',5,2,'u3','','g5_2_sci_u3_review_d','unit_review','SC5-2-u3-C8',2,'mc','auto','철판에 닿지 않은 고기 윗부분까지 익는 까닭이 되는 열의 이동 방식은 어느 것인가요?',ARRAY['SC5-2-u3-X26','SC5-2-u3-X17','SC5-2-u3-X28']::text[],false,'{"seq":12,"concept":"SC5-2-u3-C8","difficulty":2,"kind":"mc","stem":"철판에 닿지 않은 고기 윗부분까지 익는 까닭이 되는 열의 이동 방식은 어느 것인가요?","options":[{"t":"전도","correct":true},{"t":"복사","mis":"SC5-2-u3-X26"},{"t":"대류","mis":"SC5-2-u3-X17"},{"t":"응결","mis":"SC5-2-u3-X28"}],"explanation":["고기는 고체예요.","고기를 따라 올라가요.","전도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_d#13','sci',5,2,'u3','','g5_2_sci_u3_review_d','unit_review','SC5-2-u3-C11',2,'mc','auto','아크릴 통 안 촛불 실험에서 붙임딱지가 변하는 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X21']::text[],false,'{"seq":13,"concept":"SC5-2-u3-C11","difficulty":2,"kind":"mc","stem":"아크릴 통 안 촛불 실험에서 붙임딱지가 변하는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"위 → 가운데 → 아래","correct":true},{"t":"아래 → 가운데 → 위","mis":"SC5-2-u3-X21"},{"t":"세 곳이 한꺼번에","mis":"SC5-2-u3-X21"},{"t":"가운데 → 아래 → 위","mis":"SC5-2-u3-X21"}],"explanation":["데워진 공기는 올라가요.","위부터 따뜻해요.","아래가 마지막이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_d#14','sci',5,2,'u3','','g5_2_sci_u3_review_d','unit_review','SC5-2-u3-C14',2,'mc','auto','나무 그늘이 시원한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X12','SC5-2-u3-X25','SC5-2-u3-X24']::text[],false,'{"seq":14,"concept":"SC5-2-u3-C14","difficulty":2,"kind":"mc","stem":"나무 그늘이 시원한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"나뭇잎이 햇빛을 가려 복사로 오는 열이 줄어서","correct":true},{"t":"나무가 냉기를 내뿜어서","mis":"SC5-2-u3-X12"},{"t":"그늘에는 공기가 없어서","mis":"SC5-2-u3-X25"},{"t":"그늘 땅이 스스로 열을 만들어서","mis":"SC5-2-u3-X24"}],"explanation":["나뭇잎이 가려요.","오는 열이 줄어요.","시원해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_d#15','sci',5,2,'u3','','g5_2_sci_u3_review_d','unit_review','SC5-2-u3-C16',2,'match','auto','화덕 피자가 열을 받는 곳과 방식을 이으세요.','{}'::text[],false,'{"seq":15,"concept":"SC5-2-u3-C16","difficulty":2,"kind":"match","stem":"화덕 피자가 열을 받는 곳과 방식을 이으세요.","pairs":[{"l":"뜨거운 돌판","r":"전도"},{"l":"도는 뜨거운 공기","r":"대류"},{"l":"벽과 불빛","r":"복사"}],"mis":"SC5-2-u3-X28","explanation":["돌판은 닿아요.","공기는 움직여요.","불빛은 빛이에요."],"asset":{"type":"passage","lines":["돌로 만든 화덕에 장작을 피우고 피자를 넣었다.","피자 바닥은 뜨거운 돌판에 닿아 있었다.","화덕 안 뜨거운 공기가 돌았고, 벽과 불빛도 피자를 데웠다."],"title":"⑥ 셋째 날 낮 — 화덕 피자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_d#16','sci',5,2,'u3','','g5_2_sci_u3_review_d','unit_review','SC5-2-u3-C18',2,'match','auto','물건과 막는 열의 이동 방식을 이으세요.','{}'::text[],false,'{"seq":16,"concept":"SC5-2-u3-C18","difficulty":2,"kind":"match","stem":"물건과 막는 열의 이동 방식을 이으세요.","pairs":[{"l":"나무 냄비 받침","r":"전도"},{"l":"문풍지","r":"대류"},{"l":"그늘막","r":"복사"}],"mis":"SC5-2-u3-X31","explanation":["받침은 닿는 열이에요.","문풍지는 공기 흐름이에요.","그늘막은 햇빛이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_d#17','sci',5,2,'u3','','g5_2_sci_u3_review_d','unit_review','SC5-2-u3-C3',3,'mc','auto','텐트 안 공기 온도를 하루 내내 같은 방법으로 보려고 해요. 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X04','SC5-2-u3-X07']::text[],false,'{"seq":17,"concept":"SC5-2-u3-C3","difficulty":3,"kind":"mc","stem":"텐트 안 공기 온도를 하루 내내 같은 방법으로 보려고 해요. 가장 알맞은 것은 어느 것인가요?","options":[{"t":"텐트 안에 알코올 온도계를 걸어 두고 눈높이에서 읽는다","correct":true},{"t":"공기를 손으로 느껴 적는다","mis":"SC5-2-u3-X04"},{"t":"적외선 온도계로 텐트 천만 잰다","mis":"SC5-2-u3-X07"},{"t":"탐침을 땅속에 꽂아 둔다","mis":"SC5-2-u3-X07"}],"explanation":["공기 온도예요.","걸어 둘 수 있어요.","알코올 온도계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_d#18','sci',5,2,'u3','','g5_2_sci_u3_review_d','unit_review','SC5-2-u3-C5',3,'ox','auto','50 °C 코코아와 10 °C 우유 팩의 온도는 50 °C보다 높아지거나 10 °C보다 낮아지지 않고 그 사이에서 같아져요.',ARRAY['SC5-2-u3-X10']::text[],false,'{"seq":18,"concept":"SC5-2-u3-C5","difficulty":3,"kind":"ox","stem":"50 °C 코코아와 10 °C 우유 팩의 온도는 50 °C보다 높아지거나 10 °C보다 낮아지지 않고 그 사이에서 같아져요.","answer":"O","reason_options":[{"t":"높은 쪽은 내려오고 낮은 쪽은 올라가 그 사이에서 만나기 때문에","correct":true},{"t":"우유 팩이 코코아보다 뜨거워질 수 있기 때문에","mis":"SC5-2-u3-X10"}],"mis":"SC5-2-u3-X10","explanation":["높은 쪽은 내려와요.","낮은 쪽은 올라가요.","사이에서 만나요."],"asset":{"type":"passage","lines":["따뜻한 코코아 컵 속에 차가운 우유 팩을 넣고 온도를 쟀다.","0분 — 코코아 50 °C · 우유 팩 10 °C","4분 — 코코아 40 °C · 우유 팩 22 °C","8분 — 코코아 34 °C · 우유 팩 28 °C","12분 — 코코아 31 °C · 우유 팩 31 °C"],"title":"② 첫날 저녁 — 코코아와 우유 팩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_d#19','sci',5,2,'u3','','g5_2_sci_u3_review_d','unit_review','SC5-2-u3-C13',3,'mc','auto','캠프 식당 천장에 달린 냉방기를 켰어요. 식당에서 일어나는 일로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X20','SC5-2-u3-X17','SC5-2-u3-X22']::text[],false,'{"seq":19,"concept":"SC5-2-u3-C13","difficulty":3,"kind":"mc","stem":"캠프 식당 천장에 달린 냉방기를 켰어요. 식당에서 일어나는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"차가운 공기가 내려오고 데워진 공기가 올라가며 식당 전체가 시원해진다","correct":true},{"t":"차가운 공기가 천장에만 머문다","mis":"SC5-2-u3-X20"},{"t":"냉방기의 냉기가 벽을 따라 전도된다","mis":"SC5-2-u3-X17"},{"t":"공기는 움직이지 않고 냉기만 퍼진다","mis":"SC5-2-u3-X22"}],"explanation":["차가운 공기는 내려와요.","데워진 공기는 올라가요.","공기가 돌아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_d#20','sci',5,2,'u3','','g5_2_sci_u3_review_d','unit_review','SC5-2-u3-C16',3,'mc','auto','요리 방법과 주로 이용하는 열의 이동 방식을 바르게 짝지은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X28']::text[],false,'{"seq":20,"concept":"SC5-2-u3-C16","difficulty":3,"kind":"mc","stem":"요리 방법과 주로 이용하는 열의 이동 방식을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"숯불 바비큐 — 복사","correct":true},{"t":"프라이팬 볶음 — 대류","mis":"SC5-2-u3-X28"},{"t":"찜기 만두 — 전도","mis":"SC5-2-u3-X28"},{"t":"국 끓이기 — 복사","mis":"SC5-2-u3-X28"}],"explanation":["숯불은 빛을 내요.","닿지 않아도 와요.","복사예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_d#21','sci',5,2,'u3','','g5_2_sci_u3_review_d','unit_review','SC5-2-u3-C20',3,'ox','auto','햇빛반 캠프 일지 ⑧처럼 장치를 견줄 때 처음 온도와 재는 시간을 같게 한 것은 바른 방법이에요.',ARRAY['SC5-2-u3-X34']::text[],false,'{"seq":21,"concept":"SC5-2-u3-C20","difficulty":3,"kind":"ox","stem":"햇빛반 캠프 일지 ⑧처럼 장치를 견줄 때 처음 온도와 재는 시간을 같게 한 것은 바른 방법이에요.","answer":"O","reason_options":[{"t":"다른 조건이 같아야 장치의 차이만 견줄 수 있기 때문에","correct":true},{"t":"장치마다 조건을 모두 다르게 해야 하기 때문에","mis":"SC5-2-u3-X34"}],"mis":"SC5-2-u3-X34","explanation":["처음 온도가 같아요.","시간도 같아요.","바른 방법이에요."],"asset":{"type":"passage","lines":["같은 온도의 따뜻한 물을 세 장치에 넣고 30분 뒤 다시 쟀다.","가 — 뽁뽁이 두 겹, 뚜껑 덮음: 4 °C 낮아짐","나 — 신문지 한 겹, 뚜껑 없음: 15 °C 낮아짐","다 — 스타이로폼 상자, 뚜껑, 은박지: 2 °C 낮아짐","마지막 영상 — 인공 태양 연구 장치의 단열 이야기"],"title":"⑧ 마지막 날 — 장치 대회와 영상"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_d#22','sci',5,2,'u3','','g5_2_sci_u3_review_d','unit_review','SC5-2-u3-C22',3,'match','auto','열의 이동 방식과 일어나는 곳, 막는 물건을 알맞게 이으세요.','{}'::text[],false,'{"seq":22,"concept":"SC5-2-u3-C22","difficulty":3,"kind":"match","stem":"열의 이동 방식과 일어나는 곳, 막는 물건을 알맞게 이으세요.","pairs":[{"l":"전도 — 고체","r":"주방 장갑"},{"l":"대류 — 액체와 기체","r":"닫은 창문"},{"l":"복사 — 빛","r":"양산"}],"mis":"SC5-2-u3-X31","explanation":["장갑은 닿는 열을 막아요.","창문은 공기 흐름을 막아요.","양산은 햇빛을 막아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_d#23','sci',5,2,'u3','','g5_2_sci_u3_review_d','unit_review','SC5-2-u3-C6',4,'mc','auto','뜨거운 코코아 컵을 두 손으로 감싸 쥐었어요. 일어나는 일을 가장 바르게 말한 것은 어느 것인가요?',ARRAY['SC5-2-u3-X12','SC5-2-u3-X11','SC5-2-u3-X09']::text[],false,'{"seq":23,"concept":"SC5-2-u3-C6","difficulty":4,"kind":"mc","stem":"뜨거운 코코아 컵을 두 손으로 감싸 쥐었어요. 일어나는 일을 가장 바르게 말한 것은 어느 것인가요?","options":[{"t":"컵의 열이 손으로 이동해 손은 따뜻해지고 코코아는 조금 식는다","correct":true},{"t":"손의 냉기가 컵으로 가서 코코아가 식는다","mis":"SC5-2-u3-X12"},{"t":"손의 열이 컵으로 가서 코코아가 더 뜨거워진다","mis":"SC5-2-u3-X11"},{"t":"손만 따뜻해지고 코코아의 온도는 그대로이다","mis":"SC5-2-u3-X09"}],"explanation":["컵이 더 뜨거워요.","열이 손으로 와요.","둘 다 변해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_d#24','sci',5,2,'u3','','g5_2_sci_u3_review_d','unit_review','SC5-2-u3-C16',4,'mc','auto','텐트 안 난로 옆에 쇠 국자를 두었어요. 일어나는 일을 열의 이동 방식과 가장 바르게 이은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X14','SC5-2-u3-X12','SC5-2-u3-X25']::text[],false,'{"seq":24,"concept":"SC5-2-u3-C16","difficulty":4,"kind":"mc","stem":"텐트 안 난로 옆에 쇠 국자를 두었어요. 일어나는 일을 열의 이동 방식과 가장 바르게 이은 것은 어느 것인가요?","options":[{"t":"난로 빛을 받은 국자가 데워지고(복사), 그 열이 국자 손잡이로 퍼진다(전도)","correct":true},{"t":"국자 손잡이가 먼저 뜨거워지고 그다음 국자 머리가 데워진다(대류)","mis":"SC5-2-u3-X14"},{"t":"국자의 냉기가 난로로 가서 국자가 데워진다(전도)","mis":"SC5-2-u3-X12"},{"t":"국자는 난로에 닿지 않아 데워지지 않는다","mis":"SC5-2-u3-X25"}],"explanation":["난로 빛을 받아요.","국자를 따라 퍼져요.","복사와 전도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_d#25','sci',5,2,'u3','','g5_2_sci_u3_review_d','unit_review','SC5-2-u3-C20',4,'mc','auto','두 모둠의 장치를 공정하게 견주는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X34','SC5-2-u3-X04']::text[],false,'{"seq":25,"concept":"SC5-2-u3-C20","difficulty":4,"kind":"mc","stem":"두 모둠의 장치를 공정하게 견주는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"같은 온도의 물을 같은 양만큼 넣고 같은 시간 뒤에 같은 온도계로 잰다","correct":true},{"t":"한 모둠은 따뜻한 물, 한 모둠은 차가운 물을 넣는다","mis":"SC5-2-u3-X34"},{"t":"장치의 색깔이 더 예쁜 쪽을 고른다","mis":"SC5-2-u3-X34"},{"t":"한 장치만 재고 다른 장치는 손으로 만져 본다","mis":"SC5-2-u3-X04"}],"explanation":["조건을 같게 해요.","같은 시간에 재요.","공정하게 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u4-C1','sci',5,2,'u4',1,'풍력 발전기와 풍력 발전 모형 — 풍력 발전기는 바람으로 회전 날개를 돌려 에너지를 만듦 · 산 위나 바닷가에서 볼 수 있고 길쭉한 날개가 세 개 · 모형도 회전 날개가 달려 있어 바람이 불면 돌아가고, 바람이 셀수록 빨리 돎',ARRAY['[6과08-02] 재생 에너지의 종류를 조사하고, 에너지를 지속가능하게 이용하는 방법에 관심을 갖는다.']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u4-C2','sci',5,2,'u4',1,'회전 날개를 돌려 전구에 불 켜기 — 입으로 가운데를 세게 불기·빨대로 비스듬히 불기·머리 말리개 바람으로 날개를 돌림 · 날개가 빠르게 돌 때만 전구에 불이 켜짐(날개가 돌아갈 때 불을 켤 에너지가 만들어짐) · 날개에 입술·손을 가까이 대지 않고 머리 말리개에 데지 않게 조심 · 페달 밟기처럼 내 몸으로 에너지를 만드는 방법도 떠올려 봄',ARRAY['[6과08-02] 재생 에너지의 종류를 조사하고, 에너지를 지속가능하게 이용하는 방법에 관심을 갖는다.']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u4-C3','sci',5,2,'u4',2,'자원의 뜻 — 우리가 생활하거나 물건을 생산할 때 이용하는 물·나무·철 같은 원료 · 목마를 때 마시는 물, 책을 만드는 나무, 자동차를 만드는 철',ARRAY['[6과08-01] 우리가 생활에서 이용하는 다양한 자원을 조사하고, 자원의 유한함을 설명할 수 있다.']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u4-C4','sci',5,2,'u4',2,'물·산림·광물 자원의 이용 — 물 자원(마시기·씻기·농사·물건 생산), 산림 자원(목재로 집·가구·종이, 버섯·잣, 생물의 보금자리), 광물 자원(석재·철근으로 건물, 철·구리로 스마트 기기, 석탄으로 에너지, 금·은 장신구) · 이용 카드를 같은 자원끼리 분류함',ARRAY['[6과08-01] 우리가 생활에서 이용하는 다양한 자원을 조사하고, 자원의 유한함을 설명할 수 있다.']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u4-C5','sci',5,2,'u4',2,'자원의 유한성 — 물: 지구의 물 총량은 줄지 않지만 오염된 물이 다시 쓸 수 있게 되기까지 오래 걸려 쓸 수 있는 깨끗한 물은 점점 부족해짐 · 산림: 마구 베거나 숲을 농경지로 바꾸면 다시 자라는 데 오래 걸려 줄어듦 · 광물: 묻혀 있는 양이 한정되고 다시 만들어지기 어려움 · 재활용으로 되쓰는 자원이 있어도 자원이 끝없이 있는 것은 아님',ARRAY['[6과08-01] 우리가 생활에서 이용하는 다양한 자원을 조사하고, 자원의 유한함을 설명할 수 있다.']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u4-C6','sci',5,2,'u4',2,'자원을 아껴 써야 하는 까닭 — 인구가 늘고 편리한 생활을 하려고 자원 사용량이 늘어남 · 한정된 자원을 무분별하게 쓰면 부족해지고, 지나친 사용은 환경오염·기후변화도 부름 · 자원을 조사할 때는 믿을 수 있는 출처인지 확인함',ARRAY['[6과08-01] 우리가 생활에서 이용하는 다양한 자원을 조사하고, 자원의 유한함을 설명할 수 있다.']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u4-C7','sci',5,2,'u4',3,'에너지와 재생 에너지 — 에너지는 생물이 살아가거나 기계를 움직이는 데 필요하며 석탄·석유·태양 빛·바람·물 등 여러 자원에서 얻음 · 태양 빛·바람·물처럼 자연에서 얻고 계속 이용할 수 있는 에너지가 재생 에너지 · 석탄·석유는 쓸수록 줄어 재생 에너지가 아님',ARRAY['[6과08-02] 재생 에너지의 종류를 조사하고, 에너지를 지속가능하게 이용하는 방법에 관심을 갖는다.']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u4-C8','sci',5,2,'u4',3,'재생 에너지의 종류 — 태양 에너지(태양 빛을 많이 쓰고 태양열도 씀 — 태양 전지로 가로등·시계·인공위성), 풍력(바람으로 발전기), 수력(높은 곳에서 낮은 곳으로 떨어지는 물의 흐름), 해양 에너지(밀물과 썰물·파도·바닷물 흐름·온도 차이), 지열 에너지(땅속 깊은 곳의 열 — 사계절 온도가 거의 같아 냉난방에), 바이오 에너지(나무·풀·가축의 분뇨·음식물 쓰레기)',ARRAY['[6과08-02] 재생 에너지의 종류를 조사하고, 에너지를 지속가능하게 이용하는 방법에 관심을 갖는다.']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u4-C9','sci',5,2,'u4',3,'지역에 알맞은 재생 에너지 — 재생 에너지는 날씨와 지형의 영향을 많이 받음 · 바람이 센 섬·바닷가·산 위는 풍력, 햇빛이 강한 곳은 태양 에너지, 가축을 많이 기르는 곳은 바이오 에너지, 물이 세차게 흐르는 골짜기는 수력, 밀물과 썰물이 큰 바다는 해양 에너지 · 지역의 특징을 보고 고름',ARRAY['[6과08-02] 재생 에너지의 종류를 조사하고, 에너지를 지속가능하게 이용하는 방법에 관심을 갖는다.']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u4-C10','sci',5,2,'u4',3,'재생 에너지가 주목받는 까닭과 한계 — 석탄·석유는 양이 한정되고 대기오염·기후변화에 영향을 줌 → 재생 에너지는 자연에서 계속 얻고 환경오염에 영향을 적게 줘 주목받음 · 그러나 늘 일정한 양을 얻기 어렵고 설치 비용이 많이 들며 시설을 지을 때 생태계에 영향을 주기도 함 → 기술 발전이 필요함',ARRAY['[6과08-02] 재생 에너지의 종류를 조사하고, 에너지를 지속가능하게 이용하는 방법에 관심을 갖는다.']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u4-C11','sci',5,2,'u4',4,'지속가능한 에너지 이용 — 지금 세대의 필요를 채우면서 미래 세대가 쓸 에너지도 지키는 것 · 재생 에너지는 계속 쓸 수 있지만 지금은 생산량이 충분하지 않음 · 미래 세대도 깨끗한 에너지를 쓰고 기후변화에 대응하려면 지속가능하게 써야 함',ARRAY['[6과08-02] 재생 에너지의 종류를 조사하고, 에너지를 지속가능하게 이용하는 방법에 관심을 갖는다.']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u4-C12','sci',5,2,'u4',4,'지속가능한 예와 그렇지 않은 예 — 지속가능한 예: 냉난방 적정 온도 유지, 태양 에너지·수력·풍력 이용, 가까운 곳은 걷거나 자전거, 친환경 제품, 절약 캠페인, 여러 나라의 협력 · 그렇지 않은 예: 창문을 연 채 난방, 빈방 조명, 보지 않는 텔레비전, 가까운 거리도 늘 자동차, 석유로 얻어 이산화 탄소 발생, 에너지를 많이 쓰는 기계 · 놀이판의 사다리와 미끄럼틀로 분류함',ARRAY['[6과08-02] 재생 에너지의 종류를 조사하고, 에너지를 지속가능하게 이용하는 방법에 관심을 갖는다.']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u4-C13','sci',5,2,'u4',4,'에너지를 지속가능하게 이용하는 방법 — 세 갈래: 재생 가능한 자원에서 재생 에너지 얻기, 환경을 덜 오염시키고 사용량을 줄이는 친환경 기술(전기차·수소차) 개발, 일상에서 불필요한 에너지 사용 줄이기 · 학교 실천: 이동 수업 때 전등 끄기, 겨울에 교실 문 닫기, 쓰지 않는 전기 기구 플러그 뽑기',ARRAY['[6과08-02] 재생 에너지의 종류를 조사하고, 에너지를 지속가능하게 이용하는 방법에 관심을 갖는다.']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u4-C14','sci',5,2,'u4',5,'효율과 에너지 소비 효율 등급 — 효율이 좋다는 것은 같은 일을 하면서 에너지를 적게 쓰는 것(같은 밝기를 내며 전기를 적게 쓰는 전등) · 에너지 소비 효율 등급은 1~5등급이고 1등급에 가까울수록 효율이 높음 · 전원을 꺼도 플러그를 꽂아 두면 전기가 조금씩 쓰임(대기 전력) — 플러그 뽑기·절전 멀티탭',ARRAY['[6과08-03] 자원과 에너지의 효율적인 이용 방법에 대해 탐색하고, 생활 속에서 실천할 수 있는 다양한 사례를 공유할 수 있다.']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u4-C15','sci',5,2,'u4',5,'자원을 효율적으로 이용하는 방법 — 물: 물 받아 쓰기, 절수 장치, 움직임 센서 수도꼭지, 빗물 저금통 · 산림: 이면지, 손수건·다회용 컵, 전자 영수증, 나무 심고 가꾸기, 목재 제품 고쳐 쓰기 · 광물: 분리배출로 재활용(혼합물의 분리), 대체 자원 개발 · 과대 포장 물건 사지 않기 · 물·산림·광물을 함께 따짐',ARRAY['[6과08-03] 자원과 에너지의 효율적인 이용 방법에 대해 탐색하고, 생활 속에서 실천할 수 있는 다양한 사례를 공유할 수 있다.']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u4-C16','sci',5,2,'u4',5,'에너지를 효율적으로 이용하는 방법 — 1등급에 가까운 제품·LED 조명 쓰기, 절전 기능·플러그 뽑기·알맞은 냉난방 온도 같은 절약 습관, 태양 에너지·지열 에너지 같은 재생 에너지 쓰기, 외벽·지붕·창틀 단열로 열 손실 줄이기 · 효율적으로 쓰면 돈도 아끼고 환경도 지킴',ARRAY['[6과08-03] 자원과 에너지의 효율적인 이용 방법에 대해 탐색하고, 생활 속에서 실천할 수 있는 다양한 사례를 공유할 수 있다.']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u4-C17','sci',5,2,'u4',6,'집 모형 실험 설계 — 크기·모양이 같은 집 모형 두 개 · 둘 다 창문 안쪽에 뽁뽁이 한 장, 한 개에만 한 장 더 붙이고 우드록·색점토로 단열하고 틈을 막음 · 두 집 지붕에 탐침 온도계를 꽂고 미리 데운 같은 손난로를 넣어 5분 데운 뒤, 손난로를 빼고 1분 간격으로 5번 잼 · 탐침 끝은 바닥에 닿지 않게 공기 온도를 재고 뾰족한 끝은 사람을 향하지 않게 · 단열 말고 다른 조건은 같게',ARRAY['[6과08-03] 자원과 에너지의 효율적인 이용 방법에 대해 탐색하고, 생활 속에서 실천할 수 있는 다양한 사례를 공유할 수 있다.']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u4-C18','sci',5,2,'u4',6,'집 모형 결과 해석 — 온도 변화량은 처음 온도에서 5분 뒤 온도를 뺀 값 · 단열한 집이 온도 변화가 더 작음 → 집 안 온도를 잘 지켜 에너지 효율이 더 높음 · 처음 온도가 다르면 마지막 온도가 아니라 변화량으로 견줌',ARRAY['[6과08-03] 자원과 에너지의 효율적인 이용 방법에 대해 탐색하고, 생활 속에서 실천할 수 있는 다양한 사례를 공유할 수 있다.']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u4-C19','sci',5,2,'u4',6,'집에서 에너지를 효율적으로 이용하는 방법 — 열이 빠져나가지 않게 막기: 단열재, 이중창·삼중창, 햇빛 방향에 따라 움직이는 차양, 실내 온도를 지키는 열 교환기, 옥상 정원 · 에너지를 직접 만들기: 태양 빛으로 전기, 땅속 열로 냉난방 · 불 끄는 날(어스아워)처럼 절약을 함께 실천함',ARRAY['[6과08-03] 자원과 에너지의 효율적인 이용 방법에 대해 탐색하고, 생활 속에서 실천할 수 있는 다양한 사례를 공유할 수 있다.']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u4-C20','sci',5,2,'u4',7,'실천 영상 만들고 나누기 — 생활에서 실제로 할 수 있는 방법(양치 컵, 음식 남기지 않기, 분리배출, 쓰지 않는 전원 끄기, 대중교통·자전거)을 주제로 정함 · 감독·대본·촬영·소품 역할을 나누고 장면을 스토리 보드에 글과 그림으로 · 남을 비하하거나 불쾌한 내용·개인 정보는 넣지 않고 안전한 곳에서 찍으며 소품은 재활용품으로 · 공유하고 바르고 고운 말로 댓글, 나부터 꾸준히 실천',ARRAY['[6과08-03] 자원과 에너지의 효율적인 이용 방법에 대해 탐색하고, 생활 속에서 실천할 수 있는 다양한 사례를 공유할 수 있다.']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u4-C21','sci',5,2,'u4',8,'미래 에너지 전문가 — 재생 에너지 전문가: 재생 에너지원을 연구해 더 좋은 태양 전지·풍력 발전기를 만들고, 알맞은 설치 장소를 찾고, 중요성을 알림 · 에너지 하베스팅(수확) 전문가: 새어 나오는 조명 빛, 자동차의 떨림, 뜨거운 물의 열, 걸을 때 누르는 힘, 체온처럼 버려지는 에너지를 모아 쓰는 방법을 연구 · 놀이터 바닥·그네 같은 아이디어',ARRAY['[6과08-02] 재생 에너지의 종류를 조사하고, 에너지를 지속가능하게 이용하는 방법에 관심을 갖는다.']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u4-C22','sci',5,2,'u4',8,'자원과 에너지 정리 — 물·산림·광물 자원은 한정되어 아껴 써야 함 · 재생 에너지·친환경 기술·절약으로 에너지를 지속가능하게 씀 · 1등급 제품·단열·재활용·빗물 재사용으로 자원과 에너지를 효율적으로 쓰고 생활에서 실천함',ARRAY['[6과08-03] 자원과 에너지의 효율적인 이용 방법에 대해 탐색하고, 생활 속에서 실천할 수 있는 다양한 사례를 공유할 수 있다.']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X01','sci',5,'u4',ARRAY['SC5-2-u4-C2']::text[],'회전 날개가 천천히 돌거나 멈춰 있어도 전구에 불이 켜진다고 여긴다','빠르게 돌 때만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X02','sci',5,'u4',ARRAY['SC5-2-u4-C2']::text[],'바람을 약하게, 날개 끝에 불수록 날개가 잘 돌아 불이 잘 켜진다고 여긴다','가운데를 세게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X03','sci',5,'u4',ARRAY['SC5-2-u4-C1']::text[],'풍력 발전기가 바람 없이도 돈다고 여기거나 모형과의 공통점을 겉모습에서만 찾는다','바람으로 날개가 돌아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X04','sci',5,'u4',ARRAY['SC5-2-u4-C2']::text[],'날개에 입술·손을 바짝 대거나 머리 말리개를 몸 가까이 대는 등 안전을 놓친다','입술·손은 멀리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X05','sci',5,'u4',ARRAY['SC5-2-u4-C3']::text[],'자원을 물건을 만드는 원료가 아닌 엉뚱한 것(쓰레기·날씨·기계)으로 여긴다','생활과 생산에 쓰는 원료') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X06','sci',5,'u4',ARRAY['SC5-2-u4-C4']::text[],'자원을 이용하는 모습과 자원의 종류를 바꾸어 분류한다(종이컵을 광물, 석탄을 산림으로)','물 · 나무 · 땅속 광물') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X07','sci',5,'u4',ARRAY['SC5-2-u4-C5']::text[],'물을 쓰면 지구의 물 총량이 줄어든다고 여긴다','총량은 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X08','sci',5,'u4',ARRAY['SC5-2-u4-C5']::text[],'물은 돌고 도니 사람이 쓸 수 있는 깨끗한 물도 줄지 않는다고 여긴다','깨끗해지기까지 오래 걸려요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X09','sci',5,'u4',ARRAY['SC5-2-u4-C5']::text[],'나무는 다시 자라니 마구 베어도 산림 자원이 줄지 않는다고 여긴다','다시 자라는 데 오래') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X10','sci',5,'u4',ARRAY['SC5-2-u4-C5']::text[],'광물 자원은 캐내어 써도 곧 다시 만들어진다고 여긴다','묻힌 양이 한정') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X11','sci',5,'u4',ARRAY['SC5-2-u4-C5','SC5-2-u4-C6']::text[],'재활용·순환되는 사례를 보고 자원이 끝없이 있다고 여긴다','재활용해도 한정') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X12','sci',5,'u4',ARRAY['SC5-2-u4-C6']::text[],'찾은 자료를 출처를 확인하지 않고 그대로 믿고 쓴다','믿을 수 있는 출처') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X13','sci',5,'u4',ARRAY['SC5-2-u4-C7']::text[],'석탄·석유를 재생 에너지로 여기거나 태양 빛·바람도 쓰면 줄어든다고 여긴다','자연에서 계속') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X14','sci',5,'u4',ARRAY['SC5-2-u4-C8']::text[],'재생 에너지 이름과 얻는 방법을 바꾸어 짝짓는다(수력을 밀물과 썰물로, 해양 에너지를 계곡 물로)','떨어지는 물 수력 · 바다 해양') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X15','sci',5,'u4',ARRAY['SC5-2-u4-C8']::text[],'태양 에너지는 태양의 뜨거운 열만 이용한다고 여긴다','빛을 많이 써요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X16','sci',5,'u4',ARRAY['SC5-2-u4-C8']::text[],'지열 에너지를 땅 위 햇볕의 열로 여기거나 땅속 온도가 계절마다 크게 변한다고 여긴다','땅속 깊은 곳 · 사계절 비슷') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X17','sci',5,'u4',ARRAY['SC5-2-u4-C8']::text[],'바이오 에너지의 재료를 놓친다(석탄·쇠붙이라고 여긴다)','식물 · 가축 분뇨 · 음식물 쓰레기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X18','sci',5,'u4',ARRAY['SC5-2-u4-C9']::text[],'지역의 특징과 맞지 않는 재생 에너지를 고른다','그 지역에 많은 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X19','sci',5,'u4',ARRAY['SC5-2-u4-C10']::text[],'재생 에너지는 날씨와 상관없이 늘 같은 양을 얻고 비용·문제가 전혀 없다고 여긴다','날씨 · 비용 · 기술') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X20','sci',5,'u4',ARRAY['SC5-2-u4-C10']::text[],'재생 에너지가 주목받는 까닭을 고갈·오염이 아닌 엉뚱한 것(모양·크기)에서 찾거나 오히려 오염을 많이 낸다고 여긴다','계속 · 깨끗하게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X21','sci',5,'u4',ARRAY['SC5-2-u4-C7','SC5-2-u4-C10']::text[],'석탄·석유를 자연에서 끝없이 얻을 수 있고 환경에도 문제가 없다고 여긴다','쓸수록 줄어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X22','sci',5,'u4',ARRAY['SC5-2-u4-C11']::text[],'지속가능을 지금 세대가 마음껏 쓰는 것으로 여기고 미래 세대를 놓친다','미래 세대도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X23','sci',5,'u4',ARRAY['SC5-2-u4-C12']::text[],'에너지를 낭비하는 예를 지속가능하게 이용하는 예로 분류한다','불필요하게 쓰나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X24','sci',5,'u4',ARRAY['SC5-2-u4-C13']::text[],'지속가능하게 이용하는 방법을 한 가지로만 좁힌다(절약만, 또는 재생 에너지만)','재생 · 기술 · 절약 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X25','sci',5,'u4',ARRAY['SC5-2-u4-C14']::text[],'전원을 끄면 플러그를 꽂아 두어도 전기가 전혀 쓰이지 않는다고 여긴다','꽂혀 있으면 조금씩') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X26','sci',5,'u4',ARRAY['SC5-2-u4-C14']::text[],'효율이 높다는 것을 에너지를 많이 쓰거나 세게 작동하는 것으로 여긴다','같은 일에 적게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X27','sci',5,'u4',ARRAY['SC5-2-u4-C14']::text[],'에너지 소비 효율 등급 숫자가 클수록 효율이 높다고 여긴다','1등급에 가까울수록') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X28','sci',5,'u4',ARRAY['SC5-2-u4-C15']::text[],'자원을 낭비하는 행동(과대 포장 구입·일회용품·짧은 거리 자동차·물 틀어 놓기)을 효율적인 방법으로 고른다','덜 쓰고 다시 쓰기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X29','sci',5,'u4',ARRAY['SC5-2-u4-C16']::text[],'에너지 생산을 줄이고 사용을 늘리면 효율적이라고 여긴다','같은 일에 덜 쓰기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X30','sci',5,'u4',ARRAY['SC5-2-u4-C15']::text[],'물·산림·광물 자원을 아끼는 방법을 서로 바꾸어 짝짓는다(빗물 저금통을 광물, 분리배출을 물)','어떤 자원을 아끼나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X31','sci',5,'u4',ARRAY['SC5-2-u4-C17']::text[],'집 모형 실험에서 같게 할 조건(크기·손난로·재는 시간)을 다르게 한다','단열만 다르게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X32','sci',5,'u4',ARRAY['SC5-2-u4-C17']::text[],'탐침 끝을 바닥에 닿게 하거나 손난로를 뺄 때 문을 활짝 여는 등 측정을 흐트러뜨린다','공기 온도 · 살짝 열기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X33','sci',5,'u4',ARRAY['SC5-2-u4-C18']::text[],'온도 변화가 더 큰 집이 에너지 효율이 더 높다고 여긴다','덜 변한 집') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X34','sci',5,'u4',ARRAY['SC5-2-u4-C18']::text[],'처음 온도가 다른데 마지막 온도만 견주거나 온도 변화량을 잘못 구한다','처음 − 나중') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X35','sci',5,'u4',ARRAY['SC5-2-u4-C19']::text[],'열을 막는 방법과 에너지를 만드는 방법을 바꾸어 분류한다(이중창이 전기를 만든다고)','막기 · 만들기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X36','sci',5,'u4',ARRAY['SC5-2-u4-C19']::text[],'단열재가 스스로 열을 내 집을 데운다고 여긴다','막아서 지킬 뿐') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X37','sci',5,'u4',ARRAY['SC5-2-u4-C20']::text[],'생활에서 실천할 수 없거나 자원·에너지와 상관없는 내용을 실천 영상 주제로 고른다','내가 할 수 있는 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X38','sci',5,'u4',ARRAY['SC5-2-u4-C20']::text[],'영상에 개인 정보·남을 비하하는 내용을 넣거나 위험한 곳에서 찍고 댓글을 함부로 쓴다','지키고 존중하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X39','sci',5,'u4',ARRAY['SC5-2-u4-C20']::text[],'영상을 한 번 만들어 올리면 실천은 끝났다고 여긴다','꾸준히') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X40','sci',5,'u4',ARRAY['SC5-2-u4-C21']::text[],'에너지 하베스팅을 버려지는 에너지 모으기가 아닌 새 발전소 짓기·석탄 더 캐기로 여긴다','버려지는 에너지 모으기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X41','sci',5,'u4',ARRAY['SC5-2-u4-C21']::text[],'재생 에너지 전문가가 하는 일을 엉뚱하게(석유를 더 쓰게 하는 일로) 여긴다','재생 에너지를 더 잘') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X42','sci',5,'u4',ARRAY['SC5-2-u4-C22']::text[],'재생 에너지가 있으니 자원과 에너지를 아낄 필요가 없다고 여긴다','아끼기도 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L01_basic#1','sci',5,2,'u4','L01','g5_2_sci_u4_L01_basic','lesson_basic','SC5-2-u4-C1',1,'mc','auto','풍력 발전기는 무엇의 힘으로 회전 날개를 돌리나요?',ARRAY['SC5-2-u4-X03']::text[],false,'{"seq":1,"concept":"SC5-2-u4-C1","difficulty":1,"kind":"mc","stem":"풍력 발전기는 무엇의 힘으로 회전 날개를 돌리나요?","options":[{"t":"바람","correct":true},{"t":"햇빛","mis":"SC5-2-u4-X03"},{"t":"땅속의 열","mis":"SC5-2-u4-X03"},{"t":"밀물과 썰물","mis":"SC5-2-u4-X03"}],"explanation":["풍력 발전기예요.","날개가 돌아요.","바람의 힘이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L01_basic#2','sci',5,2,'u4','L01','g5_2_sci_u4_L01_basic','lesson_basic','SC5-2-u4-C2',1,'ox','auto','풍력 발전 모형의 회전 날개가 빠르게 돌아갈 때 전구에 불이 켜져요.',ARRAY['SC5-2-u4-X01']::text[],false,'{"seq":2,"concept":"SC5-2-u4-C2","difficulty":1,"kind":"ox","stem":"풍력 발전 모형의 회전 날개가 빠르게 돌아갈 때 전구에 불이 켜져요.","answer":"O","reason_options":[{"t":"날개가 돌아갈 때 불을 켤 에너지가 만들어지기 때문에","correct":true},{"t":"날개가 멈춰 있을 때 에너지가 가장 많기 때문에","mis":"SC5-2-u4-X01"}],"mis":"SC5-2-u4-X01","explanation":["날개가 돌아요.","에너지가 만들어져요.","불이 켜져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L01_basic#3','sci',5,2,'u4','L01','g5_2_sci_u4_L01_basic','lesson_basic','SC5-2-u4-C2',1,'mc','auto','풍력 발전 모형의 회전 날개를 돌리는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X01','SC5-2-u4-X03']::text[],false,'{"seq":3,"concept":"SC5-2-u4-C2","difficulty":1,"kind":"mc","stem":"풍력 발전 모형의 회전 날개를 돌리는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"머리 말리개 바람을 날개에 보낸다","correct":true},{"t":"날개를 손가락으로 붙잡고 있는다","mis":"SC5-2-u4-X01"},{"t":"모형을 바람이 없는 상자 안에 둔다","mis":"SC5-2-u4-X03"},{"t":"전구를 손으로 감싼다","mis":"SC5-2-u4-X01"}],"explanation":["바람이 필요해요.","머리 말리개도 바람을 내요.","날개가 돌아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L01_basic#4','sci',5,2,'u4','L01','g5_2_sci_u4_L01_basic','lesson_basic','SC5-2-u4-C1',1,'sa','auto','바람으로 회전 날개를 돌려 에너지를 만드는 장치를 무엇이라고 하나요? 다섯 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC5-2-u4-C1","difficulty":1,"kind":"sa","stem":"바람으로 회전 날개를 돌려 에너지를 만드는 장치를 무엇이라고 하나요? 다섯 글자로 쓰세요.","answer":["풍력발전기","풍력 발전기"],"explanation":["바람의 힘을 써요.","다섯 글자예요.","풍력 발전기예요."],"mis":"SC5-2-u4-X03"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L01_basic#5','sci',5,2,'u4','L01','g5_2_sci_u4_L01_basic','lesson_basic','SC5-2-u4-C1',2,'mc','auto','풍력 발전기와 풍력 발전 모형의 같은 점으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X03']::text[],false,'{"seq":5,"concept":"SC5-2-u4-C1","difficulty":2,"kind":"mc","stem":"풍력 발전기와 풍력 발전 모형의 같은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"회전 날개가 달려 있어 바람이 불면 돌아간다","correct":true},{"t":"둘 다 산 위에만 세운다","mis":"SC5-2-u4-X03"},{"t":"둘 다 크기가 아주 크다","mis":"SC5-2-u4-X03"},{"t":"둘 다 바람 없이 스스로 돈다","mis":"SC5-2-u4-X03"}],"explanation":["둘 다 날개가 있어요.","바람이 불면 돌아요.","그게 같은 점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L01_basic#6','sci',5,2,'u4','L01','g5_2_sci_u4_L01_basic','lesson_basic','SC5-2-u4-C2',2,'mc','auto','입으로 바람을 불어 전구에 불을 켤 때 알맞은 방법은 어느 것인가요?',ARRAY['SC5-2-u4-X02','SC5-2-u4-X04']::text[],false,'{"seq":6,"concept":"SC5-2-u4-C2","difficulty":2,"kind":"mc","stem":"입으로 바람을 불어 전구에 불을 켤 때 알맞은 방법은 어느 것인가요?","options":[{"t":"날개 가운데 부분을 세게 분다","correct":true},{"t":"날개 끝을 살살 분다","mis":"SC5-2-u4-X02"},{"t":"날개에 입술을 대고 분다","mis":"SC5-2-u4-X04"},{"t":"전구에 대고 분다","mis":"SC5-2-u4-X02"}],"explanation":["가운데를 불어요.","세게 불어요.","날개가 빨리 돌아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L01_basic#7','sci',5,2,'u4','L01','g5_2_sci_u4_L01_basic','lesson_basic','SC5-2-u4-C2',2,'ox','auto','머리 말리개로 날개를 돌릴 때는 뜨거운 바람에 데지 않게 조심해야 해요.',ARRAY['SC5-2-u4-X04']::text[],false,'{"seq":7,"concept":"SC5-2-u4-C2","difficulty":2,"kind":"ox","stem":"머리 말리개로 날개를 돌릴 때는 뜨거운 바람에 데지 않게 조심해야 해요.","answer":"O","reason_options":[{"t":"머리 말리개의 바람과 몸체가 뜨거울 수 있기 때문에","correct":true},{"t":"머리 말리개는 아무리 가까이 대도 안전하기 때문에","mis":"SC5-2-u4-X04"}],"mis":"SC5-2-u4-X04","explanation":["바람이 뜨거워요.","데일 수 있어요.","조심해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L01_basic#8','sci',5,2,'u4','L01','g5_2_sci_u4_L01_basic','lesson_basic','SC5-2-u4-C2',2,'mc','auto','풍력 발전 모형 놀이 기록 ㉠에서 전구에 불이 켜지지 않은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X02','SC5-2-u4-X01']::text[],false,'{"seq":8,"concept":"SC5-2-u4-C2","difficulty":2,"kind":"mc","stem":"풍력 발전 모형 놀이 기록 ㉠에서 전구에 불이 켜지지 않은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"날개가 천천히 돌아 불을 켤 만큼 에너지가 만들어지지 않아서","correct":true},{"t":"입으로 불면 언제나 불이 켜지지 않아서","mis":"SC5-2-u4-X02"},{"t":"날개가 돌면 전구가 꺼지기 때문이라서","mis":"SC5-2-u4-X01"},{"t":"바람이 너무 세서","mis":"SC5-2-u4-X02"}],"explanation":["살살 불었어요.","날개가 천천히 돌아요.","에너지가 모자라요."],"asset":{"type":"passage","lines":["㉠ 입으로 살살 불기 — 날개가 천천히 돎 · 전구 꺼짐","㉡ 입으로 가운데를 세게 불기 — 날개가 빠르게 돎 · 전구 켜짐","㉢ 빨대로 날개 면을 비스듬히 불기 — 날개가 빠르게 돎 · 전구 켜짐","㉣ 머리 말리개 바람 보내기 — 날개가 아주 빠르게 돎 · 전구 밝게 켜짐"],"title":"풍력 발전 모형 놀이 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L01_basic#9','sci',5,2,'u4','L01','g5_2_sci_u4_L01_basic','lesson_basic','SC5-2-u4-C2',2,'mc','auto','빨대로 바람을 불 때 날개가 잘 돌게 하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X02','SC5-2-u4-X04']::text[],false,'{"seq":9,"concept":"SC5-2-u4-C2","difficulty":2,"kind":"mc","stem":"빨대로 바람을 불 때 날개가 잘 돌게 하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"빨대 끝을 날개 면 쪽으로 향하게 해 비스듬히 분다","correct":true},{"t":"빨대를 날개 반대쪽으로 향하게 해 분다","mis":"SC5-2-u4-X02"},{"t":"빨대로 날개를 콕콕 찌른다","mis":"SC5-2-u4-X04"},{"t":"빨대를 모형 아래 바닥에 대고 분다","mis":"SC5-2-u4-X02"}],"explanation":["날개 면을 향해요.","비스듬히 불어요.","잘 돌아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L01_basic#10','sci',5,2,'u4','L01','g5_2_sci_u4_L01_basic','lesson_basic','SC5-2-u4-C2',3,'error','auto','풍력 발전 모형 놀이를 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u4-X02','SC5-2-u4-X01']::text[],false,'{"seq":10,"concept":"SC5-2-u4-C2","difficulty":3,"kind":"error","stem":"풍력 발전 모형 놀이를 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「바람을 약하게 불수록 전구가 더 밝게 켜져.」","correct":true,"mis_target":"SC5-2-u4-X02"},{"t":"하준 — 「머리 말리개를 쓰니 날개가 더 빨리 돌았어.」","mis":"SC5-2-u4-X02"},{"t":"채린 — 「날개가 멈추니 불이 꺼졌어.」","mis":"SC5-2-u4-X01"}],"explanation":["세게 불어야 해요.","날개가 빨리 돌아야 해요.","서윤의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L01_challenge#1','sci',5,2,'u4','L01','g5_2_sci_u4_L01_challenge','lesson_challenge','SC5-2-u4-C2',2,'match','auto','바람을 보내는 방법과 결과를 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-2-u4-C2","difficulty":2,"kind":"match","stem":"바람을 보내는 방법과 결과를 알맞게 이으세요.","pairs":[{"l":"입으로 살살 불기","r":"날개가 천천히 돌아 불이 안 켜짐"},{"l":"입으로 세게 불기","r":"날개가 빠르게 돌아 불이 켜짐"},{"l":"머리 말리개 바람","r":"날개가 아주 빠르게 돌아 밝게 켜짐"}],"mis":"SC5-2-u4-X02","explanation":["바람 세기를 봐요.","날개 빠르기가 달라요.","불도 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L01_challenge#2','sci',5,2,'u4','L01','g5_2_sci_u4_L01_challenge','lesson_challenge','SC5-2-u4-C1',2,'mc','auto','산 위에 있는 풍력 발전기 회전 날개의 특징으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X03']::text[],false,'{"seq":2,"concept":"SC5-2-u4-C1","difficulty":2,"kind":"mc","stem":"산 위에 있는 풍력 발전기 회전 날개의 특징으로 알맞은 것은 어느 것인가요?","options":[{"t":"길쭉한 날개가 세 개 달려 있다","correct":true},{"t":"날개가 하나도 없다","mis":"SC5-2-u4-X03"},{"t":"날개가 손바닥만큼 짧다","mis":"SC5-2-u4-X03"},{"t":"날개가 땅속에 묻혀 있다","mis":"SC5-2-u4-X03"}],"explanation":["날개가 길어요.","세 개예요.","바람을 잘 받아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L01_challenge#3','sci',5,2,'u4','L01','g5_2_sci_u4_L01_challenge','lesson_challenge','SC5-2-u4-C2',3,'mc','auto','풍력 발전 모형 놀이 기록 ㉡~㉣을 보고 알 수 있는 것으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X01','SC5-2-u4-X02','SC5-2-u4-X03']::text[],false,'{"seq":3,"concept":"SC5-2-u4-C2","difficulty":3,"kind":"mc","stem":"풍력 발전 모형 놀이 기록 ㉡~㉣을 보고 알 수 있는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"날개가 빠르게 돌수록 전구에 불이 잘 켜진다","correct":true},{"t":"날개가 돌지 않을 때 불이 가장 밝다","mis":"SC5-2-u4-X01"},{"t":"어떤 방법이든 날개 빠르기는 같다","mis":"SC5-2-u4-X02"},{"t":"전구는 바람의 색에 따라 켜진다","mis":"SC5-2-u4-X03"}],"explanation":["빠르게 돌았어요.","불이 켜졌어요.","빠를수록 잘 켜져요."],"asset":{"type":"passage","lines":["㉠ 입으로 살살 불기 — 날개가 천천히 돎 · 전구 꺼짐","㉡ 입으로 가운데를 세게 불기 — 날개가 빠르게 돎 · 전구 켜짐","㉢ 빨대로 날개 면을 비스듬히 불기 — 날개가 빠르게 돎 · 전구 켜짐","㉣ 머리 말리개 바람 보내기 — 날개가 아주 빠르게 돎 · 전구 밝게 켜짐"],"title":"풍력 발전 모형 놀이 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L01_challenge#4','sci',5,2,'u4','L01','g5_2_sci_u4_L01_challenge','lesson_challenge','SC5-2-u4-C2',3,'mc','auto','전구에 불을 켜려고 날개를 빨리 돌리는 데 힘이 많이 들었어요. 이것으로 알 수 있는 것은 어느 것인가요?',ARRAY['SC5-2-u4-X01','SC5-2-u4-X03','SC5-2-u4-X02']::text[],false,'{"seq":4,"concept":"SC5-2-u4-C2","difficulty":3,"kind":"mc","stem":"전구에 불을 켜려고 날개를 빨리 돌리는 데 힘이 많이 들었어요. 이것으로 알 수 있는 것은 어느 것인가요?","options":[{"t":"전구에 불을 켜는 데 큰 에너지가 필요하다","correct":true},{"t":"전구는 에너지 없이도 켜진다","mis":"SC5-2-u4-X01"},{"t":"바람은 에너지를 만들 수 없다","mis":"SC5-2-u4-X03"},{"t":"약한 바람이 에너지를 가장 많이 만든다","mis":"SC5-2-u4-X02"}],"explanation":["힘이 많이 들었어요.","에너지가 많이 필요해요.","불 켜기는 쉽지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L01_challenge#5','sci',5,2,'u4','L01','g5_2_sci_u4_L01_challenge','lesson_challenge','SC5-2-u4-C1',3,'ox','auto','바람이 전혀 불지 않는 날에도 풍력 발전기는 에너지를 많이 만들어요.',ARRAY['SC5-2-u4-X03']::text[],false,'{"seq":5,"concept":"SC5-2-u4-C1","difficulty":3,"kind":"ox","stem":"바람이 전혀 불지 않는 날에도 풍력 발전기는 에너지를 많이 만들어요.","answer":"X","reason_options":[{"t":"바람이 불어 날개가 돌아야 에너지가 만들어지기 때문에","correct":true},{"t":"풍력 발전기는 바람 없이 스스로 날개를 돌리기 때문에","mis":"SC5-2-u4-X03"}],"mis":"SC5-2-u4-X03","explanation":["바람이 없어요.","날개가 안 돌아요.","에너지를 못 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L01_challenge#6','sci',5,2,'u4','L01','g5_2_sci_u4_L01_challenge','lesson_challenge','SC5-2-u4-C2',3,'error','auto','안전하게 놀이를 하는지 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u4-X04','SC5-2-u4-X02']::text[],false,'{"seq":6,"concept":"SC5-2-u4-C2","difficulty":3,"kind":"error","stem":"안전하게 놀이를 하는지 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「날개에 입술을 바짝 대고 불어야 잘 돌아.」","correct":true,"mis_target":"SC5-2-u4-X04"},{"t":"지아 — 「머리 말리개는 몸에서 떨어뜨려 써.」","mis":"SC5-2-u4-X04"},{"t":"은호 — 「가운데를 세게 부니 불이 켜졌어.」","mis":"SC5-2-u4-X02"}],"explanation":["입술은 멀리해요.","날개가 돌면 다쳐요.","도윤의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L01_challenge#7','sci',5,2,'u4','L01','g5_2_sci_u4_L01_challenge','lesson_challenge','SC5-2-u4-C2',3,'mc','auto','풍력 발전 모형의 전구가 날개가 돌 때만 켜지는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X01','SC5-2-u4-X02','SC5-2-u4-X03']::text[],false,'{"seq":7,"concept":"SC5-2-u4-C2","difficulty":3,"kind":"mc","stem":"풍력 발전 모형의 전구가 날개가 돌 때만 켜지는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"날개가 돌아가는 동안 불을 켤 에너지가 만들어지기 때문이다","correct":true},{"t":"전구 속에 에너지가 미리 가득 들어 있기 때문이다","mis":"SC5-2-u4-X01"},{"t":"날개가 멈추면 바람이 더 세지기 때문이다","mis":"SC5-2-u4-X02"},{"t":"모형이 햇빛을 받아야 켜지기 때문이다","mis":"SC5-2-u4-X03"}],"explanation":["날개가 돌아요.","에너지가 생겨요.","그때만 켜져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L01_challenge#8','sci',5,2,'u4','L01','g5_2_sci_u4_L01_challenge','lesson_challenge','SC5-2-u4-C2',4,'mc','auto','내 몸을 움직여 에너지를 만들 수 있을 것 같은 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X01','SC5-2-u4-X03']::text[],false,'{"seq":8,"concept":"SC5-2-u4-C2","difficulty":4,"kind":"mc","stem":"내 몸을 움직여 에너지를 만들 수 있을 것 같은 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"자전거 페달을 힘차게 밟아 바퀴에 단 장치를 돌린다","correct":true},{"t":"가만히 앉아 눈을 감고 있는다","mis":"SC5-2-u4-X01"},{"t":"전구를 냉장고에 넣어 둔다","mis":"SC5-2-u4-X03"},{"t":"모형의 날개를 손으로 꽉 잡는다","mis":"SC5-2-u4-X01"}],"explanation":["몸을 움직여요.","바퀴가 돌아요.","에너지를 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L01_challenge#9','sci',5,2,'u4','L01','g5_2_sci_u4_L01_challenge','lesson_challenge','SC5-2-u4-C1',4,'mc','auto','풍력 발전기를 세우기에 가장 알맞은 곳은 어느 것인가요?',ARRAY['SC5-2-u4-X03']::text[],false,'{"seq":9,"concept":"SC5-2-u4-C1","difficulty":4,"kind":"mc","stem":"풍력 발전기를 세우기에 가장 알맞은 곳은 어느 것인가요?","options":[{"t":"바람이 세고 자주 부는 바닷가 언덕","correct":true},{"t":"바람이 거의 없는 좁은 골목","mis":"SC5-2-u4-X03"},{"t":"사방이 막힌 지하 주차장","mis":"SC5-2-u4-X03"},{"t":"높은 건물로 둘러싸인 작은 마당","mis":"SC5-2-u4-X03"}],"explanation":["바람이 필요해요.","세고 자주 불어야 해요.","바닷가 언덕이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L01_challenge#10','sci',5,2,'u4','L01','g5_2_sci_u4_L01_challenge','lesson_challenge','SC5-2-u4-C2',4,'essay','teacher','풍력 발전 모형의 전구를 더 밝게 켜는 방법을 하나 생각해 쓰고, 그렇게 생각한 까닭을 날개가 도는 빠르기와 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-2-u4-C2","difficulty":4,"kind":"essay","stem":"풍력 발전 모형의 전구를 더 밝게 켜는 방법을 하나 생각해 쓰고, 그렇게 생각한 까닭을 날개가 도는 빠르기와 함께 쓰세요.","answer_guide":{"answer":"예: 머리 말리개 바람을 날개 가운데에 똑바로 보낸다. 바람이 세면 날개가 더 빠르게 돌아 전구를 켤 에너지가 더 많이 만들어지기 때문이다.","scoring_points":["방법을 하나 썼는가","날개가 더 빠르게 돈다고 썼는가","에너지가 더 많이 만들어진다는 까닭을 썼는가"]},"explanation":["바람을 세게 해요.","날개가 빨라져요.","불이 밝아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L02_basic#1','sci',5,2,'u4','L02','g5_2_sci_u4_L02_basic','lesson_basic','SC5-2-u4-C3',1,'mc','auto','책을 만들 때 쓰는 나무처럼 생활하거나 물건을 만들 때 이용하는 원료를 무엇이라고 하나요?',ARRAY['SC5-2-u4-X05']::text[],false,'{"seq":1,"concept":"SC5-2-u4-C3","difficulty":1,"kind":"mc","stem":"책을 만들 때 쓰는 나무처럼 생활하거나 물건을 만들 때 이용하는 원료를 무엇이라고 하나요?","options":[{"t":"자원","correct":true},{"t":"쓰레기","mis":"SC5-2-u4-X05"},{"t":"날씨","mis":"SC5-2-u4-X05"},{"t":"기계","mis":"SC5-2-u4-X05"}],"explanation":["나무는 원료예요.","물건을 만들어요.","자원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L02_basic#2','sci',5,2,'u4','L02','g5_2_sci_u4_L02_basic','lesson_basic','SC5-2-u4-C3',1,'sa','auto','우리가 생활하거나 물건을 생산할 때 이용하는 원료를 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC5-2-u4-C3","difficulty":1,"kind":"sa","stem":"우리가 생활하거나 물건을 생산할 때 이용하는 원료를 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["자원"],"explanation":["물·나무·철이에요.","두 글자예요.","자원이에요."],"mis":"SC5-2-u4-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L02_basic#3','sci',5,2,'u4','L02','g5_2_sci_u4_L02_basic','lesson_basic','SC5-2-u4-C4',1,'mc','auto','종이컵이나 휴지를 만들 때 쓰는 나무는 어떤 자원인가요?',ARRAY['SC5-2-u4-X06']::text[],false,'{"seq":3,"concept":"SC5-2-u4-C4","difficulty":1,"kind":"mc","stem":"종이컵이나 휴지를 만들 때 쓰는 나무는 어떤 자원인가요?","options":[{"t":"산림 자원","correct":true},{"t":"물 자원","mis":"SC5-2-u4-X06"},{"t":"광물 자원","mis":"SC5-2-u4-X06"},{"t":"바람 자원","mis":"SC5-2-u4-X06"}],"explanation":["나무는 숲에서 와요.","숲은 산림이에요.","산림 자원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L02_basic#4','sci',5,2,'u4','L02','g5_2_sci_u4_L02_basic','lesson_basic','SC5-2-u4-C5',1,'ox','auto','땅속 광물 자원은 묻혀 있는 양이 한정되어 있어요.',ARRAY['SC5-2-u4-X10']::text[],false,'{"seq":4,"concept":"SC5-2-u4-C5","difficulty":1,"kind":"ox","stem":"땅속 광물 자원은 묻혀 있는 양이 한정되어 있어요.","answer":"O","reason_options":[{"t":"한번 쓰면 다시 만들어지기 어렵기 때문에","correct":true},{"t":"캐낸 만큼 금방 다시 생겨나기 때문에","mis":"SC5-2-u4-X10"}],"mis":"SC5-2-u4-X10","explanation":["묻힌 양이 정해져 있어요.","다시 생기기 어려워요.","한정되어 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L02_basic#5','sci',5,2,'u4','L02','g5_2_sci_u4_L02_basic','lesson_basic','SC5-2-u4-C4',2,'mc','auto','자원의 이용 카드에서 광물 자원을 이용하는 카드끼리 모은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X06']::text[],false,'{"seq":5,"concept":"SC5-2-u4-C4","difficulty":2,"kind":"mc","stem":"자원의 이용 카드에서 광물 자원을 이용하는 카드끼리 모은 것은 어느 것인가요?","options":[{"t":"㉢, ㉥","correct":true},{"t":"㉠, ㉣","mis":"SC5-2-u4-X06"},{"t":"㉡, ㉤","mis":"SC5-2-u4-X06"},{"t":"㉢, ㉤","mis":"SC5-2-u4-X06"}],"explanation":["철·구리는 광물이에요.","석탄도 광물이에요.","㉢과 ㉥이에요."],"asset":{"type":"passage","lines":["㉠ 목이 말라 물을 마신다.","㉡ 숲에서 버섯을 딴다.","㉢ 철과 구리로 스마트 기기를 만든다.","㉣ 논에 물을 대어 벼를 기른다.","㉤ 나무로 책상을 만든다.","㉥ 석탄으로 에너지를 얻는다."],"title":"자원의 이용 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L02_basic#6','sci',5,2,'u4','L02','g5_2_sci_u4_L02_basic','lesson_basic','SC5-2-u4-C5',2,'mc','auto','물 자원에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['SC5-2-u4-X07','SC5-2-u4-X08','SC5-2-u4-X05']::text[],false,'{"seq":6,"concept":"SC5-2-u4-C5","difficulty":2,"kind":"mc","stem":"물 자원에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"지구의 물 총량은 그대로지만 쓸 수 있는 깨끗한 물은 점점 부족해진다","correct":true},{"t":"물을 쓸 때마다 지구의 물이 사라진다","mis":"SC5-2-u4-X07"},{"t":"물은 돌고 도니 깨끗한 물도 줄지 않는다","mis":"SC5-2-u4-X08"},{"t":"물은 자원이 아니라 걱정할 필요가 없다","mis":"SC5-2-u4-X05"}],"explanation":["총량은 그대로예요.","깨끗해지려면 오래 걸려요.","깨끗한 물은 줄어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L02_basic#7','sci',5,2,'u4','L02','g5_2_sci_u4_L02_basic','lesson_basic','SC5-2-u4-C5',2,'mc','auto','산림 자원이 줄어드는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X09']::text[],false,'{"seq":7,"concept":"SC5-2-u4-C5","difficulty":2,"kind":"mc","stem":"산림 자원이 줄어드는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"나무를 많이 베거나 숲을 농경지로 바꾸면 다시 자라는 데 오래 걸려서","correct":true},{"t":"나무는 베면 바로 다시 자라서","mis":"SC5-2-u4-X09"},{"t":"비가 많이 오면 나무가 사라져서","mis":"SC5-2-u4-X09"},{"t":"나무를 심을수록 숲이 줄어들어서","mis":"SC5-2-u4-X09"}],"explanation":["나무를 많이 베요.","다시 자라려면 오래 걸려요.","숲이 줄어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L02_basic#8','sci',5,2,'u4','L02','g5_2_sci_u4_L02_basic','lesson_basic','SC5-2-u4-C6',2,'ox','auto','자원을 조사할 때는 찾은 자료가 믿을 수 있는 출처에서 나왔는지 확인해야 해요.',ARRAY['SC5-2-u4-X12']::text[],false,'{"seq":8,"concept":"SC5-2-u4-C6","difficulty":2,"kind":"ox","stem":"자원을 조사할 때는 찾은 자료가 믿을 수 있는 출처에서 나왔는지 확인해야 해요.","answer":"O","reason_options":[{"t":"틀린 정보를 그대로 믿으면 잘못 알 수 있기 때문에","correct":true},{"t":"누리망에 있는 자료는 모두 정확하기 때문에","mis":"SC5-2-u4-X12"}],"mis":"SC5-2-u4-X12","explanation":["자료를 찾아요.","출처를 확인해요.","믿을 수 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L02_basic#9','sci',5,2,'u4','L02','g5_2_sci_u4_L02_basic','lesson_basic','SC5-2-u4-C6',2,'mc','auto','자원을 아껴 써야 하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X10','SC5-2-u4-X11','SC5-2-u4-X05']::text[],false,'{"seq":9,"concept":"SC5-2-u4-C6","difficulty":2,"kind":"mc","stem":"자원을 아껴 써야 하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"자원의 양이 한정되어 있어 마구 쓰면 부족해지기 때문이다","correct":true},{"t":"자원은 쓸수록 더 늘어나기 때문이다","mis":"SC5-2-u4-X10"},{"t":"재활용하면 끝없이 생기기 때문이다","mis":"SC5-2-u4-X11"},{"t":"자원은 미래에는 필요 없기 때문이다","mis":"SC5-2-u4-X05"}],"explanation":["양이 한정되어 있어요.","마구 쓰면 부족해요.","아껴 써야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L02_basic#10','sci',5,2,'u4','L02','g5_2_sci_u4_L02_basic','lesson_basic','SC5-2-u4-C5',3,'error','auto','세 모둠의 토의 메모를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u4-X11','SC5-2-u4-X08','SC5-2-u4-X09']::text[],false,'{"seq":10,"concept":"SC5-2-u4-C5","difficulty":3,"kind":"error","stem":"세 모둠의 토의 메모를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"나래 — 「캔을 재활용하니까 광물 자원은 끝없이 쓸 수 있어.」","correct":true,"mis_target":"SC5-2-u4-X11"},{"t":"시우 — 「더러워진 물이 깨끗해지려면 오래 걸려.」","mis":"SC5-2-u4-X08"},{"t":"다온 — 「나무가 다시 자라려면 오래 걸려.」","mis":"SC5-2-u4-X09"}],"explanation":["재활용해도 한정돼요.","끝없지 않아요.","나래의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["물 모둠 — 물은 돌고 돌지만 더러워진 물이 깨끗해지려면 오래 걸린다.","숲 모둠 — 나무를 베면 다시 자라기까지 오래 걸린다.","광물 모둠 — 땅속 광물은 묻혀 있는 양이 정해져 있다."],"title":"세 모둠의 토의 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L02_challenge#1','sci',5,2,'u4','L02','g5_2_sci_u4_L02_challenge','lesson_challenge','SC5-2-u4-C4',2,'match','auto','자원을 이용하는 모습과 자원의 종류를 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-2-u4-C4","difficulty":2,"kind":"match","stem":"자원을 이용하는 모습과 자원의 종류를 알맞게 이으세요.","pairs":[{"l":"논에 물을 대어 벼를 기른다","r":"물 자원"},{"l":"나무로 책상을 만든다","r":"산림 자원"},{"l":"철근으로 건물을 짓는다","r":"광물 자원"}],"mis":"SC5-2-u4-X06","explanation":["물을 써요.","나무를 써요.","철을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L02_challenge#2','sci',5,2,'u4','L02','g5_2_sci_u4_L02_challenge','lesson_challenge','SC5-2-u4-C3',2,'mc','auto','다음 가운데 자원이라고 할 수 있는 것은 어느 것인가요?',ARRAY['SC5-2-u4-X05']::text[],false,'{"seq":2,"concept":"SC5-2-u4-C3","difficulty":2,"kind":"mc","stem":"다음 가운데 자원이라고 할 수 있는 것은 어느 것인가요?","options":[{"t":"자동차를 만드는 데 쓰는 철","correct":true},{"t":"하늘에 뜬 무지개","mis":"SC5-2-u4-X05"},{"t":"어젯밤에 꾼 꿈","mis":"SC5-2-u4-X05"},{"t":"친구의 웃음소리","mis":"SC5-2-u4-X05"}],"explanation":["원료를 찾아요.","철은 자동차의 원료예요.","철이 자원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L02_challenge#3','sci',5,2,'u4','L02','g5_2_sci_u4_L02_challenge','lesson_challenge','SC5-2-u4-C5',3,'mc','auto','세 모둠의 토의 메모를 모아 낼 수 있는 결론으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X11','SC5-2-u4-X09','SC5-2-u4-X10']::text[],false,'{"seq":3,"concept":"SC5-2-u4-C5","difficulty":3,"kind":"mc","stem":"세 모둠의 토의 메모를 모아 낼 수 있는 결론으로 알맞은 것은 어느 것인가요?","options":[{"t":"물·산림·광물 자원은 다시 만들어지는 데 오래 걸리거나 양이 한정되어 계속 쓰기 어렵다","correct":true},{"t":"세 자원은 끝없이 있어 마음껏 써도 된다","mis":"SC5-2-u4-X11"},{"t":"물 자원만 한정되어 있다","mis":"SC5-2-u4-X09"},{"t":"광물 자원은 곧 다시 만들어진다","mis":"SC5-2-u4-X10"}],"explanation":["세 모둠 모두 오래 걸려요.","양도 정해져 있어요.","계속 쓰기 어려워요."],"asset":{"type":"passage","lines":["물 모둠 — 물은 돌고 돌지만 더러워진 물이 깨끗해지려면 오래 걸린다.","숲 모둠 — 나무를 베면 다시 자라기까지 오래 걸린다.","광물 모둠 — 땅속 광물은 묻혀 있는 양이 정해져 있다."],"title":"세 모둠의 토의 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L02_challenge#4','sci',5,2,'u4','L02','g5_2_sci_u4_L02_challenge','lesson_challenge','SC5-2-u4-C5',3,'mc','auto','「물은 지구를 돌고 돌아 줄지 않으니 마음껏 써도 된다.」를 바르게 고친 것은 어느 것인가요?',ARRAY['SC5-2-u4-X07','SC5-2-u4-X08']::text[],false,'{"seq":4,"concept":"SC5-2-u4-C5","difficulty":3,"kind":"mc","stem":"「물은 지구를 돌고 돌아 줄지 않으니 마음껏 써도 된다.」를 바르게 고친 것은 어느 것인가요?","options":[{"t":"물의 총량은 그대로지만 오염이나 기후변화로 사람이 쓸 깨끗한 물은 줄어든다","correct":true},{"t":"물은 돌지 않고 한 번 쓰면 없어진다","mis":"SC5-2-u4-X07"},{"t":"고칠 것이 없는 맞는 말이다","mis":"SC5-2-u4-X08"},{"t":"물은 바다에만 있어 사람이 쓸 수 없다","mis":"SC5-2-u4-X08"}],"explanation":["물은 돌아요.","총량은 그대로예요.","깨끗한 물이 줄어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L02_challenge#5','sci',5,2,'u4','L02','g5_2_sci_u4_L02_challenge','lesson_challenge','SC5-2-u4-C5',3,'ox','auto','종이를 재활용하는 예가 있으니 산림 자원은 걱정 없이 마구 써도 돼요.',ARRAY['SC5-2-u4-X11']::text[],false,'{"seq":5,"concept":"SC5-2-u4-C5","difficulty":3,"kind":"ox","stem":"종이를 재활용하는 예가 있으니 산림 자원은 걱정 없이 마구 써도 돼요.","answer":"X","reason_options":[{"t":"재활용을 해도 자원이 끝없이 있는 것은 아니기 때문에","correct":true},{"t":"재활용되는 자원은 무한하기 때문에","mis":"SC5-2-u4-X11"}],"mis":"SC5-2-u4-X11","explanation":["재활용은 좋아요.","그래도 한정돼요.","아껴 써야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L02_challenge#6','sci',5,2,'u4','L02','g5_2_sci_u4_L02_challenge','lesson_challenge','SC5-2-u4-C6',3,'mc','auto','오늘날 자원 사용량이 점점 늘어나는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X10','SC5-2-u4-X05','SC5-2-u4-X11']::text[],false,'{"seq":6,"concept":"SC5-2-u4-C6","difficulty":3,"kind":"mc","stem":"오늘날 자원 사용량이 점점 늘어나는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"인구가 늘고 더 편리하게 생활하려고 자원을 많이 쓰기 때문이다","correct":true},{"t":"자원이 저절로 늘어나기 때문이다","mis":"SC5-2-u4-X10"},{"t":"사람들이 자원을 전혀 쓰지 않기 때문이다","mis":"SC5-2-u4-X05"},{"t":"자원은 쓸수록 다시 생기기 때문이다","mis":"SC5-2-u4-X11"}],"explanation":["사람이 늘어요.","편리한 생활을 해요.","많이 쓰게 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L02_challenge#7','sci',5,2,'u4','L02','g5_2_sci_u4_L02_challenge','lesson_challenge','SC5-2-u4-C4',3,'error','auto','자원의 이용 카드를 나누며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u4-X06']::text[],false,'{"seq":7,"concept":"SC5-2-u4-C4","difficulty":3,"kind":"error","stem":"자원의 이용 카드를 나누며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"보미 — 「㉥ 석탄으로 에너지를 얻는 카드는 산림 자원이야.」","correct":true,"mis_target":"SC5-2-u4-X06"},{"t":"지훈 — 「㉡ 숲에서 버섯을 따는 건 산림 자원이야.」","mis":"SC5-2-u4-X06"},{"t":"예린 — 「㉣ 논에 물을 대는 건 물 자원이야.」","mis":"SC5-2-u4-X06"}],"explanation":["석탄은 땅속에서 캐요.","광물 자원이에요.","보미의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["㉠ 목이 말라 물을 마신다.","㉡ 숲에서 버섯을 딴다.","㉢ 철과 구리로 스마트 기기를 만든다.","㉣ 논에 물을 대어 벼를 기른다.","㉤ 나무로 책상을 만든다.","㉥ 석탄으로 에너지를 얻는다."],"title":"자원의 이용 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L02_challenge#8','sci',5,2,'u4','L02','g5_2_sci_u4_L02_challenge','lesson_challenge','SC5-2-u4-C6',4,'mc','auto','스마트 기기로 자원을 조사할 때 가장 알맞은 태도는 어느 것인가요?',ARRAY['SC5-2-u4-X12']::text[],false,'{"seq":8,"concept":"SC5-2-u4-C6","difficulty":4,"kind":"mc","stem":"스마트 기기로 자원을 조사할 때 가장 알맞은 태도는 어느 것인가요?","options":[{"t":"믿을 수 있는 누리집 자료인지 확인하고 출처를 함께 적는다","correct":true},{"t":"가장 먼저 나온 글을 그대로 베낀다","mis":"SC5-2-u4-X12"},{"t":"출처는 지우고 내 생각처럼 쓴다","mis":"SC5-2-u4-X12"},{"t":"조사와 상관없는 놀이 누리집을 본다","mis":"SC5-2-u4-X12"}],"explanation":["자료를 살펴요.","출처를 확인해요.","함께 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L02_challenge#9','sci',5,2,'u4','L02','g5_2_sci_u4_L02_challenge','lesson_challenge','SC5-2-u4-C5',4,'mc','auto','지금처럼 자원을 마구 쓰면 생길 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X11','SC5-2-u4-X10','SC5-2-u4-X05']::text[],false,'{"seq":9,"concept":"SC5-2-u4-C5","difficulty":4,"kind":"mc","stem":"지금처럼 자원을 마구 쓰면 생길 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"쓸 수 있는 자원이 부족해지고 환경오염과 기후변화도 심해질 수 있다","correct":true},{"t":"자원이 오히려 넘쳐나게 된다","mis":"SC5-2-u4-X11"},{"t":"광물 자원이 새로 빨리 만들어진다","mis":"SC5-2-u4-X10"},{"t":"아무 일도 생기지 않는다","mis":"SC5-2-u4-X05"}],"explanation":["자원은 한정돼요.","부족해져요.","환경도 나빠져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L02_challenge#10','sci',5,2,'u4','L02','g5_2_sci_u4_L02_challenge','lesson_challenge','SC5-2-u4-C6',4,'essay','teacher','물·산림·광물 자원 가운데 하나를 골라, 그 자원을 계속 마구 쓰면 어떻게 될지와 아껴 써야 하는 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-2-u4-C6","difficulty":4,"kind":"essay","stem":"물·산림·광물 자원 가운데 하나를 골라, 그 자원을 계속 마구 쓰면 어떻게 될지와 아껴 써야 하는 까닭을 쓰세요.","answer_guide":{"answer":"예: 광물 자원은 땅속에 묻힌 양이 한정되어 있고 다시 만들어지기 어렵다. 계속 마구 쓰면 언젠가 바닥나 쓸 수 없게 되므로 아끼고 분리배출해 다시 써야 한다.","scoring_points":["자원 하나를 골랐는가","한정되어 있다는 점을 썼는가","계속 쓰면 부족해진다는 결과와 아껴 쓸 까닭을 썼는가"]},"explanation":["자원을 골라요.","한정을 써요.","까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L03_basic#1','sci',5,2,'u4','L03','g5_2_sci_u4_L03_basic','lesson_basic','SC5-2-u4-C7',1,'mc','auto','태양 빛·바람·물처럼 자연에서 얻고 계속 이용할 수 있는 에너지는 어느 것인가요?',ARRAY['SC5-2-u4-X13']::text[],false,'{"seq":1,"concept":"SC5-2-u4-C7","difficulty":1,"kind":"mc","stem":"태양 빛·바람·물처럼 자연에서 얻고 계속 이용할 수 있는 에너지는 어느 것인가요?","options":[{"t":"재생 에너지","correct":true},{"t":"석탄에서 얻는 에너지","mis":"SC5-2-u4-X13"},{"t":"석유에서 얻는 에너지","mis":"SC5-2-u4-X13"},{"t":"쓸수록 줄어드는 에너지","mis":"SC5-2-u4-X13"}],"explanation":["자연에서 얻어요.","계속 쓸 수 있어요.","재생 에너지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L03_basic#2','sci',5,2,'u4','L03','g5_2_sci_u4_L03_basic','lesson_basic','SC5-2-u4-C7',1,'sa','auto','바람처럼 자연에서 얻어 계속 쓸 수 있는 에너지를 무엇이라고 하나요? 다섯 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC5-2-u4-C7","difficulty":1,"kind":"sa","stem":"바람처럼 자연에서 얻어 계속 쓸 수 있는 에너지를 무엇이라고 하나요? 다섯 글자로 쓰세요.","answer":["재생에너지","재생 에너지"],"explanation":["계속 쓸 수 있어요.","다섯 글자예요.","재생 에너지예요."],"mis":"SC5-2-u4-X13"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L03_basic#3','sci',5,2,'u4','L03','g5_2_sci_u4_L03_basic','lesson_basic','SC5-2-u4-C8',1,'mc','auto','높은 곳에서 낮은 곳으로 떨어지는 물의 흐름을 이용하는 재생 에너지는 어느 것인가요?',ARRAY['SC5-2-u4-X14','SC5-2-u4-X17']::text[],false,'{"seq":3,"concept":"SC5-2-u4-C8","difficulty":1,"kind":"mc","stem":"높은 곳에서 낮은 곳으로 떨어지는 물의 흐름을 이용하는 재생 에너지는 어느 것인가요?","options":[{"t":"수력","correct":true},{"t":"해양 에너지","mis":"SC5-2-u4-X14"},{"t":"지열 에너지","mis":"SC5-2-u4-X14"},{"t":"바이오 에너지","mis":"SC5-2-u4-X17"}],"explanation":["떨어지는 물이에요.","물의 흐름을 써요.","수력이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L03_basic#4','sci',5,2,'u4','L03','g5_2_sci_u4_L03_basic','lesson_basic','SC5-2-u4-C8',1,'ox','auto','바람으로 발전기를 돌려 에너지를 얻는 것을 풍력이라고 해요.',ARRAY['SC5-2-u4-X14']::text[],false,'{"seq":4,"concept":"SC5-2-u4-C8","difficulty":1,"kind":"ox","stem":"바람으로 발전기를 돌려 에너지를 얻는 것을 풍력이라고 해요.","answer":"O","reason_options":[{"t":"바람의 힘으로 발전기를 돌리기 때문에","correct":true},{"t":"땅속의 열로 발전기를 돌리기 때문에","mis":"SC5-2-u4-X14"}],"mis":"SC5-2-u4-X14","explanation":["바람을 써요.","발전기가 돌아요.","풍력이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L03_basic#5','sci',5,2,'u4','L03','g5_2_sci_u4_L03_basic','lesson_basic','SC5-2-u4-C8',2,'mc','auto','재생 에너지 수수께끼 카드 (가)가 가리키는 재생 에너지는 어느 것인가요?',ARRAY['SC5-2-u4-X16','SC5-2-u4-X14']::text[],false,'{"seq":5,"concept":"SC5-2-u4-C8","difficulty":2,"kind":"mc","stem":"재생 에너지 수수께끼 카드 (가)가 가리키는 재생 에너지는 어느 것인가요?","options":[{"t":"지열 에너지","correct":true},{"t":"태양 에너지","mis":"SC5-2-u4-X16"},{"t":"해양 에너지","mis":"SC5-2-u4-X14"},{"t":"풍력","mis":"SC5-2-u4-X14"}],"explanation":["땅속 깊은 곳이에요.","온도가 거의 같아요.","지열 에너지예요."],"asset":{"type":"passage","lines":["(가) 땅속 깊은 곳에 있어. 사계절 온도가 거의 같아 냉난방을 도와.","(나) 바닷가에 살아. 밀물과 썰물이 드나드는 힘을 써.","(다) 골짜기에 살아. 높은 곳에서 떨어지는 물로 발전기를 돌려.","(라) 목장에 살아. 가축의 분뇨와 음식물 쓰레기에서 얻어."],"title":"재생 에너지 수수께끼 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L03_basic#6','sci',5,2,'u4','L03','g5_2_sci_u4_L03_basic','lesson_basic','SC5-2-u4-C8',2,'mc','auto','재생 에너지 수수께끼 카드 (라)가 가리키는 재생 에너지는 어느 것인가요?',ARRAY['SC5-2-u4-X14','SC5-2-u4-X17']::text[],false,'{"seq":6,"concept":"SC5-2-u4-C8","difficulty":2,"kind":"mc","stem":"재생 에너지 수수께끼 카드 (라)가 가리키는 재생 에너지는 어느 것인가요?","options":[{"t":"바이오 에너지","correct":true},{"t":"수력","mis":"SC5-2-u4-X14"},{"t":"지열 에너지","mis":"SC5-2-u4-X14"},{"t":"석탄","mis":"SC5-2-u4-X17"}],"explanation":["가축 분뇨를 써요.","음식물 쓰레기도 써요.","바이오 에너지예요."],"asset":{"type":"passage","lines":["(가) 땅속 깊은 곳에 있어. 사계절 온도가 거의 같아 냉난방을 도와.","(나) 바닷가에 살아. 밀물과 썰물이 드나드는 힘을 써.","(다) 골짜기에 살아. 높은 곳에서 떨어지는 물로 발전기를 돌려.","(라) 목장에 살아. 가축의 분뇨와 음식물 쓰레기에서 얻어."],"title":"재생 에너지 수수께끼 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L03_basic#7','sci',5,2,'u4','L03','g5_2_sci_u4_L03_basic','lesson_basic','SC5-2-u4-C8',2,'mc','auto','태양 에너지에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['SC5-2-u4-X15','SC5-2-u4-X16']::text[],false,'{"seq":7,"concept":"SC5-2-u4-C8","difficulty":2,"kind":"mc","stem":"태양 에너지에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"태양 빛을 많이 이용하고 태양열을 이용하기도 한다","correct":true},{"t":"태양의 뜨거운 열만 이용한다","mis":"SC5-2-u4-X15"},{"t":"밤에만 얻을 수 있다","mis":"SC5-2-u4-X15"},{"t":"땅속에서 캐내어 얻는다","mis":"SC5-2-u4-X16"}],"explanation":["빛을 많이 써요.","열도 써요.","둘 다 이용해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L03_basic#8','sci',5,2,'u4','L03','g5_2_sci_u4_L03_basic','lesson_basic','SC5-2-u4-C9',2,'mc','auto','네 지역의 특징에서 ㉡ 해든 들판에 가장 알맞은 재생 에너지는 어느 것인가요?',ARRAY['SC5-2-u4-X18']::text[],false,'{"seq":8,"concept":"SC5-2-u4-C9","difficulty":2,"kind":"mc","stem":"네 지역의 특징에서 ㉡ 해든 들판에 가장 알맞은 재생 에너지는 어느 것인가요?","options":[{"t":"태양 에너지","correct":true},{"t":"바이오 에너지","mis":"SC5-2-u4-X18"},{"t":"해양 에너지","mis":"SC5-2-u4-X18"},{"t":"수력","mis":"SC5-2-u4-X18"}],"explanation":["햇빛이 강해요.","빛을 모아요.","태양 에너지예요."],"asset":{"type":"passage","lines":["㉠ 바람솔섬 — 바다로 둘러싸여 일 년 내내 바람이 세다.","㉡ 해든 들판 — 비가 적고 햇빛이 강하게 내리쬔다.","㉢ 소울 목장 마을 — 가축이 많아 분뇨 처리가 걱정이다.","㉣ 물안개 골짜기 — 산이 깊고 물이 세차게 흘러내린다."],"title":"네 지역의 특징"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L03_basic#9','sci',5,2,'u4','L03','g5_2_sci_u4_L03_basic','lesson_basic','SC5-2-u4-C10',2,'ox','auto','재생 에너지는 환경오염에 영향을 적게 줘요.',ARRAY['SC5-2-u4-X20']::text[],false,'{"seq":9,"concept":"SC5-2-u4-C10","difficulty":2,"kind":"ox","stem":"재생 에너지는 환경오염에 영향을 적게 줘요.","answer":"O","reason_options":[{"t":"자연에서 얻어 대기오염과 기후변화에 영향을 적게 주기 때문에","correct":true},{"t":"재생 에너지는 쓸수록 공기를 더럽히기 때문에","mis":"SC5-2-u4-X20"}],"mis":"SC5-2-u4-X20","explanation":["자연에서 얻어요.","오염을 적게 내요.","환경을 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L03_basic#10','sci',5,2,'u4','L03','g5_2_sci_u4_L03_basic','lesson_basic','SC5-2-u4-C10',3,'error','auto','재생 에너지를 조사하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u4-X19','SC5-2-u4-X21']::text[],false,'{"seq":10,"concept":"SC5-2-u4-C10","difficulty":3,"kind":"error","stem":"재생 에너지를 조사하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하율 — 「재생 에너지는 날씨와 상관없이 늘 같은 양을 얻을 수 있어.」","correct":true,"mis_target":"SC5-2-u4-X19"},{"t":"준서 — 「석탄과 석유는 쓸수록 줄어.」","mis":"SC5-2-u4-X21"},{"t":"민아 — 「재생 에너지는 설치 비용이 많이 들기도 해.」","mis":"SC5-2-u4-X19"}],"explanation":["날씨 영향을 받아요.","양이 달라져요.","하율의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L03_challenge#1','sci',5,2,'u4','L03','g5_2_sci_u4_L03_challenge','lesson_challenge','SC5-2-u4-C8',2,'match','auto','에너지를 얻는 곳과 재생 에너지를 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-2-u4-C8","difficulty":2,"kind":"match","stem":"에너지를 얻는 곳과 재생 에너지를 알맞게 이으세요.","pairs":[{"l":"밀물과 썰물, 파도","r":"해양 에너지"},{"l":"땅속 깊은 곳의 열","r":"지열 에너지"},{"l":"나무, 풀, 가축의 분뇨","r":"바이오 에너지"}],"mis":"SC5-2-u4-X14","explanation":["바다는 해양이에요.","땅속은 지열이에요.","생물은 바이오예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L03_challenge#2','sci',5,2,'u4','L03','g5_2_sci_u4_L03_challenge','lesson_challenge','SC5-2-u4-C9',2,'mc','auto','네 지역의 특징에서 ㉣ 물안개 골짜기에 가장 알맞은 재생 에너지는 어느 것인가요?',ARRAY['SC5-2-u4-X18','SC5-2-u4-X13']::text[],false,'{"seq":2,"concept":"SC5-2-u4-C9","difficulty":2,"kind":"mc","stem":"네 지역의 특징에서 ㉣ 물안개 골짜기에 가장 알맞은 재생 에너지는 어느 것인가요?","options":[{"t":"수력","correct":true},{"t":"바이오 에너지","mis":"SC5-2-u4-X18"},{"t":"지열 에너지","mis":"SC5-2-u4-X18"},{"t":"석유","mis":"SC5-2-u4-X13"}],"explanation":["물이 세차게 흘러요.","떨어지는 물을 써요.","수력이에요."],"asset":{"type":"passage","lines":["㉠ 바람솔섬 — 바다로 둘러싸여 일 년 내내 바람이 세다.","㉡ 해든 들판 — 비가 적고 햇빛이 강하게 내리쬔다.","㉢ 소울 목장 마을 — 가축이 많아 분뇨 처리가 걱정이다.","㉣ 물안개 골짜기 — 산이 깊고 물이 세차게 흘러내린다."],"title":"네 지역의 특징"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L03_challenge#3','sci',5,2,'u4','L03','g5_2_sci_u4_L03_challenge','lesson_challenge','SC5-2-u4-C9',3,'mc','auto','네 지역의 특징에서 ㉠과 ㉢에 알맞은 재생 에너지를 바르게 짝지은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X18']::text[],false,'{"seq":3,"concept":"SC5-2-u4-C9","difficulty":3,"kind":"mc","stem":"네 지역의 특징에서 ㉠과 ㉢에 알맞은 재생 에너지를 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"㉠ 풍력, ㉢ 바이오 에너지","correct":true},{"t":"㉠ 바이오 에너지, ㉢ 풍력","mis":"SC5-2-u4-X18"},{"t":"㉠ 수력, ㉢ 태양 에너지","mis":"SC5-2-u4-X18"},{"t":"㉠ 지열 에너지, ㉢ 해양 에너지","mis":"SC5-2-u4-X18"}],"explanation":["섬은 바람이 세요.","목장은 분뇨가 많아요.","풍력과 바이오예요."],"asset":{"type":"passage","lines":["㉠ 바람솔섬 — 바다로 둘러싸여 일 년 내내 바람이 세다.","㉡ 해든 들판 — 비가 적고 햇빛이 강하게 내리쬔다.","㉢ 소울 목장 마을 — 가축이 많아 분뇨 처리가 걱정이다.","㉣ 물안개 골짜기 — 산이 깊고 물이 세차게 흘러내린다."],"title":"네 지역의 특징"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L03_challenge#4','sci',5,2,'u4','L03','g5_2_sci_u4_L03_challenge','lesson_challenge','SC5-2-u4-C10',3,'mc','auto','재생 에너지가 주목받는 까닭 두 가지를 바르게 모은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X21','SC5-2-u4-X19','SC5-2-u4-X20']::text[],false,'{"seq":4,"concept":"SC5-2-u4-C10","difficulty":3,"kind":"mc","stem":"재생 에너지가 주목받는 까닭 두 가지를 바르게 모은 것은 어느 것인가요?","options":[{"t":"자연에서 계속 얻을 수 있고, 대기오염과 기후변화에 영향을 적게 준다","correct":true},{"t":"땅속에 묻힌 양이 정해져 있고, 태울수록 연기가 많이 난다","mis":"SC5-2-u4-X21"},{"t":"설치 비용이 들지 않고, 어디서나 같은 양을 얻는다","mis":"SC5-2-u4-X19"},{"t":"모양이 멋지고, 크기가 커서 눈에 잘 띈다","mis":"SC5-2-u4-X20"}],"explanation":["계속 얻어요.","환경에 좋아요.","그래서 주목받아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L03_challenge#5','sci',5,2,'u4','L03','g5_2_sci_u4_L03_challenge','lesson_challenge','SC5-2-u4-C8',3,'mc','auto','태양 전지로 햇빛을 받아 전기를 만들어 쓰는 예로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X16','SC5-2-u4-X14','SC5-2-u4-X17']::text[],false,'{"seq":5,"concept":"SC5-2-u4-C8","difficulty":3,"kind":"mc","stem":"태양 전지로 햇빛을 받아 전기를 만들어 쓰는 예로 알맞은 것은 어느 것인가요?","options":[{"t":"태양 전지를 단 가로등과 인공위성","correct":true},{"t":"땅속의 열로 데우는 온천","mis":"SC5-2-u4-X16"},{"t":"바람으로 돌아가는 바람개비","mis":"SC5-2-u4-X14"},{"t":"가축 분뇨로 만든 가스","mis":"SC5-2-u4-X17"}],"explanation":["햇빛을 받아요.","전기를 만들어요.","가로등과 인공위성이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L03_challenge#6','sci',5,2,'u4','L03','g5_2_sci_u4_L03_challenge','lesson_challenge','SC5-2-u4-C8',3,'ox','auto','땅속 깊은 곳은 사계절 내내 온도가 거의 변하지 않아 냉난방에 이용할 수 있어요.',ARRAY['SC5-2-u4-X16']::text[],false,'{"seq":6,"concept":"SC5-2-u4-C8","difficulty":3,"kind":"ox","stem":"땅속 깊은 곳은 사계절 내내 온도가 거의 변하지 않아 냉난방에 이용할 수 있어요.","answer":"O","reason_options":[{"t":"겨울에는 땅 위보다 따뜻하고 여름에는 땅 위보다 시원하기 때문에","correct":true},{"t":"땅속 온도는 여름에 가장 뜨겁고 겨울에 가장 차갑기 때문에","mis":"SC5-2-u4-X16"}],"mis":"SC5-2-u4-X16","explanation":["땅속은 온도가 비슷해요.","겨울엔 따뜻해요.","여름엔 시원해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L03_challenge#7','sci',5,2,'u4','L03','g5_2_sci_u4_L03_challenge','lesson_challenge','SC5-2-u4-C7',3,'error','auto','재생 에너지를 가려내며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u4-X13']::text[],false,'{"seq":7,"concept":"SC5-2-u4-C7","difficulty":3,"kind":"error","stem":"재생 에너지를 가려내며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「석유도 자연에서 캐내니까 재생 에너지야.」","correct":true,"mis_target":"SC5-2-u4-X13"},{"t":"가은 — 「바람은 써도 줄어들지 않아.」","mis":"SC5-2-u4-X13"},{"t":"로하 — 「에너지가 있어야 기계가 움직여.」","mis":"SC5-2-u4-X13"}],"explanation":["석유는 쓸수록 줄어요.","계속 쓸 수 없어요.","태오의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L03_challenge#8','sci',5,2,'u4','L03','g5_2_sci_u4_L03_challenge','lesson_challenge','SC5-2-u4-C10',4,'mc','auto','재생 에너지의 단점을 줄이는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X21','SC5-2-u4-X19','SC5-2-u4-X18']::text[],false,'{"seq":8,"concept":"SC5-2-u4-C10","difficulty":4,"kind":"mc","stem":"재생 에너지의 단점을 줄이는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"날씨에 따라 달라지는 에너지를 모아 두는 기술과 비용을 줄이는 기술을 발전시킨다","correct":true},{"t":"재생 에너지를 모두 없애고 석탄만 쓴다","mis":"SC5-2-u4-X21"},{"t":"단점이 없으니 아무것도 하지 않는다","mis":"SC5-2-u4-X19"},{"t":"바람이 없는 곳에 풍력 발전기를 더 세운다","mis":"SC5-2-u4-X18"}],"explanation":["양이 달라져요.","비용도 들어요.","기술을 발전시켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L03_challenge#9','sci',5,2,'u4','L03','g5_2_sci_u4_L03_challenge','lesson_challenge','SC5-2-u4-C9',4,'mc','auto','네 지역의 특징의 바람솔섬에서 바람이 약한 날에도 에너지를 얻으려면 어떻게 하는 것이 가장 알맞은가요?',ARRAY['SC5-2-u4-X18','SC5-2-u4-X19']::text[],false,'{"seq":9,"concept":"SC5-2-u4-C9","difficulty":4,"kind":"mc","stem":"네 지역의 특징의 바람솔섬에서 바람이 약한 날에도 에너지를 얻으려면 어떻게 하는 것이 가장 알맞은가요?","options":[{"t":"풍력과 함께 섬 둘레 바다의 밀물과 썰물을 쓰는 해양 에너지도 쓴다","correct":true},{"t":"풍력 발전기를 모두 없앤다","mis":"SC5-2-u4-X18"},{"t":"바람이 약한 날에 풍력이 더 많은 에너지를 만든다고 믿는다","mis":"SC5-2-u4-X19"},{"t":"섬에 없는 골짜기의 물을 쓴다","mis":"SC5-2-u4-X18"}],"explanation":["섬은 바다로 둘러싸여요.","바다도 에너지를 줘요.","함께 쓰면 좋아요."],"asset":{"type":"passage","lines":["㉠ 바람솔섬 — 바다로 둘러싸여 일 년 내내 바람이 세다.","㉡ 해든 들판 — 비가 적고 햇빛이 강하게 내리쬔다.","㉢ 소울 목장 마을 — 가축이 많아 분뇨 처리가 걱정이다.","㉣ 물안개 골짜기 — 산이 깊고 물이 세차게 흘러내린다."],"title":"네 지역의 특징"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L03_challenge#10','sci',5,2,'u4','L03','g5_2_sci_u4_L03_challenge','lesson_challenge','SC5-2-u4-C8',4,'essay','teacher','재생 에너지 한 가지를 골라 소개 카드를 쓰세요. 에너지를 얻는 방법, 이용하는 예, 좋은 점을 넣으세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-2-u4-C8","difficulty":4,"kind":"essay","stem":"재생 에너지 한 가지를 골라 소개 카드를 쓰세요. 에너지를 얻는 방법, 이용하는 예, 좋은 점을 넣으세요.","answer_guide":{"answer":"예: 태양 에너지 — 태양 빛이나 태양열을 이용해 에너지를 얻는다. 태양 전지를 단 가로등이나 지붕의 태양 전지판에 쓴다. 자연에서 계속 얻을 수 있고 환경을 덜 오염시킨다.","scoring_points":["재생 에너지를 골라 얻는 방법을 썼는가","이용하는 예를 썼는가","좋은 점(계속 이용·환경)을 썼는가"]},"explanation":["하나를 골라요.","얻는 방법을 써요.","좋은 점을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L04_basic#1','sci',5,2,'u4','L04','g5_2_sci_u4_L04_basic','lesson_basic','SC5-2-u4-C11',1,'mc','auto','지속가능한 에너지의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X22']::text[],false,'{"seq":1,"concept":"SC5-2-u4-C11","difficulty":1,"kind":"mc","stem":"지속가능한 에너지의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"지금 필요를 채우면서 미래 세대도 계속 쓸 수 있게 하는 에너지","correct":true},{"t":"지금 세대만 마음껏 쓰는 에너지","mis":"SC5-2-u4-X22"},{"t":"한 번 쓰면 사라지는 에너지","mis":"SC5-2-u4-X22"},{"t":"미래에는 필요 없는 에너지","mis":"SC5-2-u4-X22"}],"explanation":["지금도 써요.","미래 세대도 써요.","계속 쓸 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L04_basic#2','sci',5,2,'u4','L04','g5_2_sci_u4_L04_basic','lesson_basic','SC5-2-u4-C12',1,'ox','auto','사람이 없는 교실의 전등과 전기 기구를 끄는 것은 에너지를 지속가능하게 이용하는 방법이에요.',ARRAY['SC5-2-u4-X23']::text[],false,'{"seq":2,"concept":"SC5-2-u4-C12","difficulty":1,"kind":"ox","stem":"사람이 없는 교실의 전등과 전기 기구를 끄는 것은 에너지를 지속가능하게 이용하는 방법이에요.","answer":"O","reason_options":[{"t":"불필요한 에너지 사용을 줄이기 때문에","correct":true},{"t":"사람이 없어도 켜 두어야 에너지가 늘어나기 때문에","mis":"SC5-2-u4-X23"}],"mis":"SC5-2-u4-X23","explanation":["사람이 없어요.","켜 둘 필요가 없어요.","꺼서 아껴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L04_basic#3','sci',5,2,'u4','L04','g5_2_sci_u4_L04_basic','lesson_basic','SC5-2-u4-C12',1,'mc','auto','에너지 이용 놀이판의 ⑤ 칸에 도착하면 말을 어떻게 옮기나요?',ARRAY['SC5-2-u4-X23']::text[],false,'{"seq":3,"concept":"SC5-2-u4-C12","difficulty":1,"kind":"mc","stem":"에너지 이용 놀이판의 ⑤ 칸에 도착하면 말을 어떻게 옮기나요?","options":[{"t":"사다리를 타고 위로 올라간다","correct":true},{"t":"미끄럼틀을 타고 아래로 내려간다","mis":"SC5-2-u4-X23"},{"t":"출발점으로 돌아간다","mis":"SC5-2-u4-X23"},{"t":"그 자리에서 놀이가 끝난다","mis":"SC5-2-u4-X23"}],"explanation":["⑤는 태양 전지판이에요.","지속가능한 예예요.","사다리로 올라가요."],"asset":{"type":"passage","lines":["① 냉난방할 때 알맞은 온도 지키기","② 창문을 연 채 난방 켜기","③ 가까운 곳은 걷거나 자전거 타기","④ 빈방에 조명 켜 두기","⑤ 지붕에 태양 전지판 달기","⑥ 보지 않는 텔레비전 켜 두기","⑦ 여러 나라가 함께 에너지 문제 풀기","⑧ 가까운 거리도 늘 자동차 타기"],"title":"에너지 이용 놀이판의 칸"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L04_basic#4','sci',5,2,'u4','L04','g5_2_sci_u4_L04_basic','lesson_basic','SC5-2-u4-C13',1,'mc','auto','에너지를 지속가능하게 이용하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X21','SC5-2-u4-X23']::text[],false,'{"seq":4,"concept":"SC5-2-u4-C13","difficulty":1,"kind":"mc","stem":"에너지를 지속가능하게 이용하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"태양 에너지, 풍력 같은 재생 에너지를 쓴다","correct":true},{"t":"석유를 더 많이 태운다","mis":"SC5-2-u4-X21"},{"t":"빈방 전등을 켜 둔다","mis":"SC5-2-u4-X23"},{"t":"가까운 거리도 늘 자동차를 탄다","mis":"SC5-2-u4-X23"}],"explanation":["재생 에너지예요.","계속 쓸 수 있어요.","지속가능해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L04_basic#5','sci',5,2,'u4','L04','g5_2_sci_u4_L04_basic','lesson_basic','SC5-2-u4-C12',2,'mc','auto','에너지 이용 놀이판에서 미끄럼틀을 타고 내려가는 칸끼리 모은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X23']::text[],false,'{"seq":5,"concept":"SC5-2-u4-C12","difficulty":2,"kind":"mc","stem":"에너지 이용 놀이판에서 미끄럼틀을 타고 내려가는 칸끼리 모은 것은 어느 것인가요?","options":[{"t":"②, ④, ⑥, ⑧","correct":true},{"t":"①, ③, ⑤, ⑦","mis":"SC5-2-u4-X23"},{"t":"①, ②, ③, ④","mis":"SC5-2-u4-X23"},{"t":"⑤, ⑥, ⑦, ⑧","mis":"SC5-2-u4-X23"}],"explanation":["낭비하는 칸이에요.","짝수 칸이에요.","미끄럼틀이에요."],"asset":{"type":"passage","lines":["① 냉난방할 때 알맞은 온도 지키기","② 창문을 연 채 난방 켜기","③ 가까운 곳은 걷거나 자전거 타기","④ 빈방에 조명 켜 두기","⑤ 지붕에 태양 전지판 달기","⑥ 보지 않는 텔레비전 켜 두기","⑦ 여러 나라가 함께 에너지 문제 풀기","⑧ 가까운 거리도 늘 자동차 타기"],"title":"에너지 이용 놀이판의 칸"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L04_basic#6','sci',5,2,'u4','L04','g5_2_sci_u4_L04_basic','lesson_basic','SC5-2-u4-C11',2,'mc','auto','에너지를 지속가능하게 이용해야 하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X22','SC5-2-u4-X21','SC5-2-u4-X19']::text[],false,'{"seq":6,"concept":"SC5-2-u4-C11","difficulty":2,"kind":"mc","stem":"에너지를 지속가능하게 이용해야 하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"미래 세대도 깨끗한 에너지를 쓰고 기후변화에 대응하기 위해서","correct":true},{"t":"지금 세대가 에너지를 더 많이 쓰기 위해서","mis":"SC5-2-u4-X22"},{"t":"석탄과 석유를 빨리 다 쓰기 위해서","mis":"SC5-2-u4-X21"},{"t":"재생 에너지가 이미 넘칠 만큼 많아서","mis":"SC5-2-u4-X19"}],"explanation":["미래 세대가 있어요.","기후변화도 있어요.","그래서 지속가능하게 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L04_basic#7','sci',5,2,'u4','L04','g5_2_sci_u4_L04_basic','lesson_basic','SC5-2-u4-C13',2,'ox','auto','전기차나 수소차처럼 환경오염에 영향을 적게 주는 친환경 기술을 개발하는 것도 지속가능한 방법이에요.',ARRAY['SC5-2-u4-X24']::text[],false,'{"seq":7,"concept":"SC5-2-u4-C13","difficulty":2,"kind":"ox","stem":"전기차나 수소차처럼 환경오염에 영향을 적게 주는 친환경 기술을 개발하는 것도 지속가능한 방법이에요.","answer":"O","reason_options":[{"t":"환경을 덜 오염시키고 에너지 문제를 푸는 데 도움이 되기 때문에","correct":true},{"t":"지속가능한 방법은 에너지를 아끼는 것 한 가지뿐이기 때문에","mis":"SC5-2-u4-X24"}],"mis":"SC5-2-u4-X24","explanation":["친환경 기술이에요.","오염을 줄여요.","지속가능해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L04_basic#8','sci',5,2,'u4','L04','g5_2_sci_u4_L04_basic','lesson_basic','SC5-2-u4-C13',2,'mc','auto','학교에서 에너지를 지속가능하게 이용하려고 실천할 수 있는 일은 어느 것인가요?',ARRAY['SC5-2-u4-X23','SC5-2-u4-X25']::text[],false,'{"seq":8,"concept":"SC5-2-u4-C13","difficulty":2,"kind":"mc","stem":"학교에서 에너지를 지속가능하게 이용하려고 실천할 수 있는 일은 어느 것인가요?","options":[{"t":"이동 수업을 갈 때 교실 전등을 끈다","correct":true},{"t":"겨울에 난방을 켜고 교실 문을 활짝 열어 둔다","mis":"SC5-2-u4-X23"},{"t":"쓰지 않는 전기 기구 플러그를 꽂아 둔다","mis":"SC5-2-u4-X25"},{"t":"에어컨을 켠 채 창문을 연다","mis":"SC5-2-u4-X23"}],"explanation":["교실이 비어요.","전등을 꺼요.","에너지를 아껴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L04_basic#9','sci',5,2,'u4','L04','g5_2_sci_u4_L04_basic','lesson_basic','SC5-2-u4-C11',2,'mc','auto','석탄과 석유로 에너지를 얻을 때 생기는 문제로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X21','SC5-2-u4-X22']::text[],false,'{"seq":9,"concept":"SC5-2-u4-C11","difficulty":2,"kind":"mc","stem":"석탄과 석유로 에너지를 얻을 때 생기는 문제로 알맞은 것은 어느 것인가요?","options":[{"t":"양이 한정되어 있고 대기오염과 기후변화를 일으킬 수 있다","correct":true},{"t":"양이 끝없이 많다","mis":"SC5-2-u4-X21"},{"t":"공기를 깨끗하게 만든다","mis":"SC5-2-u4-X21"},{"t":"미래 세대에게만 도움이 된다","mis":"SC5-2-u4-X22"}],"explanation":["양이 정해져 있어요.","공기를 더럽혀요.","문제가 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L04_basic#10','sci',5,2,'u4','L04','g5_2_sci_u4_L04_basic','lesson_basic','SC5-2-u4-C12',3,'error','auto','놀이를 마치고 칸을 나누며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u4-X23','SC5-2-u4-X24']::text[],false,'{"seq":10,"concept":"SC5-2-u4-C12","difficulty":3,"kind":"error","stem":"놀이를 마치고 칸을 나누며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"이든 — 「창문을 연 채 난방을 하면 시원하니까 지속가능한 방법이야.」","correct":true,"mis_target":"SC5-2-u4-X23"},{"t":"소윤 — 「친환경 제품을 쓰면 에너지를 아낄 수 있어.」","mis":"SC5-2-u4-X23"},{"t":"라희 — 「여러 나라가 협력하는 것도 도움이 돼.」","mis":"SC5-2-u4-X24"}],"explanation":["열이 빠져나가요.","에너지를 낭비해요.","이든의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L04_challenge#1','sci',5,2,'u4','L04','g5_2_sci_u4_L04_challenge','lesson_challenge','SC5-2-u4-C13',2,'match','auto','에너지를 지속가능하게 이용하는 일과 그 갈래를 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-2-u4-C13","difficulty":2,"kind":"match","stem":"에너지를 지속가능하게 이용하는 일과 그 갈래를 알맞게 이으세요.","pairs":[{"l":"바람으로 전기를 만드는 발전기를 세운다","r":"재생 에너지 얻기"},{"l":"전기차와 수소차를 연구한다","r":"친환경 기술 개발"},{"l":"쓰지 않는 전등을 끈다","r":"불필요한 사용 줄이기"}],"mis":"SC5-2-u4-X24","explanation":["발전기는 재생 에너지예요.","연구는 기술이에요.","끄는 건 절약이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L04_challenge#2','sci',5,2,'u4','L04','g5_2_sci_u4_L04_challenge','lesson_challenge','SC5-2-u4-C12',2,'mc','auto','에너지를 지속가능하게 이용하지 않은 예는 어느 것인가요?',ARRAY['SC5-2-u4-X23']::text[],false,'{"seq":2,"concept":"SC5-2-u4-C12","difficulty":2,"kind":"mc","stem":"에너지를 지속가능하게 이용하지 않은 예는 어느 것인가요?","options":[{"t":"석유로 에너지를 얻어 이산화 탄소가 많이 생긴다","correct":true},{"t":"에너지 절약 캠페인에 참여한다","mis":"SC5-2-u4-X23"},{"t":"수력과 풍력을 이용한다","mis":"SC5-2-u4-X23"},{"t":"친환경 제품을 쓴다","mis":"SC5-2-u4-X23"}],"explanation":["석유를 태워요.","이산화 탄소가 생겨요.","지속가능하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L04_challenge#3','sci',5,2,'u4','L04','g5_2_sci_u4_L04_challenge','lesson_challenge','SC5-2-u4-C11',3,'mc','auto','재생 에너지는 계속 쓸 수 있는데도 에너지를 아껴 써야 하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X13','SC5-2-u4-X20','SC5-2-u4-X42']::text[],false,'{"seq":3,"concept":"SC5-2-u4-C11","difficulty":3,"kind":"mc","stem":"재생 에너지는 계속 쓸 수 있는데도 에너지를 아껴 써야 하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"지금은 재생 에너지 생산량이 충분하지 않기 때문이다","correct":true},{"t":"재생 에너지는 쓰면 금방 사라지기 때문이다","mis":"SC5-2-u4-X13"},{"t":"재생 에너지가 환경을 가장 많이 오염시키기 때문이다","mis":"SC5-2-u4-X20"},{"t":"아낄 필요가 전혀 없다","mis":"SC5-2-u4-X42"}],"explanation":["계속 쓸 수 있어요.","하지만 아직 모자라요.","아껴야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L04_challenge#4','sci',5,2,'u4','L04','g5_2_sci_u4_L04_challenge','lesson_challenge','SC5-2-u4-C13',3,'mc','auto','「에너지를 지속가능하게 쓰려면 재생 에너지만 있으면 돼.」를 바르게 고친 것은 어느 것인가요?',ARRAY['SC5-2-u4-X24','SC5-2-u4-X21','SC5-2-u4-X22']::text[],false,'{"seq":4,"concept":"SC5-2-u4-C13","difficulty":3,"kind":"mc","stem":"「에너지를 지속가능하게 쓰려면 재생 에너지만 있으면 돼.」를 바르게 고친 것은 어느 것인가요?","options":[{"t":"재생 에너지와 함께 친환경 기술 개발과 절약도 같이 해야 한다","correct":true},{"t":"고칠 것이 없으니 절약은 필요 없다","mis":"SC5-2-u4-X24"},{"t":"재생 에너지는 쓰지 말고 석유만 쓴다","mis":"SC5-2-u4-X21"},{"t":"미래 세대는 에너지가 필요 없다","mis":"SC5-2-u4-X22"}],"explanation":["세 갈래가 있어요.","함께 해야 해요.","하나로는 부족해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L04_challenge#5','sci',5,2,'u4','L04','g5_2_sci_u4_L04_challenge','lesson_challenge','SC5-2-u4-C12',3,'ox','auto','에너지를 많이 소모하는 기계를 공장에서 계속 쓰는 것은 에너지를 지속가능하게 이용하는 예예요.',ARRAY['SC5-2-u4-X23']::text[],false,'{"seq":5,"concept":"SC5-2-u4-C12","difficulty":3,"kind":"ox","stem":"에너지를 많이 소모하는 기계를 공장에서 계속 쓰는 것은 에너지를 지속가능하게 이용하는 예예요.","answer":"X","reason_options":[{"t":"필요 이상으로 에너지를 많이 써 낭비가 되기 때문에","correct":true},{"t":"에너지를 많이 쓸수록 미래 세대에 도움이 되기 때문에","mis":"SC5-2-u4-X23"}],"mis":"SC5-2-u4-X23","explanation":["에너지를 많이 써요.","낭비예요.","지속가능하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L04_challenge#6','sci',5,2,'u4','L04','g5_2_sci_u4_L04_challenge','lesson_challenge','SC5-2-u4-C11',3,'error','auto','지속가능한 에너지를 토의하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u4-X22']::text[],false,'{"seq":6,"concept":"SC5-2-u4-C11","difficulty":3,"kind":"error","stem":"지속가능한 에너지를 토의하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"규리 — 「미래 세대는 알아서 하겠지. 지금 우리가 마음껏 쓰면 돼.」","correct":true,"mis_target":"SC5-2-u4-X22"},{"t":"수아 — 「미래 세대도 에너지가 필요해.」","mis":"SC5-2-u4-X22"},{"t":"해온 — 「기후변화에도 대응해야 해.」","mis":"SC5-2-u4-X22"}],"explanation":["미래 세대도 써요.","마음껏 쓰면 안 돼요.","규리의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L04_challenge#7','sci',5,2,'u4','L04','g5_2_sci_u4_L04_challenge','lesson_challenge','SC5-2-u4-C13',3,'mc','auto','겨울철 교실에서 에너지를 지속가능하게 쓰는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X23']::text[],false,'{"seq":7,"concept":"SC5-2-u4-C13","difficulty":3,"kind":"mc","stem":"겨울철 교실에서 에너지를 지속가능하게 쓰는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"난방 중에는 열이 빠져나가지 않게 문과 창문을 닫는다","correct":true},{"t":"난방을 가장 세게 켜고 창문을 연다","mis":"SC5-2-u4-X23"},{"t":"복도 전등까지 모두 켜 둔다","mis":"SC5-2-u4-X23"},{"t":"빈 교실 난방기를 켜 둔다","mis":"SC5-2-u4-X23"}],"explanation":["난방 중이에요.","열이 나가면 안 돼요.","문을 닫아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L04_challenge#8','sci',5,2,'u4','L04','g5_2_sci_u4_L04_challenge','lesson_challenge','SC5-2-u4-C12',4,'mc','auto','에너지 이용 놀이판의 미끄럼틀 칸을 사다리 칸으로 바르게 바꾼 것은 어느 것인가요?',ARRAY['SC5-2-u4-X23']::text[],false,'{"seq":8,"concept":"SC5-2-u4-C12","difficulty":4,"kind":"mc","stem":"에너지 이용 놀이판의 미끄럼틀 칸을 사다리 칸으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"④ 빈방에 조명 켜 두기 → 방을 나설 때 조명 끄기","correct":true},{"t":"② 창문을 연 채 난방 켜기 → 난방을 더 세게 켜기","mis":"SC5-2-u4-X23"},{"t":"⑧ 가까운 거리도 늘 자동차 타기 → 더 큰 자동차 타기","mis":"SC5-2-u4-X23"},{"t":"⑥ 보지 않는 텔레비전 켜 두기 → 소리만 줄이기","mis":"SC5-2-u4-X23"}],"explanation":["낭비를 찾아요.","불필요한 사용을 끊어요.","④를 바르게 바꿨어요."],"asset":{"type":"passage","lines":["① 냉난방할 때 알맞은 온도 지키기","② 창문을 연 채 난방 켜기","③ 가까운 곳은 걷거나 자전거 타기","④ 빈방에 조명 켜 두기","⑤ 지붕에 태양 전지판 달기","⑥ 보지 않는 텔레비전 켜 두기","⑦ 여러 나라가 함께 에너지 문제 풀기","⑧ 가까운 거리도 늘 자동차 타기"],"title":"에너지 이용 놀이판의 칸"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L04_challenge#9','sci',5,2,'u4','L04','g5_2_sci_u4_L04_challenge','lesson_challenge','SC5-2-u4-C11',4,'mc','auto','에너지를 지속가능하게 이용하는 태도로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X22','SC5-2-u4-X42','SC5-2-u4-X21']::text[],false,'{"seq":9,"concept":"SC5-2-u4-C11","difficulty":4,"kind":"mc","stem":"에너지를 지속가능하게 이용하는 태도로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"에너지 문제를 내 일로 여기고 생활 속 작은 실천부터 꾸준히 한다","correct":true},{"t":"어른들이 할 일이라 나와는 상관없다","mis":"SC5-2-u4-X22"},{"t":"재생 에너지가 있으니 낭비해도 된다","mis":"SC5-2-u4-X42"},{"t":"석유를 아끼려고 석탄을 더 쓴다","mis":"SC5-2-u4-X21"}],"explanation":["내 일이에요.","작은 실천부터요.","꾸준히 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L04_challenge#10','sci',5,2,'u4','L04','g5_2_sci_u4_L04_challenge','lesson_challenge','SC5-2-u4-C11',4,'essay','teacher','에너지를 지속가능하게 이용해야 하는 까닭을 두 가지 쓰고, 내가 학교에서 실천할 수 있는 방법을 하나 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-2-u4-C11","difficulty":4,"kind":"essay","stem":"에너지를 지속가능하게 이용해야 하는 까닭을 두 가지 쓰고, 내가 학교에서 실천할 수 있는 방법을 하나 쓰세요.","answer_guide":{"answer":"예: 석탄과 석유는 양이 한정되어 있어 계속 쓸 수 없다. 또 대기오염과 기후변화를 일으키므로 미래 세대도 깨끗한 에너지를 쓸 수 있게 해야 한다. 나는 이동 수업 때 교실 전등을 끄겠다.","scoring_points":["까닭 하나(한정·고갈)를 썼는가","까닭 하나(환경·미래 세대)를 썼는가","학교에서 실천할 방법을 썼는가"]},"explanation":["까닭 두 가지예요.","미래 세대를 생각해요.","실천을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L05_basic#1','sci',5,2,'u4','L05','g5_2_sci_u4_L05_basic','lesson_basic','SC5-2-u4-C14',1,'mc','auto','효율이 좋은 전등은 어느 것인가요?',ARRAY['SC5-2-u4-X26']::text[],false,'{"seq":1,"concept":"SC5-2-u4-C14","difficulty":1,"kind":"mc","stem":"효율이 좋은 전등은 어느 것인가요?","options":[{"t":"같은 밝기를 내면서 전기를 적게 쓰는 전등","correct":true},{"t":"같은 밝기를 내면서 전기를 많이 쓰는 전등","mis":"SC5-2-u4-X26"},{"t":"전기를 많이 써 가장 뜨거운 전등","mis":"SC5-2-u4-X26"},{"t":"불을 켜도 어두운 전등","mis":"SC5-2-u4-X26"}],"explanation":["밝기가 같아요.","전기를 적게 써요.","효율이 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L05_basic#2','sci',5,2,'u4','L05','g5_2_sci_u4_L05_basic','lesson_basic','SC5-2-u4-C14',1,'mc','auto','에너지 소비 효율 등급에서 효율이 가장 높은 등급은 어느 것인가요?',ARRAY['SC5-2-u4-X27']::text[],false,'{"seq":2,"concept":"SC5-2-u4-C14","difficulty":1,"kind":"mc","stem":"에너지 소비 효율 등급에서 효율이 가장 높은 등급은 어느 것인가요?","options":[{"t":"1등급","correct":true},{"t":"5등급","mis":"SC5-2-u4-X27"},{"t":"3등급","mis":"SC5-2-u4-X27"},{"t":"등급과 효율은 상관없다","mis":"SC5-2-u4-X27"}],"explanation":["1~5등급이 있어요.","1등급에 가까울수록요.","1등급이 가장 높아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L05_basic#3','sci',5,2,'u4','L05','g5_2_sci_u4_L05_basic','lesson_basic','SC5-2-u4-C15',1,'ox','auto','빗물 저금통에 빗물을 모아 다시 쓰면 물 자원을 효율적으로 이용할 수 있어요.',ARRAY['SC5-2-u4-X07']::text[],false,'{"seq":3,"concept":"SC5-2-u4-C15","difficulty":1,"kind":"ox","stem":"빗물 저금통에 빗물을 모아 다시 쓰면 물 자원을 효율적으로 이용할 수 있어요.","answer":"O","reason_options":[{"t":"그냥 흘러가 버릴 빗물을 모아 다시 쓰기 때문에","correct":true},{"t":"빗물을 모으면 지구의 물이 새로 늘어나기 때문에","mis":"SC5-2-u4-X07"}],"mis":"SC5-2-u4-X07","explanation":["빗물을 모아요.","다시 써요.","물을 아껴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L05_basic#4','sci',5,2,'u4','L05','g5_2_sci_u4_L05_basic','lesson_basic','SC5-2-u4-C15',1,'mc','auto','산림 자원을 효율적으로 이용하는 방법은 어느 것인가요?',ARRAY['SC5-2-u4-X28']::text[],false,'{"seq":4,"concept":"SC5-2-u4-C15","difficulty":1,"kind":"mc","stem":"산림 자원을 효율적으로 이용하는 방법은 어느 것인가요?","options":[{"t":"종이 영수증 대신 전자 영수증을 받는다","correct":true},{"t":"종이컵을 한 번 쓰고 버린다","mis":"SC5-2-u4-X28"},{"t":"과대 포장된 물건을 산다","mis":"SC5-2-u4-X28"},{"t":"이면지를 모두 버린다","mis":"SC5-2-u4-X28"}],"explanation":["영수증은 종이예요.","전자로 받아요.","나무를 아껴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L05_basic#5','sci',5,2,'u4','L05','g5_2_sci_u4_L05_basic','lesson_basic','SC5-2-u4-C14',2,'mc','auto','우리 교실 살펴보기 ①에서 에너지가 낭비되는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X25','SC5-2-u4-X29']::text[],false,'{"seq":5,"concept":"SC5-2-u4-C14","difficulty":2,"kind":"mc","stem":"우리 교실 살펴보기 ①에서 에너지가 낭비되는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"꺼 둔 기계도 플러그가 꽂혀 있으면 전기가 조금씩 쓰이기 때문이다","correct":true},{"t":"꺼 둔 기계는 플러그가 꽂혀 있어도 전기가 전혀 쓰이지 않기 때문이다","mis":"SC5-2-u4-X25"},{"t":"플러그를 꽂아 두면 전기가 새로 만들어지기 때문이다","mis":"SC5-2-u4-X29"},{"t":"공기 청정기는 원래 전기를 쓰지 않기 때문이다","mis":"SC5-2-u4-X25"}],"explanation":["전원은 꺼져 있어요.","플러그는 꽂혀 있어요.","전기가 조금씩 새요."],"asset":{"type":"passage","lines":["① 꺼 둔 공기 청정기의 플러그가 꽂혀 있다.","② 종이컵을 하루에 열 개씩 쓰고 버린다.","③ 양치할 때 물을 계속 틀어 놓는다.","④ 이면지 상자가 늘 비어 있다.","⑤ 교실 전등을 LED 조명으로 바꾸었다."],"title":"우리 교실 살펴보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L05_basic#6','sci',5,2,'u4','L05','g5_2_sci_u4_L05_basic','lesson_basic','SC5-2-u4-C15',2,'mc','auto','우리 교실 살펴보기 ③을 고치는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X28','SC5-2-u4-X30']::text[],false,'{"seq":6,"concept":"SC5-2-u4-C15","difficulty":2,"kind":"mc","stem":"우리 교실 살펴보기 ③을 고치는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"양치 컵에 물을 받아 양치한다","correct":true},{"t":"물을 더 세게 틀어 놓는다","mis":"SC5-2-u4-X28"},{"t":"물 대신 종이를 아낀다","mis":"SC5-2-u4-X30"},{"t":"수도꼭지를 분리배출한다","mis":"SC5-2-u4-X30"}],"explanation":["물을 틀어 놓았어요.","컵에 받아요.","물을 아껴요."],"asset":{"type":"passage","lines":["① 꺼 둔 공기 청정기의 플러그가 꽂혀 있다.","② 종이컵을 하루에 열 개씩 쓰고 버린다.","③ 양치할 때 물을 계속 틀어 놓는다.","④ 이면지 상자가 늘 비어 있다.","⑤ 교실 전등을 LED 조명으로 바꾸었다."],"title":"우리 교실 살펴보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L05_basic#7','sci',5,2,'u4','L05','g5_2_sci_u4_L05_basic','lesson_basic','SC5-2-u4-C16',2,'mc','auto','에너지를 효율적으로 이용하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X27','SC5-2-u4-X29','SC5-2-u4-X25']::text[],false,'{"seq":7,"concept":"SC5-2-u4-C16","difficulty":2,"kind":"mc","stem":"에너지를 효율적으로 이용하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"1등급에 가까운 제품과 LED 조명을 쓴다","correct":true},{"t":"5등급 제품을 골라 쓴다","mis":"SC5-2-u4-X27"},{"t":"에너지 생산을 줄이고 사용을 늘린다","mis":"SC5-2-u4-X29"},{"t":"쓰지 않는 전기 기구를 켜 둔다","mis":"SC5-2-u4-X25"}],"explanation":["등급을 봐요.","LED 조명이에요.","효율적이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L05_basic#8','sci',5,2,'u4','L05','g5_2_sci_u4_L05_basic','lesson_basic','SC5-2-u4-C15',2,'ox','auto','분리배출을 잘하면 버려질 광물 자원을 재활용할 수 있어요.',ARRAY['SC5-2-u4-X30']::text[],false,'{"seq":8,"concept":"SC5-2-u4-C15","difficulty":2,"kind":"ox","stem":"분리배출을 잘하면 버려질 광물 자원을 재활용할 수 있어요.","answer":"O","reason_options":[{"t":"섞인 쓰레기를 종류별로 나누면 다시 쓸 수 있기 때문에","correct":true},{"t":"분리배출은 물 자원만 아끼는 방법이기 때문에","mis":"SC5-2-u4-X30"}],"mis":"SC5-2-u4-X30","explanation":["종류별로 나눠요.","혼합물의 분리예요.","다시 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L05_basic#9','sci',5,2,'u4','L05','g5_2_sci_u4_L05_basic','lesson_basic','SC5-2-u4-C16',2,'mc','auto','절전 멀티탭을 쓰는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X26','SC5-2-u4-X25']::text[],false,'{"seq":9,"concept":"SC5-2-u4-C16","difficulty":2,"kind":"mc","stem":"절전 멀티탭을 쓰는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"쓰지 않을 때 단추 하나로 전기를 끊어 새는 전기를 막으려고","correct":true},{"t":"전기를 더 많이 쓰려고","mis":"SC5-2-u4-X26"},{"t":"꺼 둔 기계는 원래 전기를 안 쓰니 필요 없다","mis":"SC5-2-u4-X25"},{"t":"전기 기구를 더 세게 작동시키려고","mis":"SC5-2-u4-X26"}],"explanation":["단추로 끊어요.","새는 전기를 막아요.","에너지를 아껴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L05_basic#10','sci',5,2,'u4','L05','g5_2_sci_u4_L05_basic','lesson_basic','SC5-2-u4-C16',3,'error','auto','두 냉장고의 등급 표시를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u4-X27','SC5-2-u4-X26']::text[],false,'{"seq":10,"concept":"SC5-2-u4-C16","difficulty":3,"kind":"error","stem":"두 냉장고의 등급 표시를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태린 — 「4등급인 ㉯가 숫자가 더 크니까 효율이 더 높아.」","correct":true,"mis_target":"SC5-2-u4-X27"},{"t":"윤재 — 「㉮가 같은 일을 하며 전기를 덜 써.」","mis":"SC5-2-u4-X26"},{"t":"하린 — 「1등급에 가까울수록 효율이 높아.」","mis":"SC5-2-u4-X27"}],"explanation":["1등급에 가까울수록요.","㉮가 효율이 높아요.","태린의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["냉장고 ㉮ — 에너지 소비 효율 1등급","냉장고 ㉯ — 에너지 소비 효율 4등급","두 냉장고는 크기와 기능이 같다."],"title":"두 냉장고의 등급 표시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L05_challenge#1','sci',5,2,'u4','L05','g5_2_sci_u4_L05_challenge','lesson_challenge','SC5-2-u4-C15',2,'match','auto','자원을 효율적으로 이용하는 방법과 주로 아끼는 자원을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-2-u4-C15","difficulty":2,"kind":"match","stem":"자원을 효율적으로 이용하는 방법과 주로 아끼는 자원을 알맞게 이으세요.","pairs":[{"l":"빗물 저금통","r":"물 자원"},{"l":"이면지 쓰기","r":"산림 자원"},{"l":"캔 분리배출","r":"광물 자원"}],"mis":"SC5-2-u4-X30","explanation":["빗물은 물이에요.","종이는 나무예요.","캔은 광물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L05_challenge#2','sci',5,2,'u4','L05','g5_2_sci_u4_L05_challenge','lesson_challenge','SC5-2-u4-C14',2,'mc','auto','전기 기구를 껐는데도 플러그를 꽂아 두기만 해서 쓰이는 전기를 줄이는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X25','SC5-2-u4-X26']::text[],false,'{"seq":2,"concept":"SC5-2-u4-C14","difficulty":2,"kind":"mc","stem":"전기 기구를 껐는데도 플러그를 꽂아 두기만 해서 쓰이는 전기를 줄이는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"쓰지 않을 때는 플러그를 뽑는다","correct":true},{"t":"플러그를 더 깊게 꽂는다","mis":"SC5-2-u4-X25"},{"t":"전원 단추만 여러 번 누른다","mis":"SC5-2-u4-X25"},{"t":"멀티탭을 두 개 이어 쓴다","mis":"SC5-2-u4-X26"}],"explanation":["꽂혀만 있어도 써요.","플러그를 뽑아요.","새는 전기를 막아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L05_challenge#3','sci',5,2,'u4','L05','g5_2_sci_u4_L05_challenge','lesson_challenge','SC5-2-u4-C16',3,'mc','auto','두 냉장고의 등급 표시에서 ㉮를 고르는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X27','SC5-2-u4-X26']::text[],false,'{"seq":3,"concept":"SC5-2-u4-C16","difficulty":3,"kind":"mc","stem":"두 냉장고의 등급 표시에서 ㉮를 고르는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"크기와 기능이 같으면서 전기를 덜 써 에너지와 돈을 아낄 수 있어서","correct":true},{"t":"숫자가 작아 효율이 낮아서","mis":"SC5-2-u4-X27"},{"t":"전기를 더 많이 써서 더 시원해서","mis":"SC5-2-u4-X26"},{"t":"등급은 겉모양을 알려 주는 표시라서","mis":"SC5-2-u4-X27"}],"explanation":["크기·기능이 같아요.","1등급이에요.","전기를 덜 써요."],"asset":{"type":"passage","lines":["냉장고 ㉮ — 에너지 소비 효율 1등급","냉장고 ㉯ — 에너지 소비 효율 4등급","두 냉장고는 크기와 기능이 같다."],"title":"두 냉장고의 등급 표시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L05_challenge#4','sci',5,2,'u4','L05','g5_2_sci_u4_L05_challenge','lesson_challenge','SC5-2-u4-C15',3,'mc','auto','자원을 가장 효율적으로 이용한 친구는 누구인가요?',ARRAY['SC5-2-u4-X28']::text[],false,'{"seq":4,"concept":"SC5-2-u4-C15","difficulty":3,"kind":"mc","stem":"자원을 가장 효율적으로 이용한 친구는 누구인가요?","options":[{"t":"장바구니를 들고 가 과대 포장 없는 물건을 산 은솔","correct":true},{"t":"가까운 편의점까지 자동차를 탄 지후","mis":"SC5-2-u4-X28"},{"t":"물을 틀어 놓고 비누칠을 한 서아","mis":"SC5-2-u4-X28"},{"t":"새 공책을 한 장만 쓰고 버린 하람","mis":"SC5-2-u4-X28"}],"explanation":["장바구니를 써요.","포장을 줄여요.","은솔이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L05_challenge#5','sci',5,2,'u4','L05','g5_2_sci_u4_L05_challenge','lesson_challenge','SC5-2-u4-C16',3,'ox','auto','외벽과 창틀에 단열을 하는 것도 에너지를 효율적으로 이용하는 방법이에요.',ARRAY['SC5-2-u4-X36']::text[],false,'{"seq":5,"concept":"SC5-2-u4-C16","difficulty":3,"kind":"ox","stem":"외벽과 창틀에 단열을 하는 것도 에너지를 효율적으로 이용하는 방법이에요.","answer":"O","reason_options":[{"t":"집 안 열이 빠져나가는 것을 막아 냉난방 에너지를 덜 쓰기 때문에","correct":true},{"t":"단열재가 스스로 열을 만들어 집을 데우기 때문에","mis":"SC5-2-u4-X36"}],"mis":"SC5-2-u4-X36","explanation":["열이 빠져나가요.","단열로 막아요.","에너지를 덜 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L05_challenge#6','sci',5,2,'u4','L05','g5_2_sci_u4_L05_challenge','lesson_challenge','SC5-2-u4-C16',3,'error','auto','에너지를 효율적으로 쓰는 방법을 나누며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u4-X29']::text[],false,'{"seq":6,"concept":"SC5-2-u4-C16","difficulty":3,"kind":"error","stem":"에너지를 효율적으로 쓰는 방법을 나누며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민규 — 「에너지 생산을 줄이고 사용을 늘리면 효율적으로 쓰는 거야.」","correct":true,"mis_target":"SC5-2-u4-X29"},{"t":"세아 — 「태양 에너지를 쓰는 것도 방법이야.」","mis":"SC5-2-u4-X29"},{"t":"도하 — 「냉난방 온도를 알맞게 지켜.」","mis":"SC5-2-u4-X29"}],"explanation":["덜 써야 해요.","사용을 늘리면 낭비예요.","민규의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L05_challenge#7','sci',5,2,'u4','L05','g5_2_sci_u4_L05_challenge','lesson_challenge','SC5-2-u4-C15',3,'mc','auto','움직임을 알아차리는 센서가 달린 수도꼭지가 물 절약에 좋은 까닭은 어느 것인가요?',ARRAY['SC5-2-u4-X28','SC5-2-u4-X07','SC5-2-u4-X30']::text[],false,'{"seq":7,"concept":"SC5-2-u4-C15","difficulty":3,"kind":"mc","stem":"움직임을 알아차리는 센서가 달린 수도꼭지가 물 절약에 좋은 까닭은 어느 것인가요?","options":[{"t":"손을 떼면 물이 저절로 멈춰 낭비되는 물을 줄인다","correct":true},{"t":"물을 끊임없이 흘려보낸다","mis":"SC5-2-u4-X28"},{"t":"지구의 물을 새로 만들어 낸다","mis":"SC5-2-u4-X07"},{"t":"물 대신 나무를 아낀다","mis":"SC5-2-u4-X30"}],"explanation":["손을 떼요.","물이 멈춰요.","물을 아껴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L05_challenge#8','sci',5,2,'u4','L05','g5_2_sci_u4_L05_challenge','lesson_challenge','SC5-2-u4-C14',4,'mc','auto','밝기가 같은 전등 ㉠은 한 시간에 전기를 10만큼, 전등 ㉡은 60만큼 써요. 효율이 더 좋은 전등과 그 까닭은 어느 것인가요?',ARRAY['SC5-2-u4-X26','SC5-2-u4-X27']::text[],false,'{"seq":8,"concept":"SC5-2-u4-C14","difficulty":4,"kind":"mc","stem":"밝기가 같은 전등 ㉠은 한 시간에 전기를 10만큼, 전등 ㉡은 60만큼 써요. 효율이 더 좋은 전등과 그 까닭은 어느 것인가요?","options":[{"t":"㉠, 같은 밝기를 내면서 전기를 적게 써서","correct":true},{"t":"㉡, 전기를 많이 써서","mis":"SC5-2-u4-X26"},{"t":"둘이 같다, 밝기가 같아서","mis":"SC5-2-u4-X26"},{"t":"㉡, 숫자가 더 커서","mis":"SC5-2-u4-X27"}],"explanation":["밝기가 같아요.","㉠이 적게 써요.","㉠이 효율적이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L05_challenge#9','sci',5,2,'u4','L05','g5_2_sci_u4_L05_challenge','lesson_challenge','SC5-2-u4-C16',4,'mc','auto','우리 교실의 에너지 계획으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X25','SC5-2-u4-X26','SC5-2-u4-X27']::text[],false,'{"seq":9,"concept":"SC5-2-u4-C16","difficulty":4,"kind":"mc","stem":"우리 교실의 에너지 계획으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"쓰지 않는 기기는 절전 멀티탭으로 끄고, 조명은 LED로, 냉난방 중엔 창문을 닫는다","correct":true},{"t":"모든 기기를 켜 두고 창문을 활짝 연다","mis":"SC5-2-u4-X25"},{"t":"밝게 하려고 조명을 두 배로 늘린다","mis":"SC5-2-u4-X26"},{"t":"모든 제품을 5등급으로 바꾼다","mis":"SC5-2-u4-X27"}],"explanation":["새는 전기를 막아요.","효율 높은 조명이에요.","열도 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L05_challenge#10','sci',5,2,'u4','L05','g5_2_sci_u4_L05_challenge','lesson_challenge','SC5-2-u4-C15',4,'essay','teacher','우리 교실 살펴보기에서 자원이나 에너지가 낭비되는 곳을 두 군데 찾고, 각각 어떻게 고치면 좋을지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-2-u4-C15","difficulty":4,"kind":"essay","stem":"우리 교실 살펴보기에서 자원이나 에너지가 낭비되는 곳을 두 군데 찾고, 각각 어떻게 고치면 좋을지 쓰세요.","answer_guide":{"answer":"예: ① 꺼 둔 공기 청정기의 플러그가 꽂혀 있어 전기가 새므로 쓰지 않을 때 플러그를 뽑는다. ② 종이컵을 하루에 열 개씩 버리므로 다회용 컵을 쓴다.","scoring_points":["낭비되는 곳 하나를 바르게 찾아 고칠 방법을 썼는가","낭비되는 곳 하나를 더 찾아 고칠 방법을 썼는가","고친 방법이 무엇을 아끼는지 알맞은가"]},"explanation":["두 군데를 찾아요.","고칠 방법을 써요.","무엇을 아끼나 봐요."],"asset":{"type":"passage","lines":["① 꺼 둔 공기 청정기의 플러그가 꽂혀 있다.","② 종이컵을 하루에 열 개씩 쓰고 버린다.","③ 양치할 때 물을 계속 틀어 놓는다.","④ 이면지 상자가 늘 비어 있다.","⑤ 교실 전등을 LED 조명으로 바꾸었다."],"title":"우리 교실 살펴보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L06_basic#1','sci',5,2,'u4','L06','g5_2_sci_u4_L06_basic','lesson_basic','SC5-2-u4-C17',1,'mc','auto','단열 효과를 알아보는 실험에서 두 집 모형은 어떻게 만드나요?',ARRAY['SC5-2-u4-X31']::text[],false,'{"seq":1,"concept":"SC5-2-u4-C17","difficulty":1,"kind":"mc","stem":"단열 효과를 알아보는 실험에서 두 집 모형은 어떻게 만드나요?","options":[{"t":"크기와 모양이 같게 만든다","correct":true},{"t":"크기를 서로 다르게 만든다","mis":"SC5-2-u4-X31"},{"t":"한 집은 종이, 한 집은 쇠로 만든다","mis":"SC5-2-u4-X31"},{"t":"집 모형을 하나만 만든다","mis":"SC5-2-u4-X31"}],"explanation":["두 집을 견줘요.","크기와 모양이 같아요.","단열만 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L06_basic#2','sci',5,2,'u4','L06','g5_2_sci_u4_L06_basic','lesson_basic','SC5-2-u4-C17',1,'mc','auto','집 모형 실험 차례 ④에서 집 안 공기를 데우려고 넣은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X31']::text[],false,'{"seq":2,"concept":"SC5-2-u4-C17","difficulty":1,"kind":"mc","stem":"집 모형 실험 차례 ④에서 집 안 공기를 데우려고 넣은 것은 어느 것인가요?","options":[{"t":"따뜻한 손난로","correct":true},{"t":"얼음 주머니","mis":"SC5-2-u4-X31"},{"t":"젖은 수건","mis":"SC5-2-u4-X31"},{"t":"작은 선풍기","mis":"SC5-2-u4-X31"}],"explanation":["공기를 데워요.","따뜻한 것을 넣어요.","손난로예요."],"asset":{"type":"passage","lines":["① 크기와 모양이 같은 집 모형 ㉮, ㉯를 만든다.","② 두 집 창문 안쪽에 뽁뽁이를 한 장씩 붙인다.","③ ㉯에만 뽁뽁이를 한 장 더, 벽에 우드록, 틈은 색점토로 막는다.","④ 지붕에 탐침 온도계를 꽂고 데운 손난로를 넣어 5분 둔다.","⑤ 손난로를 빼고 1분 간격으로 5번 온도를 잰다."],"title":"집 모형 실험 차례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L06_basic#3','sci',5,2,'u4','L06','g5_2_sci_u4_L06_basic','lesson_basic','SC5-2-u4-C18',1,'ox','auto','단열을 한 집 모형은 단열을 하지 않은 집 모형보다 온도 변화가 더 작아요.',ARRAY['SC5-2-u4-X33']::text[],false,'{"seq":3,"concept":"SC5-2-u4-C18","difficulty":1,"kind":"ox","stem":"단열을 한 집 모형은 단열을 하지 않은 집 모형보다 온도 변화가 더 작아요.","answer":"O","reason_options":[{"t":"단열을 하면 집 안의 열이 덜 빠져나가기 때문에","correct":true},{"t":"단열재가 열을 더 빨리 밖으로 내보내기 때문에","mis":"SC5-2-u4-X33"}],"mis":"SC5-2-u4-X33","explanation":["열이 덜 나가요.","온도가 잘 지켜져요.","변화가 작아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L06_basic#4','sci',5,2,'u4','L06','g5_2_sci_u4_L06_basic','lesson_basic','SC5-2-u4-C18',1,'sa','auto','두 집 모형 안의 온도 그래프에서 단열한 집의 5분 뒤 온도는 몇 °C인가요? 숫자만 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC5-2-u4-C18","difficulty":1,"kind":"sa","stem":"두 집 모형 안의 온도 그래프에서 단열한 집의 5분 뒤 온도는 몇 °C인가요? 숫자만 쓰세요.","answer":["27.5","27.5 °C","27.5도"],"explanation":["단열한 집을 봐요.","5분 뒤예요.","27.5 °C예요."],"asset":{"type":"lgraph","xs":["처음","1","2","3","4","5"],"series":[{"name":"단열 안 한 집","vals":[30,28,27,26.5,26,25.5]},{"name":"단열한 집","vals":[30,29.5,29,28.5,28,27.5]}],"step":0.5,"y0":24,"wave":true,"ymax":31,"ylab":"(°C)","xlab":"(분 뒤)","title":"두 집 모형 안의 온도"},"mis":"SC5-2-u4-X34"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L06_basic#5','sci',5,2,'u4','L06','g5_2_sci_u4_L06_basic','lesson_basic','SC5-2-u4-C18',2,'mc','auto','두 집 모형 안의 온도 그래프에서 단열 안 한 집의 온도 변화량은 얼마인가요?',ARRAY['SC5-2-u4-X34','SC5-2-u4-X33']::text[],false,'{"seq":5,"concept":"SC5-2-u4-C18","difficulty":2,"kind":"mc","stem":"두 집 모형 안의 온도 그래프에서 단열 안 한 집의 온도 변화량은 얼마인가요?","options":[{"t":"4.5 °C","correct":true},{"t":"25.5 °C","mis":"SC5-2-u4-X34"},{"t":"2.5 °C","mis":"SC5-2-u4-X33"},{"t":"30 °C","mis":"SC5-2-u4-X34"}],"explanation":["처음은 30 °C예요.","5분 뒤 25.5 °C예요.","4.5 °C 낮아졌어요."],"asset":{"type":"lgraph","xs":["처음","1","2","3","4","5"],"series":[{"name":"단열 안 한 집","vals":[30,28,27,26.5,26,25.5]},{"name":"단열한 집","vals":[30,29.5,29,28.5,28,27.5]}],"step":0.5,"y0":24,"wave":true,"ymax":31,"ylab":"(°C)","xlab":"(분 뒤)","title":"두 집 모형 안의 온도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L06_basic#6','sci',5,2,'u4','L06','g5_2_sci_u4_L06_basic','lesson_basic','SC5-2-u4-C17',2,'mc','auto','집 모형 안의 온도를 잴 때 탐침 온도계를 바르게 쓴 것은 어느 것인가요?',ARRAY['SC5-2-u4-X32']::text[],false,'{"seq":6,"concept":"SC5-2-u4-C17","difficulty":2,"kind":"mc","stem":"집 모형 안의 온도를 잴 때 탐침 온도계를 바르게 쓴 것은 어느 것인가요?","options":[{"t":"탐침 끝이 바닥에 닿지 않게 꽂아 공기의 온도를 잰다","correct":true},{"t":"탐침 끝을 바닥에 꾹 눌러 꽂는다","mis":"SC5-2-u4-X32"},{"t":"탐침 끝을 친구 쪽으로 향하게 든다","mis":"SC5-2-u4-X32"},{"t":"손난로에 탐침을 꽂는다","mis":"SC5-2-u4-X32"}],"explanation":["공기 온도를 재요.","바닥에 닿지 않게요.","바르게 꽂아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L06_basic#7','sci',5,2,'u4','L06','g5_2_sci_u4_L06_basic','lesson_basic','SC5-2-u4-C18',2,'mc','auto','두 집 모형 안의 온도 그래프에서 에너지 효율이 더 높은 집과 그 까닭은 어느 것인가요?',ARRAY['SC5-2-u4-X33','SC5-2-u4-X34']::text[],false,'{"seq":7,"concept":"SC5-2-u4-C18","difficulty":2,"kind":"mc","stem":"두 집 모형 안의 온도 그래프에서 에너지 효율이 더 높은 집과 그 까닭은 어느 것인가요?","options":[{"t":"단열한 집, 온도 변화가 더 작아서","correct":true},{"t":"단열 안 한 집, 온도 변화가 더 커서","mis":"SC5-2-u4-X33"},{"t":"두 집이 같다, 처음 온도가 같아서","mis":"SC5-2-u4-X34"},{"t":"단열 안 한 집, 5분 뒤 온도가 더 낮아서","mis":"SC5-2-u4-X33"}],"explanation":["변화량을 견줘요.","단열한 집이 덜 변해요.","효율이 높아요."],"asset":{"type":"lgraph","xs":["처음","1","2","3","4","5"],"series":[{"name":"단열 안 한 집","vals":[30,28,27,26.5,26,25.5]},{"name":"단열한 집","vals":[30,29.5,29,28.5,28,27.5]}],"step":0.5,"y0":24,"wave":true,"ymax":31,"ylab":"(°C)","xlab":"(분 뒤)","title":"두 집 모형 안의 온도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L06_basic#8','sci',5,2,'u4','L06','g5_2_sci_u4_L06_basic','lesson_basic','SC5-2-u4-C19',2,'mc','auto','에너지를 아끼는 집 그림에서 ㉡ 이중창이 하는 일은 어느 것인가요?',ARRAY['SC5-2-u4-X35','SC5-2-u4-X36']::text[],false,'{"seq":8,"concept":"SC5-2-u4-C19","difficulty":2,"kind":"mc","stem":"에너지를 아끼는 집 그림에서 ㉡ 이중창이 하는 일은 어느 것인가요?","options":[{"t":"집 안과 밖 사이의 열 이동을 막아 집 안 온도를 지킨다","correct":true},{"t":"햇빛으로 전기를 만든다","mis":"SC5-2-u4-X35"},{"t":"스스로 열을 내 집을 데운다","mis":"SC5-2-u4-X36"},{"t":"땅속 열을 끌어 온다","mis":"SC5-2-u4-X35"}],"explanation":["창이 두 겹이에요.","열 이동을 막아요.","온도를 지켜요."],"asset":{"type":"passage","lines":["㉠ 벽 속 단열재","㉡ 이중창","㉢ 햇빛 방향에 따라 움직이는 차양","㉣ 지붕 위 태양 전지판","㉤ 땅속 열을 쓰는 냉난방","㉥ 옥상 정원"],"title":"에너지를 아끼는 집 그림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L06_basic#9','sci',5,2,'u4','L06','g5_2_sci_u4_L06_basic','lesson_basic','SC5-2-u4-C19',2,'ox','auto','지붕의 태양 전지판으로 전기를 만들어 쓰는 것은 에너지를 직접 만들어 쓰는 방법이에요.',ARRAY['SC5-2-u4-X35']::text[],false,'{"seq":9,"concept":"SC5-2-u4-C19","difficulty":2,"kind":"ox","stem":"지붕의 태양 전지판으로 전기를 만들어 쓰는 것은 에너지를 직접 만들어 쓰는 방법이에요.","answer":"O","reason_options":[{"t":"태양 빛으로 필요한 에너지를 생산하기 때문에","correct":true},{"t":"태양 전지판은 열이 빠져나가는 것을 막는 단열재이기 때문에","mis":"SC5-2-u4-X35"}],"mis":"SC5-2-u4-X35","explanation":["햇빛을 받아요.","전기를 만들어요.","직접 만드는 방법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L06_basic#10','sci',5,2,'u4','L06','g5_2_sci_u4_L06_basic','lesson_basic','SC5-2-u4-C17',3,'error','auto','집 모형 실험 차례를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u4-X32','SC5-2-u4-X31']::text[],false,'{"seq":10,"concept":"SC5-2-u4-C17","difficulty":3,"kind":"error","stem":"집 모형 실험 차례를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"주원 — 「손난로를 뺄 때는 집 문을 활짝 열어야 정확해.」","correct":true,"mis_target":"SC5-2-u4-X32"},{"t":"채아 — 「두 집에 같은 손난로를 넣었어.」","mis":"SC5-2-u4-X31"},{"t":"보람 — 「㉯ 집만 단열을 더 했어.」","mis":"SC5-2-u4-X31"}],"explanation":["활짝 열면 열이 나가요.","살짝만 열어요.","주원의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["① 크기와 모양이 같은 집 모형 ㉮, ㉯를 만든다.","② 두 집 창문 안쪽에 뽁뽁이를 한 장씩 붙인다.","③ ㉯에만 뽁뽁이를 한 장 더, 벽에 우드록, 틈은 색점토로 막는다.","④ 지붕에 탐침 온도계를 꽂고 데운 손난로를 넣어 5분 둔다.","⑤ 손난로를 빼고 1분 간격으로 5번 온도를 잰다."],"title":"집 모형 실험 차례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L06_challenge#1','sci',5,2,'u4','L06','g5_2_sci_u4_L06_challenge','lesson_challenge','SC5-2-u4-C19',2,'match','auto','에너지를 아끼는 집 그림의 시설과 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-2-u4-C19","difficulty":2,"kind":"match","stem":"에너지를 아끼는 집 그림의 시설과 하는 일을 알맞게 이으세요.","pairs":[{"l":"벽 속 단열재","r":"열이 빠져나가는 것을 막음"},{"l":"지붕 위 태양 전지판","r":"햇빛으로 에너지를 만듦"},{"l":"햇빛 방향에 따라 움직이는 차양","r":"들어오는 햇빛을 알맞게 조절함"}],"mis":"SC5-2-u4-X35","explanation":["단열재는 막아요.","전지판은 만들어요.","차양은 조절해요."],"asset":{"type":"passage","lines":["㉠ 벽 속 단열재","㉡ 이중창","㉢ 햇빛 방향에 따라 움직이는 차양","㉣ 지붕 위 태양 전지판","㉤ 땅속 열을 쓰는 냉난방","㉥ 옥상 정원"],"title":"에너지를 아끼는 집 그림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L06_challenge#2','sci',5,2,'u4','L06','g5_2_sci_u4_L06_challenge','lesson_challenge','SC5-2-u4-C17',2,'mc','auto','집 모형 실험 차례에서 두 집을 서로 다르게 한 조건은 어느 것인가요?',ARRAY['SC5-2-u4-X31']::text[],false,'{"seq":2,"concept":"SC5-2-u4-C17","difficulty":2,"kind":"mc","stem":"집 모형 실험 차례에서 두 집을 서로 다르게 한 조건은 어느 것인가요?","options":[{"t":"단열을 한 정도","correct":true},{"t":"집 모형의 크기","mis":"SC5-2-u4-X31"},{"t":"넣은 손난로의 종류","mis":"SC5-2-u4-X31"},{"t":"온도를 잰 시간 간격","mis":"SC5-2-u4-X31"}],"explanation":["㉯만 더 했어요.","단열이 달라요.","나머지는 같아요."],"asset":{"type":"passage","lines":["① 크기와 모양이 같은 집 모형 ㉮, ㉯를 만든다.","② 두 집 창문 안쪽에 뽁뽁이를 한 장씩 붙인다.","③ ㉯에만 뽁뽁이를 한 장 더, 벽에 우드록, 틈은 색점토로 막는다.","④ 지붕에 탐침 온도계를 꽂고 데운 손난로를 넣어 5분 둔다.","⑤ 손난로를 빼고 1분 간격으로 5번 온도를 잰다."],"title":"집 모형 실험 차례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L06_challenge#3','sci',5,2,'u4','L06','g5_2_sci_u4_L06_challenge','lesson_challenge','SC5-2-u4-C18',3,'mc','auto','처음 온도가 다른 두 집 모형에서 단열한 집은 어느 것이고, 그 까닭은 무엇인가요?',ARRAY['SC5-2-u4-X34','SC5-2-u4-X33']::text[],false,'{"seq":3,"concept":"SC5-2-u4-C18","difficulty":3,"kind":"mc","stem":"처음 온도가 다른 두 집 모형에서 단열한 집은 어느 것이고, 그 까닭은 무엇인가요?","options":[{"t":"(나), 온도 변화량이 2.8 °C로 (가)의 6.2 °C보다 작아서","correct":true},{"t":"(가), 처음 온도가 더 높아서","mis":"SC5-2-u4-X34"},{"t":"(가), 온도 변화량이 더 커서","mis":"SC5-2-u4-X33"},{"t":"(나), 5분 뒤 온도만 보면 되니까","mis":"SC5-2-u4-X34"}],"explanation":["처음 온도가 달라요.","변화량을 구해요.","(나)가 덜 변했어요."],"asset":{"type":"passage","lines":["(가) 처음 31.0 °C → 5분 뒤 24.8 °C","(나) 처음 30.0 °C → 5분 뒤 27.2 °C","두 집 가운데 한 집만 단열을 하였다."],"title":"처음 온도가 다른 두 집 모형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L06_challenge#4','sci',5,2,'u4','L06','g5_2_sci_u4_L06_challenge','lesson_challenge','SC5-2-u4-C18',3,'sa','auto','처음 온도가 다른 두 집 모형에서 (가)의 온도 변화량은 몇 °C인가요? 숫자만 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC5-2-u4-C18","difficulty":3,"kind":"sa","stem":"처음 온도가 다른 두 집 모형에서 (가)의 온도 변화량은 몇 °C인가요? 숫자만 쓰세요.","answer":["6.2","6.2 °C","6.2도"],"explanation":["처음 31.0 °C예요.","5분 뒤 24.8 °C예요.","6.2 °C예요."],"asset":{"type":"passage","lines":["(가) 처음 31.0 °C → 5분 뒤 24.8 °C","(나) 처음 30.0 °C → 5분 뒤 27.2 °C","두 집 가운데 한 집만 단열을 하였다."],"title":"처음 온도가 다른 두 집 모형"},"mis":"SC5-2-u4-X34"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L06_challenge#5','sci',5,2,'u4','L06','g5_2_sci_u4_L06_challenge','lesson_challenge','SC5-2-u4-C18',3,'ox','auto','처음 온도가 다른 두 집은 5분 뒤 온도만 견주어도 단열 효과를 알 수 있어요.',ARRAY['SC5-2-u4-X34']::text[],false,'{"seq":5,"concept":"SC5-2-u4-C18","difficulty":3,"kind":"ox","stem":"처음 온도가 다른 두 집은 5분 뒤 온도만 견주어도 단열 효과를 알 수 있어요.","answer":"X","reason_options":[{"t":"처음 온도가 달라 온도 변화량을 구해 견주어야 하기 때문에","correct":true},{"t":"마지막 온도가 높은 집이 언제나 단열이 잘된 집이기 때문에","mis":"SC5-2-u4-X34"}],"mis":"SC5-2-u4-X34","explanation":["처음이 달라요.","변화량을 구해요.","그래야 공정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L06_challenge#6','sci',5,2,'u4','L06','g5_2_sci_u4_L06_challenge','lesson_challenge','SC5-2-u4-C19',3,'error','auto','단열한 집 모형을 보며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u4-X36','SC5-2-u4-X33']::text[],false,'{"seq":6,"concept":"SC5-2-u4-C19","difficulty":3,"kind":"error","stem":"단열한 집 모형을 보며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서진 — 「우드록과 색점토가 스스로 따뜻해져서 집을 데워 줘.」","correct":true,"mis_target":"SC5-2-u4-X36"},{"t":"나윤 — 「색점토로 틈을 막으니 열이 덜 새.」","mis":"SC5-2-u4-X36"},{"t":"이현 — 「뽁뽁이를 두 겹 붙이면 단열이 더 잘돼.」","mis":"SC5-2-u4-X33"}],"explanation":["단열재는 막을 뿐이에요.","스스로 열을 내지 않아요.","서진의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L06_challenge#7','sci',5,2,'u4','L06','g5_2_sci_u4_L06_challenge','lesson_challenge','SC5-2-u4-C19',3,'mc','auto','전 세계에서 함께 한 시간 불을 끄는 날(어스아워) 캠페인을 하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X29','SC5-2-u4-X42','SC5-2-u4-X27']::text[],false,'{"seq":7,"concept":"SC5-2-u4-C19","difficulty":3,"kind":"mc","stem":"전 세계에서 함께 한 시간 불을 끄는 날(어스아워) 캠페인을 하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"에너지 절약이 왜 필요한지 알리고 함께 실천하려고","correct":true},{"t":"불을 끄면 에너지가 새로 생겨나서","mis":"SC5-2-u4-X29"},{"t":"재생 에너지가 있어 원래는 아낄 필요가 없어서","mis":"SC5-2-u4-X42"},{"t":"전등의 효율 등급을 바꾸려고","mis":"SC5-2-u4-X27"}],"explanation":["불을 함께 꺼요.","절약을 알려요.","함께 실천해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L06_challenge#8','sci',5,2,'u4','L06','g5_2_sci_u4_L06_challenge','lesson_challenge','SC5-2-u4-C17',4,'mc','auto','집 모형 실험 결과를 더 믿을 수 있게 하는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X31','SC5-2-u4-X32']::text[],false,'{"seq":8,"concept":"SC5-2-u4-C17","difficulty":4,"kind":"mc","stem":"집 모형 실험 결과를 더 믿을 수 있게 하는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"같은 실험을 여러 번 되풀이해 결과가 비슷한지 확인한다","correct":true},{"t":"한 집에만 손난로를 더 오래 넣는다","mis":"SC5-2-u4-X31"},{"t":"두 집을 서로 다른 때에 따로 잰다","mis":"SC5-2-u4-X31"},{"t":"탐침 끝을 바닥에 닿게 한다","mis":"SC5-2-u4-X32"}],"explanation":["되풀이해요.","결과를 견줘요.","믿을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L06_challenge#9','sci',5,2,'u4','L06','g5_2_sci_u4_L06_challenge','lesson_challenge','SC5-2-u4-C19',4,'mc','auto','사계절 내내 에너지를 아끼는 집을 설계한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X35','SC5-2-u4-X36','SC5-2-u4-X33']::text[],false,'{"seq":9,"concept":"SC5-2-u4-C19","difficulty":4,"kind":"mc","stem":"사계절 내내 에너지를 아끼는 집을 설계한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"벽과 지붕을 단열하고 이중창을 달며, 태양 빛과 땅속 열로 에너지를 만들어 쓴다","correct":true},{"t":"얇은 한 겹 창을 크게 내고 냉난방을 세게 켠다","mis":"SC5-2-u4-X35"},{"t":"단열재가 열을 내니 난방기를 없앤다","mis":"SC5-2-u4-X36"},{"t":"지붕과 벽에 틈을 넓게 낸다","mis":"SC5-2-u4-X33"}],"explanation":["열을 막아요.","에너지를 만들어요.","둘 다 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L06_challenge#10','sci',5,2,'u4','L06','g5_2_sci_u4_L06_challenge','lesson_challenge','SC5-2-u4-C18',4,'essay','teacher','두 집 모형 안의 온도 그래프를 보고 두 집의 온도 변화량을 견주어 쓰고, 이 결과를 실제 집에 어떻게 쓸 수 있는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-2-u4-C18","difficulty":4,"kind":"essay","stem":"두 집 모형 안의 온도 그래프를 보고 두 집의 온도 변화량을 견주어 쓰고, 이 결과를 실제 집에 어떻게 쓸 수 있는지 쓰세요.","answer_guide":{"answer":"예: 단열 안 한 집은 4.5 °C, 단열한 집은 2.5 °C 낮아져 단열한 집의 온도 변화가 더 작다. 단열을 하면 집 안 온도를 잘 지켜 에너지 효율이 높아지므로, 실제 집에도 단열재와 이중창을 쓰면 냉난방 에너지를 아낄 수 있다.","scoring_points":["두 집의 온도 변화량을 바르게 썼는가","변화가 작은 집이 효율이 높다고 썼는가","실제 집에 쓸 방법(단열재·이중창 등)을 썼는가"]},"explanation":["변화량을 구해요.","덜 변한 집이에요.","실제 집에 써요."],"asset":{"type":"lgraph","xs":["처음","1","2","3","4","5"],"series":[{"name":"단열 안 한 집","vals":[30,28,27,26.5,26,25.5]},{"name":"단열한 집","vals":[30,29.5,29,28.5,28,27.5]}],"step":0.5,"y0":24,"wave":true,"ymax":31,"ylab":"(°C)","xlab":"(분 뒤)","title":"두 집 모형 안의 온도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L07_basic#1','sci',5,2,'u4','L07','g5_2_sci_u4_L07_basic','lesson_basic','SC5-2-u4-C20',1,'mc','auto','자원과 에너지를 효율적으로 이용하는 실천 영상의 주제로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X37','SC5-2-u4-X38']::text[],false,'{"seq":1,"concept":"SC5-2-u4-C20","difficulty":1,"kind":"mc","stem":"자원과 에너지를 효율적으로 이용하는 실천 영상의 주제로 알맞은 것은 어느 것인가요?","options":[{"t":"양치할 때 양치 컵에 물을 받아 쓰기","correct":true},{"t":"좋아하는 과자 소개하기","mis":"SC5-2-u4-X37"},{"t":"친구 얼굴을 몰래 찍기","mis":"SC5-2-u4-X38"},{"t":"하루 종일 텔레비전 켜 두기","mis":"SC5-2-u4-X37"}],"explanation":["생활 속 실천이에요.","물을 아껴요.","알맞은 주제예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L07_basic#2','sci',5,2,'u4','L07','g5_2_sci_u4_L07_basic','lesson_basic','SC5-2-u4-C20',1,'mc','auto','모둠 역할 나누기에서 장면마다 할 말을 쓰는 역할은 어느 것인가요?',ARRAY['SC5-2-u4-X37']::text[],false,'{"seq":2,"concept":"SC5-2-u4-C20","difficulty":1,"kind":"mc","stem":"모둠 역할 나누기에서 장면마다 할 말을 쓰는 역할은 어느 것인가요?","options":[{"t":"대본","correct":true},{"t":"촬영","mis":"SC5-2-u4-X37"},{"t":"소품","mis":"SC5-2-u4-X37"},{"t":"감독","mis":"SC5-2-u4-X37"}],"explanation":["할 말을 써요.","대사를 정해요.","대본이에요."],"asset":{"type":"passage","lines":["감독 — 영상의 흐름을 정하고 이끈다.","대본 — 장면마다 할 말을 쓴다.","촬영 — 스마트 기기로 장면을 찍는다.","소품 — 다 쓴 상자로 팻말을 만든다."],"title":"모둠 역할 나누기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L07_basic#3','sci',5,2,'u4','L07','g5_2_sci_u4_L07_basic','lesson_basic','SC5-2-u4-C20',1,'ox','auto','실천 영상에 친구의 이름과 사는 곳을 크게 넣어 누리망에 올려요.',ARRAY['SC5-2-u4-X38']::text[],false,'{"seq":3,"concept":"SC5-2-u4-C20","difficulty":1,"kind":"ox","stem":"실천 영상에 친구의 이름과 사는 곳을 크게 넣어 누리망에 올려요.","answer":"X","reason_options":[{"t":"나와 다른 사람의 개인 정보를 누리망에 함부로 올리면 안 되기 때문에","correct":true},{"t":"개인 정보를 넣어야 영상이 더 재미있기 때문에","mis":"SC5-2-u4-X38"}],"mis":"SC5-2-u4-X38","explanation":["개인 정보예요.","함부로 올리면 안 돼요.","빼고 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L07_basic#4','sci',5,2,'u4','L07','g5_2_sci_u4_L07_basic','lesson_basic','SC5-2-u4-C20',1,'mc','auto','촬영할 장면과 상황을 글과 그림으로 미리 정리한 것을 무엇이라고 하나요?',ARRAY['SC5-2-u4-X37']::text[],false,'{"seq":4,"concept":"SC5-2-u4-C20","difficulty":1,"kind":"mc","stem":"촬영할 장면과 상황을 글과 그림으로 미리 정리한 것을 무엇이라고 하나요?","options":[{"t":"스토리 보드","correct":true},{"t":"영수증","mis":"SC5-2-u4-X37"},{"t":"놀이판","mis":"SC5-2-u4-X37"},{"t":"일기장","mis":"SC5-2-u4-X37"}],"explanation":["장면을 미리 그려요.","글도 써요.","스토리 보드예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L07_basic#5','sci',5,2,'u4','L07','g5_2_sci_u4_L07_basic','lesson_basic','SC5-2-u4-C20',2,'mc','auto','하늘 모둠 스토리 보드 ① 장면이 보여 주는 문제는 어느 것인가요?',ARRAY['SC5-2-u4-X28','SC5-2-u4-X37']::text[],false,'{"seq":5,"concept":"SC5-2-u4-C20","difficulty":2,"kind":"mc","stem":"하늘 모둠 스토리 보드 ① 장면이 보여 주는 문제는 어느 것인가요?","options":[{"t":"비누칠하는 동안 물을 틀어 놓아 낭비한다","correct":true},{"t":"물을 너무 아껴 손이 더럽다","mis":"SC5-2-u4-X28"},{"t":"전등을 꺼서 어둡다","mis":"SC5-2-u4-X37"},{"t":"양치 컵을 써서 물이 모자란다","mis":"SC5-2-u4-X28"}],"explanation":["물을 틀어 놓았어요.","「잠깐!」이라고 해요.","물 낭비예요."],"asset":{"type":"passage","lines":["① 수도꼭지를 틀어 놓고 비누칠하는 친구 — 「잠깐!」","② 물을 잠그고 비누칠하는 모습","③ 양치 컵에 물을 받아 양치하는 모습","④ 화면 글 — 「물을 아껴 지구를 지켜요」"],"title":"하늘 모둠 스토리 보드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L07_basic#6','sci',5,2,'u4','L07','g5_2_sci_u4_L07_basic','lesson_basic','SC5-2-u4-C15',2,'mc','auto','영상에 쓸 팻말 소품을 만들 재료로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X28']::text[],false,'{"seq":6,"concept":"SC5-2-u4-C15","difficulty":2,"kind":"mc","stem":"영상에 쓸 팻말 소품을 만들 재료로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"다 쓴 상자 같은 재활용품","correct":true},{"t":"새로 산 플라스틱 판 여러 장","mis":"SC5-2-u4-X28"},{"t":"한 번 쓰고 버릴 종이컵 묶음","mis":"SC5-2-u4-X28"},{"t":"비닐을 겹겹이 두른 새 포장지","mis":"SC5-2-u4-X28"}],"explanation":["소품도 아껴요.","재활용품을 써요.","상자로 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L07_basic#7','sci',5,2,'u4','L07','g5_2_sci_u4_L07_basic','lesson_basic','SC5-2-u4-C20',2,'ox','auto','다른 모둠의 실천 영상에 댓글을 달 때는 바르고 고운 말을 써요.',ARRAY['SC5-2-u4-X38']::text[],false,'{"seq":7,"concept":"SC5-2-u4-C20","difficulty":2,"kind":"ox","stem":"다른 모둠의 실천 영상에 댓글을 달 때는 바르고 고운 말을 써요.","answer":"O","reason_options":[{"t":"상대를 존중하고 배려해야 하기 때문에","correct":true},{"t":"댓글은 아무도 안 보니 함부로 써도 되기 때문에","mis":"SC5-2-u4-X38"}],"mis":"SC5-2-u4-X38","explanation":["댓글도 말이에요.","존중해요.","고운 말을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L07_basic#8','sci',5,2,'u4','L07','g5_2_sci_u4_L07_basic','lesson_basic','SC5-2-u4-C16',2,'mc','auto','전기를 아끼는 실천 영상에 넣기 알맞은 장면은 어느 것인가요?',ARRAY['SC5-2-u4-X25','SC5-2-u4-X23']::text[],false,'{"seq":8,"concept":"SC5-2-u4-C16","difficulty":2,"kind":"mc","stem":"전기를 아끼는 실천 영상에 넣기 알맞은 장면은 어느 것인가요?","options":[{"t":"쓰지 않는 전기 기구의 전원을 끄고 플러그를 뽑는다","correct":true},{"t":"보지 않는 텔레비전을 켜 둔다","mis":"SC5-2-u4-X25"},{"t":"에어컨을 켠 채 문을 연다","mis":"SC5-2-u4-X23"},{"t":"빈방 조명을 켜 둔다","mis":"SC5-2-u4-X23"}],"explanation":["전원을 꺼요.","플러그를 뽑아요.","전기를 아껴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L07_basic#9','sci',5,2,'u4','L07','g5_2_sci_u4_L07_basic','lesson_basic','SC5-2-u4-C20',2,'mc','auto','실천 영상을 공유한 뒤에 해야 할 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X39','SC5-2-u4-X38']::text[],false,'{"seq":9,"concept":"SC5-2-u4-C20","difficulty":2,"kind":"mc","stem":"실천 영상을 공유한 뒤에 해야 할 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"영상에 담은 실천을 나부터 꾸준히 이어 간다","correct":true},{"t":"영상을 올렸으니 실천은 그만둔다","mis":"SC5-2-u4-X39"},{"t":"다른 모둠 영상을 깎아내리는 댓글을 단다","mis":"SC5-2-u4-X38"},{"t":"영상을 지우고 잊어버린다","mis":"SC5-2-u4-X39"}],"explanation":["영상은 시작이에요.","나부터 해요.","꾸준히 이어 가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L07_basic#10','sci',5,2,'u4','L07','g5_2_sci_u4_L07_basic','lesson_basic','SC5-2-u4-C20',3,'error','auto','실천 영상을 만들며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u4-X39','SC5-2-u4-X38','SC5-2-u4-X37']::text[],false,'{"seq":10,"concept":"SC5-2-u4-C20","difficulty":3,"kind":"error","stem":"실천 영상을 만들며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지율 — 「영상에서 실천하는 척만 하고 실제로는 안 해도 돼.」","correct":true,"mis_target":"SC5-2-u4-X39"},{"t":"하온 — 「촬영할 장소는 안전한 곳으로 정해.」","mis":"SC5-2-u4-X38"},{"t":"시하 — 「역할을 나누면 더 잘 만들 수 있어.」","mis":"SC5-2-u4-X37"}],"explanation":["영상은 실천을 알려요.","나도 실천해야 해요.","지율의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L07_challenge#1','sci',5,2,'u4','L07','g5_2_sci_u4_L07_challenge','lesson_challenge','SC5-2-u4-C20',2,'match','auto','모둠 역할 나누기의 역할과 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-2-u4-C20","difficulty":2,"kind":"match","stem":"모둠 역할 나누기의 역할과 하는 일을 알맞게 이으세요.","pairs":[{"l":"감독","r":"영상의 흐름을 정하고 이끈다"},{"l":"촬영","r":"스마트 기기로 장면을 찍는다"},{"l":"소품","r":"다 쓴 상자로 팻말을 만든다"}],"mis":"SC5-2-u4-X37","explanation":["감독은 이끌어요.","촬영은 찍어요.","소품은 만들어요."],"asset":{"type":"passage","lines":["감독 — 영상의 흐름을 정하고 이끈다.","대본 — 장면마다 할 말을 쓴다.","촬영 — 스마트 기기로 장면을 찍는다.","소품 — 다 쓴 상자로 팻말을 만든다."],"title":"모둠 역할 나누기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L07_challenge#2','sci',5,2,'u4','L07','g5_2_sci_u4_L07_challenge','lesson_challenge','SC5-2-u4-C20',2,'mc','auto','하늘 모둠 스토리 보드의 네 장면을 바르게 설명한 것은 어느 것인가요?',ARRAY['SC5-2-u4-X37']::text[],false,'{"seq":2,"concept":"SC5-2-u4-C20","difficulty":2,"kind":"mc","stem":"하늘 모둠 스토리 보드의 네 장면을 바르게 설명한 것은 어느 것인가요?","options":[{"t":"①은 문제 장면, ②·③은 바른 실천, ④는 함께하자는 말이다","correct":true},{"t":"①·②는 바른 실천, ③·④는 문제 장면이다","mis":"SC5-2-u4-X37"},{"t":"네 장면 모두 문제 장면이다","mis":"SC5-2-u4-X37"},{"t":"네 장면 모두 자원과 상관없는 장면이다","mis":"SC5-2-u4-X37"}],"explanation":["①은 낭비예요.","②·③은 실천이에요.","④는 함께하자는 말이에요."],"asset":{"type":"passage","lines":["① 수도꼭지를 틀어 놓고 비누칠하는 친구 — 「잠깐!」","② 물을 잠그고 비누칠하는 모습","③ 양치 컵에 물을 받아 양치하는 모습","④ 화면 글 — 「물을 아껴 지구를 지켜요」"],"title":"하늘 모둠 스토리 보드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L07_challenge#3','sci',5,2,'u4','L07','g5_2_sci_u4_L07_challenge','lesson_challenge','SC5-2-u4-C20',3,'mc','auto','실천 영상을 촬영할 장소로 가장 알맞은 곳은 어느 것인가요?',ARRAY['SC5-2-u4-X38']::text[],false,'{"seq":3,"concept":"SC5-2-u4-C20","difficulty":3,"kind":"mc","stem":"실천 영상을 촬영할 장소로 가장 알맞은 곳은 어느 것인가요?","options":[{"t":"사람이 다니는 안전한 교실이나 집 안","correct":true},{"t":"사람이 거의 없는 어두운 공사장","mis":"SC5-2-u4-X38"},{"t":"차가 다니는 찻길 한가운데","mis":"SC5-2-u4-X38"},{"t":"물이 깊은 강가","mis":"SC5-2-u4-X38"}],"explanation":["안전이 먼저예요.","위험한 곳은 피해요.","교실이나 집 안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L07_challenge#4','sci',5,2,'u4','L07','g5_2_sci_u4_L07_challenge','lesson_challenge','SC5-2-u4-C15',3,'mc','auto','음식물 쓰레기를 줄이는 실천 영상에 넣기 알맞은 장면은 어느 것인가요?',ARRAY['SC5-2-u4-X28','SC5-2-u4-X37']::text[],false,'{"seq":4,"concept":"SC5-2-u4-C15","difficulty":3,"kind":"mc","stem":"음식물 쓰레기를 줄이는 실천 영상에 넣기 알맞은 장면은 어느 것인가요?","options":[{"t":"먹을 만큼만 요리하고 남김없이 먹는 모습","correct":true},{"t":"음식을 많이 남기고 버리는 모습","mis":"SC5-2-u4-X28"},{"t":"음식을 일회용 그릇에 담아 바로 버리는 모습","mis":"SC5-2-u4-X28"},{"t":"음식과 상관없는 춤 장면","mis":"SC5-2-u4-X37"}],"explanation":["먹을 만큼만 해요.","남기지 않아요.","쓰레기가 줄어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L07_challenge#5','sci',5,2,'u4','L07','g5_2_sci_u4_L07_challenge','lesson_challenge','SC5-2-u4-C20',3,'ox','auto','스토리 보드에 다른 사람을 놀리거나 비하하는 장면을 넣어도 웃기면 괜찮아요.',ARRAY['SC5-2-u4-X38']::text[],false,'{"seq":5,"concept":"SC5-2-u4-C20","difficulty":3,"kind":"ox","stem":"스토리 보드에 다른 사람을 놀리거나 비하하는 장면을 넣어도 웃기면 괜찮아요.","answer":"X","reason_options":[{"t":"다른 사람에게 불쾌감을 주는 내용은 넣지 않아야 하기 때문에","correct":true},{"t":"재미있으면 무엇이든 넣어도 되기 때문에","mis":"SC5-2-u4-X38"}],"mis":"SC5-2-u4-X38","explanation":["불쾌감을 줘요.","존중해야 해요.","넣지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L07_challenge#6','sci',5,2,'u4','L07','g5_2_sci_u4_L07_challenge','lesson_challenge','SC5-2-u4-C20',3,'error','auto','실천 영상 주제를 정하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u4-X37']::text[],false,'{"seq":6,"concept":"SC5-2-u4-C20","difficulty":3,"kind":"error","stem":"실천 영상 주제를 정하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은재 — 「우주에 발전소를 짓는 모습을 실천 영상으로 찍자.」","correct":true,"mis_target":"SC5-2-u4-X37"},{"t":"해솔 — 「분리배출 하는 모습을 찍자.」","mis":"SC5-2-u4-X37"},{"t":"다빈 — 「자전거 타고 등교하는 모습도 좋아.」","mis":"SC5-2-u4-X37"}],"explanation":["생활에서 할 수 있어야 해요.","우주 발전소는 어려워요.","은재의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L07_challenge#7','sci',5,2,'u4','L07','g5_2_sci_u4_L07_challenge','lesson_challenge','SC5-2-u4-C16',3,'mc','auto','교실에서 난방 에너지를 아끼는 실천 영상에 넣기 알맞은 장면은 어느 것인가요?',ARRAY['SC5-2-u4-X23']::text[],false,'{"seq":7,"concept":"SC5-2-u4-C16","difficulty":3,"kind":"mc","stem":"교실에서 난방 에너지를 아끼는 실천 영상에 넣기 알맞은 장면은 어느 것인가요?","options":[{"t":"「문을 닫아요」 팻말을 들고 난방 중인 교실 문을 닫는 모습","correct":true},{"t":"창문을 활짝 열고 난방을 세게 켜는 모습","mis":"SC5-2-u4-X23"},{"t":"빈 교실의 난방기를 켜 두는 모습","mis":"SC5-2-u4-X23"},{"t":"복도 전등을 모두 켜는 모습","mis":"SC5-2-u4-X23"}],"explanation":["난방 중이에요.","문을 닫아요.","열을 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L07_challenge#8','sci',5,2,'u4','L07','g5_2_sci_u4_L07_challenge','lesson_challenge','SC5-2-u4-C20',4,'mc','auto','더 많은 사람이 함께 실천하게 하려면 영상을 어떻게 쓰는 것이 가장 알맞은가요?',ARRAY['SC5-2-u4-X39','SC5-2-u4-X38','SC5-2-u4-X37']::text[],false,'{"seq":8,"concept":"SC5-2-u4-C20","difficulty":4,"kind":"mc","stem":"더 많은 사람이 함께 실천하게 하려면 영상을 어떻게 쓰는 것이 가장 알맞은가요?","options":[{"t":"학급 누리집에 올려 가족과 이웃에게도 알리고 함께 실천하자고 권한다","correct":true},{"t":"혼자만 보고 아무에게도 알리지 않는다","mis":"SC5-2-u4-X39"},{"t":"친구 집 주소를 함께 적어 퍼뜨린다","mis":"SC5-2-u4-X38"},{"t":"실천과 상관없는 장면만 더 넣는다","mis":"SC5-2-u4-X37"}],"explanation":["널리 알려요.","함께하자고 해요.","실천이 퍼져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L07_challenge#9','sci',5,2,'u4','L07','g5_2_sci_u4_L07_challenge','lesson_challenge','SC5-2-u4-C20',4,'mc','auto','다른 모둠의 물 절약 영상에 단 댓글로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X38','SC5-2-u4-X39']::text[],false,'{"seq":9,"concept":"SC5-2-u4-C20","difficulty":4,"kind":"mc","stem":"다른 모둠의 물 절약 영상에 단 댓글로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「설거지통에 물을 받아 쓰는 방법을 우리 집에도 알려야겠어요.」","correct":true},{"t":"「이런 걸 왜 찍었어요?」","mis":"SC5-2-u4-X38"},{"t":"「영상 속 친구 이름이 뭐예요? 어디 살아요?」","mis":"SC5-2-u4-X38"},{"t":"「나는 그냥 물을 계속 틀어 놓을래요.」","mis":"SC5-2-u4-X39"}],"explanation":["배운 점을 써요.","고운 말이에요.","실천도 다짐해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L07_challenge#10','sci',5,2,'u4','L07','g5_2_sci_u4_L07_challenge','lesson_challenge','SC5-2-u4-C20',4,'essay','teacher','우리 모둠의 실천 영상 계획을 쓰세요. 주제, 넣을 장면 두 개, 영상을 만들 때 지킬 점 하나를 넣으세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-2-u4-C20","difficulty":4,"kind":"essay","stem":"우리 모둠의 실천 영상 계획을 쓰세요. 주제, 넣을 장면 두 개, 영상을 만들 때 지킬 점 하나를 넣으세요.","answer_guide":{"answer":"예: 주제 — 교실 전기 아끼기. 장면 1 — 이동 수업 때 전등을 끄는 모습. 장면 2 — 쓰지 않는 기기의 플러그를 뽑는 모습. 지킬 점 — 친구의 이름이나 얼굴 같은 개인 정보는 허락 없이 넣지 않는다.","scoring_points":["생활에서 실천할 수 있는 주제를 정했는가","주제에 맞는 실천 장면을 두 개 썼는가","지킬 점(개인 정보·존중·안전 등)을 썼는가"]},"explanation":["주제를 정해요.","장면을 써요.","지킬 점을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L08_basic#1','sci',5,2,'u4','L08','g5_2_sci_u4_L08_basic','lesson_basic','SC5-2-u4-C21',1,'mc','auto','두 미래 에너지 전문가의 말에서 ㉮는 어떤 전문가인가요?',ARRAY['SC5-2-u4-X41']::text[],false,'{"seq":1,"concept":"SC5-2-u4-C21","difficulty":1,"kind":"mc","stem":"두 미래 에너지 전문가의 말에서 ㉮는 어떤 전문가인가요?","options":[{"t":"재생 에너지 전문가","correct":true},{"t":"에너지 하베스팅 전문가","mis":"SC5-2-u4-X41"},{"t":"석탄을 캐는 사람","mis":"SC5-2-u4-X41"},{"t":"영상 감독","mis":"SC5-2-u4-X41"}],"explanation":["태양 전지를 연구해요.","풍력 발전기도요.","재생 에너지 전문가예요."],"asset":{"type":"passage","lines":["㉮ 더 좋은 태양 전지와 풍력 발전기를 연구하고, 발전기를 세울 알맞은 곳을 찾아요.","㉯ 새어 나가는 빛, 자동차의 떨림, 체온처럼 그냥 버려지는 에너지를 모아 쓰는 방법을 연구해요."],"title":"두 미래 에너지 전문가의 말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L08_basic#2','sci',5,2,'u4','L08','g5_2_sci_u4_L08_basic','lesson_basic','SC5-2-u4-C21',1,'mc','auto','일상에서 버려지는 에너지를 모아 쓰는 방법을 연구하는 사람은 누구인가요?',ARRAY['SC5-2-u4-X40']::text[],false,'{"seq":2,"concept":"SC5-2-u4-C21","difficulty":1,"kind":"mc","stem":"일상에서 버려지는 에너지를 모아 쓰는 방법을 연구하는 사람은 누구인가요?","options":[{"t":"에너지 하베스팅 전문가","correct":true},{"t":"재생 에너지 전문가","mis":"SC5-2-u4-X40"},{"t":"자원을 마구 캐는 사람","mis":"SC5-2-u4-X40"},{"t":"집 모형을 꾸미는 사람","mis":"SC5-2-u4-X40"}],"explanation":["버려지는 에너지예요.","모아서 써요.","하베스팅 전문가예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L08_basic#3','sci',5,2,'u4','L08','g5_2_sci_u4_L08_basic','lesson_basic','SC5-2-u4-C21',1,'ox','auto','걸을 때 바닥을 누르는 힘도 모으면 에너지로 쓸 수 있어요.',ARRAY['SC5-2-u4-X40']::text[],false,'{"seq":3,"concept":"SC5-2-u4-C21","difficulty":1,"kind":"ox","stem":"걸을 때 바닥을 누르는 힘도 모으면 에너지로 쓸 수 있어요.","answer":"O","reason_options":[{"t":"버려지는 에너지를 모아 쓰는 기술이 있기 때문에","correct":true},{"t":"사람이 움직이는 힘은 에너지가 될 수 없기 때문에","mis":"SC5-2-u4-X40"}],"mis":"SC5-2-u4-X40","explanation":["걸을 때 힘이 생겨요.","모을 수 있어요.","에너지로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L08_basic#4','sci',5,2,'u4','L08','g5_2_sci_u4_L08_basic','lesson_basic','SC5-2-u4-C22',1,'mc','auto','「자원과 에너지」 단원을 정리한 말로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X11','SC5-2-u4-X42','SC5-2-u4-X21']::text[],false,'{"seq":4,"concept":"SC5-2-u4-C22","difficulty":1,"kind":"mc","stem":"「자원과 에너지」 단원을 정리한 말로 알맞은 것은 어느 것인가요?","options":[{"t":"자원은 한정되어 있어 아끼고 효율적으로 써야 한다","correct":true},{"t":"자원은 끝없이 있어 마음껏 써도 된다","mis":"SC5-2-u4-X11"},{"t":"재생 에너지가 있으니 아낄 필요가 없다","mis":"SC5-2-u4-X42"},{"t":"석탄과 석유가 가장 깨끗한 에너지다","mis":"SC5-2-u4-X21"}],"explanation":["자원은 한정돼요.","아껴 써요.","효율적으로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L08_basic#5','sci',5,2,'u4','L08','g5_2_sci_u4_L08_basic','lesson_basic','SC5-2-u4-C21',2,'mc','auto','에너지 놀이터 아이디어 가운데 사람이 움직일 때 생기는 힘을 모으는 것끼리 모은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X40']::text[],false,'{"seq":5,"concept":"SC5-2-u4-C21","difficulty":2,"kind":"mc","stem":"에너지 놀이터 아이디어 가운데 사람이 움직일 때 생기는 힘을 모으는 것끼리 모은 것은 어느 것인가요?","options":[{"t":"①, ②","correct":true},{"t":"③, ④","mis":"SC5-2-u4-X40"},{"t":"③","mis":"SC5-2-u4-X40"},{"t":"①, ③","mis":"SC5-2-u4-X40"}],"explanation":["뛰면 모여요.","그네를 타면 모여요.","①과 ②예요."],"asset":{"type":"passage","lines":["① 뛰면 에너지가 모이는 바닥 타일","② 탈 때마다 에너지를 모으는 그네","③ 밤새 켜 두는 큰 조명","④ 미끄럼틀 지붕의 태양 전지판"],"title":"에너지 놀이터 아이디어"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L08_basic#6','sci',5,2,'u4','L08','g5_2_sci_u4_L08_basic','lesson_basic','SC5-2-u4-C21',2,'mc','auto','에너지 하베스팅의 예로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X40','SC5-2-u4-X23']::text[],false,'{"seq":6,"concept":"SC5-2-u4-C21","difficulty":2,"kind":"mc","stem":"에너지 하베스팅의 예로 알맞은 것은 어느 것인가요?","options":[{"t":"뜨거운 물이나 기구에서 버려지는 열을 모아 전기를 만든다","correct":true},{"t":"땅속 석탄을 더 많이 캔다","mis":"SC5-2-u4-X40"},{"t":"새 석탄 발전소를 짓는다","mis":"SC5-2-u4-X40"},{"t":"쓰지 않는 조명을 밤새 켜 둔다","mis":"SC5-2-u4-X23"}],"explanation":["열이 버려져요.","모아서 써요.","하베스팅이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L08_basic#7','sci',5,2,'u4','L08','g5_2_sci_u4_L08_basic','lesson_basic','SC5-2-u4-C21',2,'ox','auto','두 미래 에너지 전문가의 말에서 ㉮ 같은 전문가는 사람들에게 재생 에너지의 중요성을 알리는 일도 해요.',ARRAY['SC5-2-u4-X41']::text[],false,'{"seq":7,"concept":"SC5-2-u4-C21","difficulty":2,"kind":"ox","stem":"두 미래 에너지 전문가의 말에서 ㉮ 같은 전문가는 사람들에게 재생 에너지의 중요성을 알리는 일도 해요.","answer":"O","reason_options":[{"t":"재생 에너지를 널리 쓰게 돕는 것도 할 일이기 때문에","correct":true},{"t":"재생 에너지 전문가는 석유를 더 많이 쓰게 하는 사람이기 때문에","mis":"SC5-2-u4-X41"}],"mis":"SC5-2-u4-X41","explanation":["연구도 해요.","널리 알려요.","함께 쓰게 도와요."],"asset":{"type":"passage","lines":["㉮ 더 좋은 태양 전지와 풍력 발전기를 연구하고, 발전기를 세울 알맞은 곳을 찾아요.","㉯ 새어 나가는 빛, 자동차의 떨림, 체온처럼 그냥 버려지는 에너지를 모아 쓰는 방법을 연구해요."],"title":"두 미래 에너지 전문가의 말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L08_basic#8','sci',5,2,'u4','L08','g5_2_sci_u4_L08_basic','lesson_basic','SC5-2-u4-C22',2,'mc','auto','방법과 그 효과를 바르게 짝지은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X35','SC5-2-u4-X30','SC5-2-u4-X27']::text[],false,'{"seq":8,"concept":"SC5-2-u4-C22","difficulty":2,"kind":"mc","stem":"방법과 그 효과를 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"빗물 저금통 — 물 자원을 효율적으로 이용","correct":true},{"t":"이중창 — 전기를 생산","mis":"SC5-2-u4-X35"},{"t":"분리배출 — 산림 자원만 아낌","mis":"SC5-2-u4-X30"},{"t":"5등급 제품 — 효율이 가장 높음","mis":"SC5-2-u4-X27"}],"explanation":["빗물을 모아요.","다시 써요.","물을 아껴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L08_basic#9','sci',5,2,'u4','L08','g5_2_sci_u4_L08_basic','lesson_basic','SC5-2-u4-C22',2,'mc','auto','자연에서 얻어 계속 쓸 수 있는 에너지끼리 모은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X13','SC5-2-u4-X21']::text[],false,'{"seq":9,"concept":"SC5-2-u4-C22","difficulty":2,"kind":"mc","stem":"자연에서 얻어 계속 쓸 수 있는 에너지끼리 모은 것은 어느 것인가요?","options":[{"t":"태양 에너지, 지열 에너지, 바이오 에너지","correct":true},{"t":"석탄, 석유, 풍력","mis":"SC5-2-u4-X13"},{"t":"석탄, 수력, 석유","mis":"SC5-2-u4-X13"},{"t":"석유, 해양 에너지, 석탄","mis":"SC5-2-u4-X21"}],"explanation":["석탄·석유는 빼요.","자연에서 계속 얻어요.","세 가지 모두 재생 에너지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L08_basic#10','sci',5,2,'u4','L08','g5_2_sci_u4_L08_basic','lesson_basic','SC5-2-u4-C22',3,'error','auto','단원을 마무리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u4-X42','SC5-2-u4-X11','SC5-2-u4-X33']::text[],false,'{"seq":10,"concept":"SC5-2-u4-C22","difficulty":3,"kind":"error","stem":"단원을 마무리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"로운 — 「재생 에너지가 있으니까 이제 전기는 마음껏 써도 돼.」","correct":true,"mis_target":"SC5-2-u4-X42"},{"t":"예솔 — 「물·산림·광물 자원은 한정되어 있어.」","mis":"SC5-2-u4-X11"},{"t":"지환 — 「단열을 하면 에너지 효율이 높아져.」","mis":"SC5-2-u4-X33"}],"explanation":["재생 에너지도 아직 모자라요.","아끼기도 함께해요.","로운의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L08_challenge#1','sci',5,2,'u4','L08','g5_2_sci_u4_L08_challenge','lesson_challenge','SC5-2-u4-C22',2,'match','auto','단원에서 배운 내용과 그 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-2-u4-C22","difficulty":2,"kind":"match","stem":"단원에서 배운 내용과 그 내용을 알맞게 이으세요.","pairs":[{"l":"자원의 유한성","r":"물·산림·광물 자원은 계속 쓰기 어려움"},{"l":"지속가능한 이용","r":"재생 에너지·친환경 기술·절약"},{"l":"효율적인 이용","r":"1등급 제품·단열·재활용"}],"mis":"SC5-2-u4-X42","explanation":["자원은 한정돼요.","세 갈래로 지속가능하게요.","효율적으로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L08_challenge#2','sci',5,2,'u4','L08','g5_2_sci_u4_L08_challenge','lesson_challenge','SC5-2-u4-C21',2,'mc','auto','일상에서 그냥 버려지는 에너지의 예로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X40']::text[],false,'{"seq":2,"concept":"SC5-2-u4-C21","difficulty":2,"kind":"mc","stem":"일상에서 그냥 버려지는 에너지의 예로 알맞은 것은 어느 것인가요?","options":[{"t":"집 창문으로 새어 나오는 조명의 빛","correct":true},{"t":"땅속에 묻힌 석탄","mis":"SC5-2-u4-X40"},{"t":"가게에 진열된 새 건전지","mis":"SC5-2-u4-X40"},{"t":"아직 쓰지 않은 휘발유","mis":"SC5-2-u4-X40"}],"explanation":["빛이 새어 나와요.","쓰지 못하고 버려져요.","모을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L08_challenge#3','sci',5,2,'u4','L08','g5_2_sci_u4_L08_challenge','lesson_challenge','SC5-2-u4-C21',3,'mc','auto','학교에서 해 볼 수 있는 에너지 하베스팅 아이디어로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X23','SC5-2-u4-X21','SC5-2-u4-X25']::text[],false,'{"seq":3,"concept":"SC5-2-u4-C21","difficulty":3,"kind":"mc","stem":"학교에서 해 볼 수 있는 에너지 하베스팅 아이디어로 알맞은 것은 어느 것인가요?","options":[{"t":"복도 바닥에 밟으면 에너지가 모이는 판을 깔아 작은 전등을 켠다","correct":true},{"t":"복도 전등을 하루 종일 켜 둔다","mis":"SC5-2-u4-X23"},{"t":"운동장에 석탄을 쌓아 태운다","mis":"SC5-2-u4-X21"},{"t":"교실 플러그를 모두 꽂아 둔다","mis":"SC5-2-u4-X25"}],"explanation":["걸을 때 힘이 생겨요.","바닥이 모아요.","전등을 켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L08_challenge#4','sci',5,2,'u4','L08','g5_2_sci_u4_L08_challenge','lesson_challenge','SC5-2-u4-C9',3,'mc','auto','산 위는 바람이 세고 집집마다 지붕이 넓으며 음식물 쓰레기가 많이 나오는 마을의 계획으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X18','SC5-2-u4-X21','SC5-2-u4-X19']::text[],false,'{"seq":4,"concept":"SC5-2-u4-C9","difficulty":3,"kind":"mc","stem":"산 위는 바람이 세고 집집마다 지붕이 넓으며 음식물 쓰레기가 많이 나오는 마을의 계획으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"산 위에는 풍력, 지붕에는 태양 전지판, 음식물 쓰레기로 바이오 에너지","correct":true},{"t":"산 위에 바이오 에너지, 지붕에 수력, 쓰레기로 풍력","mis":"SC5-2-u4-X18"},{"t":"석탄을 들여와 모두 태운다","mis":"SC5-2-u4-X21"},{"t":"재생 에너지는 단점이 없으니 아무 데나 세운다","mis":"SC5-2-u4-X19"}],"explanation":["바람은 산 위예요.","햇빛은 지붕이에요.","쓰레기는 바이오예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L08_challenge#5','sci',5,2,'u4','L08','g5_2_sci_u4_L08_challenge','lesson_challenge','SC5-2-u4-C19',3,'ox','auto','에너지 효율이 높은 집을 짓는 친구에게 단열재와 이중창을 알려 주면 좋아요.',ARRAY['SC5-2-u4-X35']::text[],false,'{"seq":5,"concept":"SC5-2-u4-C19","difficulty":3,"kind":"ox","stem":"에너지 효율이 높은 집을 짓는 친구에게 단열재와 이중창을 알려 주면 좋아요.","answer":"O","reason_options":[{"t":"집 안 열이 빠져나가는 것을 막아 냉난방 에너지를 아끼기 때문에","correct":true},{"t":"단열재와 이중창이 스스로 전기를 만들어 주기 때문에","mis":"SC5-2-u4-X35"}],"mis":"SC5-2-u4-X35","explanation":["열을 막아요.","냉난방을 아껴요.","효율이 높아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L08_challenge#6','sci',5,2,'u4','L08','g5_2_sci_u4_L08_challenge','lesson_challenge','SC5-2-u4-C21',3,'error','auto','두 미래 에너지 전문가의 말을 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u4-X40','SC5-2-u4-X41']::text[],false,'{"seq":6,"concept":"SC5-2-u4-C21","difficulty":3,"kind":"error","stem":"두 미래 에너지 전문가의 말을 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"나은 — 「㉯ 전문가는 새 석탄 광산을 찾는 사람이야.」","correct":true,"mis_target":"SC5-2-u4-X40"},{"t":"예준 — 「㉮ 전문가는 발전기를 세울 곳도 찾아.」","mis":"SC5-2-u4-X41"},{"t":"하랑 — 「㉯ 전문가는 체온도 에너지로 써.」","mis":"SC5-2-u4-X40"}],"explanation":["㉯는 버려지는 에너지를 모아요.","석탄 광산이 아니에요.","나은의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["㉮ 더 좋은 태양 전지와 풍력 발전기를 연구하고, 발전기를 세울 알맞은 곳을 찾아요.","㉯ 새어 나가는 빛, 자동차의 떨림, 체온처럼 그냥 버려지는 에너지를 모아 쓰는 방법을 연구해요."],"title":"두 미래 에너지 전문가의 말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L08_challenge#7','sci',5,2,'u4','L08','g5_2_sci_u4_L08_challenge','lesson_challenge','SC5-2-u4-C10',3,'mc','auto','재생 에너지 시설을 늘리자는 의견에 반대하는 쪽이 근거로 들 수 있는 것은 어느 것인가요?',ARRAY['SC5-2-u4-X13','SC5-2-u4-X20']::text[],false,'{"seq":7,"concept":"SC5-2-u4-C10","difficulty":3,"kind":"mc","stem":"재생 에너지 시설을 늘리자는 의견에 반대하는 쪽이 근거로 들 수 있는 것은 어느 것인가요?","options":[{"t":"시설을 지을 때 생물의 보금자리가 망가지거나 소음이 생길 수 있다","correct":true},{"t":"재생 에너지는 쓰면 금방 바닥난다","mis":"SC5-2-u4-X13"},{"t":"재생 에너지는 공기를 가장 많이 더럽힌다","mis":"SC5-2-u4-X20"},{"t":"재생 에너지는 자연에서 얻을 수 없다","mis":"SC5-2-u4-X13"}],"explanation":["생태계에 영향을 줘요.","소음도 있어요.","반대 근거가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L08_challenge#8','sci',5,2,'u4','L08','g5_2_sci_u4_L08_challenge','lesson_challenge','SC5-2-u4-C21',4,'mc','auto','에너지 놀이터 아이디어의 ③을 고친 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X23','SC5-2-u4-X25','SC5-2-u4-X27']::text[],false,'{"seq":8,"concept":"SC5-2-u4-C21","difficulty":4,"kind":"mc","stem":"에너지 놀이터 아이디어의 ③을 고친 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"사람이 다가올 때만 켜지고, 낮에 모은 햇빛 에너지로 켜지는 조명","correct":true},{"t":"조명을 더 크게, 더 많이 단다","mis":"SC5-2-u4-X23"},{"t":"조명을 켠 채 플러그를 하나 더 꽂는다","mis":"SC5-2-u4-X25"},{"t":"조명을 5등급 제품으로 바꾼다","mis":"SC5-2-u4-X27"}],"explanation":["밤새 켜 두면 낭비예요.","필요할 때만 켜요.","햇빛 에너지로 켜요."],"asset":{"type":"passage","lines":["① 뛰면 에너지가 모이는 바닥 타일","② 탈 때마다 에너지를 모으는 그네","③ 밤새 켜 두는 큰 조명","④ 미끄럼틀 지붕의 태양 전지판"],"title":"에너지 놀이터 아이디어"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L08_challenge#9','sci',5,2,'u4','L08','g5_2_sci_u4_L08_challenge','lesson_challenge','SC5-2-u4-C22',4,'mc','auto','단원 전체를 생각한 실천 계획으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X42','SC5-2-u4-X28','SC5-2-u4-X27']::text[],false,'{"seq":9,"concept":"SC5-2-u4-C22","difficulty":4,"kind":"mc","stem":"단원 전체를 생각한 실천 계획으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"물은 받아 쓰고 이면지를 쓰며 분리배출하고, 1등급 제품과 재생 에너지에 관심을 갖는다","correct":true},{"t":"재생 에너지만 있으면 되니 다른 실천은 안 한다","mis":"SC5-2-u4-X42"},{"t":"편하게 짧은 거리도 자동차를 탄다","mis":"SC5-2-u4-X28"},{"t":"효율 등급 숫자가 큰 제품을 고른다","mis":"SC5-2-u4-X27"}],"explanation":["자원을 아껴요.","에너지도 효율적으로요.","함께 실천해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L08_challenge#10','sci',5,2,'u4','L08','g5_2_sci_u4_L08_challenge','lesson_challenge','SC5-2-u4-C21',4,'essay','teacher','미래 에너지 전문가가 되어 우리 학교에서 버려지는 에너지를 찾아 모아 쓰는 아이디어를 쓰세요. 어떤 에너지가 버려지는지와 어디에 쓸지 넣으세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-2-u4-C21","difficulty":4,"kind":"essay","stem":"미래 에너지 전문가가 되어 우리 학교에서 버려지는 에너지를 찾아 모아 쓰는 아이디어를 쓰세요. 어떤 에너지가 버려지는지와 어디에 쓸지 넣으세요.","answer_guide":{"answer":"예: 계단을 오르내릴 때 바닥을 누르는 힘이 버려진다. 계단 바닥에 밟으면 에너지가 모이는 판을 깔아 모은 에너지로 계단 비상등을 켠다.","scoring_points":["학교에서 버려지는 에너지를 찾았는가","그 에너지를 모으는 방법을 썼는가","모은 에너지를 쓸 곳을 썼는가"]},"explanation":["버려지는 것을 찾아요.","모으는 방법이에요.","쓸 곳을 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_a#1','sci',5,2,'u4','','g5_2_sci_u4_review_a','unit_review','SC5-2-u4-C2',1,'mc','auto','누리반 탐방 일지 ①에서 전구에 불이 켜진 때는 언제인가요?',ARRAY['SC5-2-u4-X01','SC5-2-u4-X03']::text[],false,'{"seq":1,"concept":"SC5-2-u4-C2","difficulty":1,"kind":"mc","stem":"누리반 탐방 일지 ①에서 전구에 불이 켜진 때는 언제인가요?","options":[{"t":"날개가 빨리 돌 때","correct":true},{"t":"날개가 멈췄을 때","mis":"SC5-2-u4-X01"},{"t":"바람이 전혀 없을 때","mis":"SC5-2-u4-X03"},{"t":"전구를 손으로 덮었을 때","mis":"SC5-2-u4-X01"}],"explanation":["바람을 보냈어요.","날개가 빨리 돌아요.","불이 켜졌어요."],"asset":{"type":"passage","lines":["배에서 내리자 언덕 위 풍력 발전기의 긴 날개 세 개가 돌고 있었다.","우리는 풍력 발전 모형에 머리 말리개 바람을 보냈다.","날개가 빨리 돌자 전구에 불이 켜졌다.","해설사: 「바람이 약한 날엔 날개가 천천히 돌아요.」"],"title":"① 첫날 — 바람의 섬에 도착"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_a#2','sci',5,2,'u4','','g5_2_sci_u4_review_a','unit_review','SC5-2-u4-C4',1,'mc','auto','누리반 탐방 일지 ②에서 우물물과 빗물은 어떤 자원인가요?',ARRAY['SC5-2-u4-X06']::text[],false,'{"seq":2,"concept":"SC5-2-u4-C4","difficulty":1,"kind":"mc","stem":"누리반 탐방 일지 ②에서 우물물과 빗물은 어떤 자원인가요?","options":[{"t":"물 자원","correct":true},{"t":"산림 자원","mis":"SC5-2-u4-X06"},{"t":"광물 자원","mis":"SC5-2-u4-X06"},{"t":"바람 자원","mis":"SC5-2-u4-X06"}],"explanation":["물이에요.","마시고 씻어요.","물 자원이에요."],"asset":{"type":"passage","lines":["섬 사람들은 우물물과 빗물을 모아 쓴다.","뒷산 나무로 집을 지었는데, 다시 자라려면 오래 걸린다고 한다.","옛 돌 광산은 묻혀 있던 돌이 바닥나 문을 닫았다.","섬마을 이장님: 「캔은 꼭 분리배출해요.」"],"title":"② 첫날 오후 — 섬의 자원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_a#3','sci',5,2,'u4','','g5_2_sci_u4_review_a','unit_review','SC5-2-u4-C5',1,'mc','auto','누리반 탐방 일지 ②에서 옛 돌 광산이 문을 닫은 까닭은 어느 것인가요?',ARRAY['SC5-2-u4-X10','SC5-2-u4-X11','SC5-2-u4-X05']::text[],false,'{"seq":3,"concept":"SC5-2-u4-C5","difficulty":1,"kind":"mc","stem":"누리반 탐방 일지 ②에서 옛 돌 광산이 문을 닫은 까닭은 어느 것인가요?","options":[{"t":"묻혀 있던 돌의 양이 한정되어 바닥났기 때문이다","correct":true},{"t":"돌이 너무 빨리 다시 생겨서","mis":"SC5-2-u4-X10"},{"t":"돌을 재활용해 끝없이 쓸 수 있어서","mis":"SC5-2-u4-X11"},{"t":"돌은 자원이 아니어서","mis":"SC5-2-u4-X05"}],"explanation":["묻힌 양이 정해져 있어요.","다 캐냈어요.","바닥났어요."],"asset":{"type":"passage","lines":["섬 사람들은 우물물과 빗물을 모아 쓴다.","뒷산 나무로 집을 지었는데, 다시 자라려면 오래 걸린다고 한다.","옛 돌 광산은 묻혀 있던 돌이 바닥나 문을 닫았다.","섬마을 이장님: 「캔은 꼭 분리배출해요.」"],"title":"② 첫날 오후 — 섬의 자원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_a#4','sci',5,2,'u4','','g5_2_sci_u4_review_a','unit_review','SC5-2-u4-C8',1,'mc','auto','누리반 탐방 일지 ③에서 바닷가 둑의 시설이 얻는 재생 에너지는 어느 것인가요?',ARRAY['SC5-2-u4-X14','SC5-2-u4-X17']::text[],false,'{"seq":4,"concept":"SC5-2-u4-C8","difficulty":1,"kind":"mc","stem":"누리반 탐방 일지 ③에서 바닷가 둑의 시설이 얻는 재생 에너지는 어느 것인가요?","options":[{"t":"해양 에너지","correct":true},{"t":"수력","mis":"SC5-2-u4-X14"},{"t":"지열 에너지","mis":"SC5-2-u4-X14"},{"t":"바이오 에너지","mis":"SC5-2-u4-X17"}],"explanation":["밀물과 썰물이에요.","바다예요.","해양 에너지예요."],"asset":{"type":"passage","lines":["언덕 — 풍력 발전기","집 지붕 — 태양 전지판","바닷가 둑 — 밀물과 썰물을 쓰는 발전 시설","돼지 농장 — 분뇨로 가스를 만드는 시설","마을 회관 땅속 — 땅속 열을 쓰는 냉난방"],"title":"③ 둘째 날 — 섬의 재생 에너지 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_a#5','sci',5,2,'u4','','g5_2_sci_u4_review_a','unit_review','SC5-2-u4-C9',1,'mc','auto','바람솔섬 언덕에 풍력 발전기를 세운 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X18','SC5-2-u4-X21']::text[],false,'{"seq":5,"concept":"SC5-2-u4-C9","difficulty":1,"kind":"mc","stem":"바람솔섬 언덕에 풍력 발전기를 세운 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"언덕에 바람이 세고 자주 불어서","correct":true},{"t":"언덕에 가축이 많아서","mis":"SC5-2-u4-X18"},{"t":"언덕에 물이 세차게 흘러서","mis":"SC5-2-u4-X18"},{"t":"언덕 땅속에 석탄이 많아서","mis":"SC5-2-u4-X21"}],"explanation":["섬은 바람이 세요.","언덕은 더 세요.","풍력에 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_a#6','sci',5,2,'u4','','g5_2_sci_u4_review_a','unit_review','SC5-2-u4-C11',1,'mc','auto','누리반 탐방 일지 ④의 결정에서 「미래 세대를 생각한다」는 것은 무엇을 뜻하나요?',ARRAY['SC5-2-u4-X22','SC5-2-u4-X21']::text[],false,'{"seq":6,"concept":"SC5-2-u4-C11","difficulty":1,"kind":"mc","stem":"누리반 탐방 일지 ④의 결정에서 「미래 세대를 생각한다」는 것은 무엇을 뜻하나요?","options":[{"t":"지금 쓰면서도 미래 세대가 쓸 에너지를 지킨다","correct":true},{"t":"지금 세대만 마음껏 쓴다","mis":"SC5-2-u4-X22"},{"t":"미래에는 에너지가 필요 없다","mis":"SC5-2-u4-X22"},{"t":"석유를 빨리 다 쓴다","mis":"SC5-2-u4-X21"}],"explanation":["지금도 써요.","미래도 생각해요.","지속가능이에요."],"asset":{"type":"passage","lines":["주민 1: 「바람이 약한 날은 전기가 모자라요.」","주민 2: 「옛날처럼 석유 발전기를 다시 돌립시다.」","주민 3: 「에너지를 모아 두는 기술을 들이고 모두 함께 아껴 씁시다.」","결정 — 재생 에너지를 늘리고 절약하며, 미래 세대를 생각한다."],"title":"④ 둘째 날 저녁 — 마을 회의"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_a#7','sci',5,2,'u4','','g5_2_sci_u4_review_a','unit_review','SC5-2-u4-C14',1,'mc','auto','누리반 탐방 일지 ⑤의 두 냉장고 가운데 에너지 효율이 더 높은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X27']::text[],false,'{"seq":7,"concept":"SC5-2-u4-C14","difficulty":1,"kind":"mc","stem":"누리반 탐방 일지 ⑤의 두 냉장고 가운데 에너지 효율이 더 높은 것은 어느 것인가요?","options":[{"t":"냉장고 ㉮","correct":true},{"t":"냉장고 ㉯","mis":"SC5-2-u4-X27"},{"t":"둘이 같다","mis":"SC5-2-u4-X27"},{"t":"등급으로는 알 수 없다","mis":"SC5-2-u4-X27"}],"explanation":["㉮는 1등급이에요.","1등급에 가까울수록요.","㉮예요."],"asset":{"type":"passage","lines":["냉장고 ㉮ — 1등급, 냉장고 ㉯ — 5등급(크기와 기능이 같다)","꺼 둔 텔레비전의 플러그가 꽂혀 있었다.","수도꼭지는 움직임을 알아차려 저절로 멈추는 것으로 바뀌었다.","종이컵 대신 다회용 컵이 놓여 있었다."],"title":"⑤ 셋째 날 — 마을 회관 살펴보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_a#8','sci',5,2,'u4','','g5_2_sci_u4_review_a','unit_review','SC5-2-u4-C18',1,'mc','auto','누리반 탐방 일지 ⑥에서 에너지 효율이 더 높은 집은 어느 것인가요?',ARRAY['SC5-2-u4-X33','SC5-2-u4-X34']::text[],false,'{"seq":8,"concept":"SC5-2-u4-C18","difficulty":1,"kind":"mc","stem":"누리반 탐방 일지 ⑥에서 에너지 효율이 더 높은 집은 어느 것인가요?","options":[{"t":"단열한 집","correct":true},{"t":"단열 안 한 집","mis":"SC5-2-u4-X33"},{"t":"두 집이 같다","mis":"SC5-2-u4-X34"},{"t":"처음 온도가 높은 집","mis":"SC5-2-u4-X34"}],"explanation":["변화량을 견줘요.","단열한 집이 덜 변해요.","단열한 집이에요."],"asset":{"type":"passage","lines":["단열 안 한 집 — 처음 28.0 °C → 5분 뒤 23.6 °C","단열한 집(뽁뽁이 두 겹·우드록·색점토) — 처음 27.0 °C → 5분 뒤 25.2 °C","두 집은 크기가 같고, 같은 손난로로 데운 뒤 1분마다 쟀다."],"title":"⑥ 셋째 날 오후 — 집 모형 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_a#9','sci',5,2,'u4','','g5_2_sci_u4_review_a','unit_review','SC5-2-u4-C2',2,'mc','auto','누리반 탐방 일지 ①의 해설사 말로 알 수 있는 것은 어느 것인가요?',ARRAY['SC5-2-u4-X02','SC5-2-u4-X01','SC5-2-u4-X03']::text[],false,'{"seq":9,"concept":"SC5-2-u4-C2","difficulty":2,"kind":"mc","stem":"누리반 탐방 일지 ①의 해설사 말로 알 수 있는 것은 어느 것인가요?","options":[{"t":"바람이 약하면 날개가 천천히 돌아 에너지가 덜 만들어진다","correct":true},{"t":"바람이 약할수록 에너지가 더 많이 만들어진다","mis":"SC5-2-u4-X02"},{"t":"날개가 멈춰도 에너지는 똑같다","mis":"SC5-2-u4-X01"},{"t":"바람과 날개는 아무 상관이 없다","mis":"SC5-2-u4-X03"}],"explanation":["바람이 약해요.","날개가 천천히 돌아요.","에너지가 덜 생겨요."],"asset":{"type":"passage","lines":["배에서 내리자 언덕 위 풍력 발전기의 긴 날개 세 개가 돌고 있었다.","우리는 풍력 발전 모형에 머리 말리개 바람을 보냈다.","날개가 빨리 돌자 전구에 불이 켜졌다.","해설사: 「바람이 약한 날엔 날개가 천천히 돌아요.」"],"title":"① 첫날 — 바람의 섬에 도착"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_a#10','sci',5,2,'u4','','g5_2_sci_u4_review_a','unit_review','SC5-2-u4-C5',2,'mc','auto','누리반 탐방 일지 ②의 세 자원에서 함께 알 수 있는 것은 어느 것인가요?',ARRAY['SC5-2-u4-X11','SC5-2-u4-X09','SC5-2-u4-X10']::text[],false,'{"seq":10,"concept":"SC5-2-u4-C5","difficulty":2,"kind":"mc","stem":"누리반 탐방 일지 ②의 세 자원에서 함께 알 수 있는 것은 어느 것인가요?","options":[{"t":"자원은 한정되어 있거나 다시 생기는 데 오래 걸려 계속 쓰기 어렵다","correct":true},{"t":"섬의 자원은 끝없이 쓸 수 있다","mis":"SC5-2-u4-X11"},{"t":"물만 아끼면 된다","mis":"SC5-2-u4-X09"},{"t":"돌은 곧 다시 생긴다","mis":"SC5-2-u4-X10"}],"explanation":["물·나무·돌을 봐요.","모두 한정돼요.","계속 쓰기 어려워요."],"asset":{"type":"passage","lines":["섬 사람들은 우물물과 빗물을 모아 쓴다.","뒷산 나무로 집을 지었는데, 다시 자라려면 오래 걸린다고 한다.","옛 돌 광산은 묻혀 있던 돌이 바닥나 문을 닫았다.","섬마을 이장님: 「캔은 꼭 분리배출해요.」"],"title":"② 첫날 오후 — 섬의 자원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
